"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { createPortal } from "react-dom";
import {
  useDataGridActions,
  useDataGridInternalActions,
  useDataGridActiveCell,
  useDataGridReadOnly,
  useDataGridRowCount,
  useDataGridRowIds,
  useDataGridRowMarkers,
  useDataGridRowMoveAnnouncement,
  useDataGridRowReorderEnabled,
  useDataGridStoreApi,
  type AnyColumnDef,
} from "./store";
import { useRowWindow } from "./virtualization/use-row-window";
import { useCanvasOffset } from "./virtualization/use-scroll-snapshot";
import { useDataGridRootContext, type RenderedColumn } from "./layout-context";
import { DataGridRow } from "./row";
import { DataGridOverlays } from "./overlays";
import { predictBlockTarget, useRowReorder } from "./rows/use-row-reorder";
import { CompactSelection } from "./selection";
import type { CompactSelectionLike } from "./types";
import { isReorderMarkerMode } from "./rows/marker-width";
import { FLASH_KEYFRAMES } from "./cell";
import { createRowElementRegistry } from "./row-element-registry";
import { GRID_LAYER } from "./layers";
import { gridAttrSelector } from "./data-attributes";
import { isDev } from "./is-dev";

/** Real-index `[min, max+1)` bounds of the currently rendered UNPINNED columns.
 * Overlay segmentation clamps its unpinned segment to this, so it never reaches off-screen track
 * positions the virtualized window did not render. An empty window collapses to a zero-width range. */
function unpinnedWindowRange(
  renderedColumns: readonly RenderedColumn[],
  pins: readonly (AnyColumnDef["pin"] | undefined)[],
): { start: number; end: number } {
  let min = Infinity;
  let max = -Infinity;
  for (const { index } of renderedColumns) {
    if (pins[index] !== undefined) continue;
    if (index < min) min = index;
    if (index > max) max = index;
  }
  return Number.isFinite(min) ? { start: min, end: max + 1 } : { start: 0, end: 0 };
}

let warnedRowCountMismatch = false;

/** Dev-only: warn once when the rendered row set is not exactly the virtualized range plus the off-window active row. */
function warnRowCountMismatch(indicesLength: number, expected: number, start: number, end: number, activeRowOffWindow: boolean): void {
  if (indicesLength === expected || warnedRowCountMismatch) return;
  warnedRowCountMismatch = true;
  console.warn(
    `gridcn: rendered row count (${indicesLength}) does not match the expected window size (${expected}) — start=${start} end=${end} activeRowOffWindow=${activeRowOffWindow}.`,
  );
}

// Firefox gives an element taller than about 17.9 million px a height of 0; Chromium clamps at 33.5 million.
const BROWSER_HEIGHT_LIMIT_WARN_PX = 17_800_000;
const CHROMIUM_HEIGHT_LIMIT_PX = 33_554_400;

function warnHeightLimit(rowCount: number, rowHeight: number): void {
  // Two significant digits, so a large row height still names a nonzero row count.
  const roundDown = (px: number) => {
    const rows = Math.floor(px / rowHeight);
    const step = 10 ** Math.max(0, Math.floor(Math.log10(Math.max(rows, 1))) - 1);
    return Math.floor(rows / step) * step;
  };
  const firefoxRows = roundDown(BROWSER_HEIGHT_LIMIT_WARN_PX);
  const chromiumRows = roundDown(CHROMIUM_HEIGHT_LIMIT_PX);
  console.warn(
    `gridcn: ${rowCount} rows at ${rowHeight}px need ${rowCount * rowHeight}px of scroll height, which is above the browser height limit (about 17.9 million px in Firefox, 33.5 million px in Chromium). Firefox shows no scroll range above about ${firefoxRows.toLocaleString("en-US")} rows at this row height. Chromium cannot reach the rows past about ${chromiumRows.toLocaleString("en-US")}. See the virtualization docs page.`,
  );
}

/** First child of the rows canvas: its layout effect runs before the row cells', so child effects and measurements see the canvas at its final offset. */
// The scroll element arrives as a prop: a memoized anchor re-renders when it attaches.
function CanvasOffsetAnchor({ scrollElement, baseOffset }: { scrollElement: HTMLElement | null; baseOffset: number }): ReactNode {
  const anchorRef = useRef<HTMLStyleElement>(null);
  useCanvasOffset(scrollElement, anchorRef, baseOffset);
  return <style ref={anchorRef}>{FLASH_KEYFRAMES}</style>;
}

/** Props for {@link DataGridBody}. */
export type DataGridBodyProps = {
  /** Merged onto the rows-canvas element (the transformed canvas holding the virtualized rows and overlays, not the scroll root). */
  className?: string;
};

const GRID_ORIGIN_MARGIN_ROWS = 96;

/** Renders only the virtualized rows for the current scroll position, plus the active row so focus survives scrolling it out of view. */
export function DataGridBody({ className }: DataGridBodyProps): ReactNode {
  const {
    scrollRef,
    renderedColumns,
    rowHeight,
    headerHeight,
    headerRowCount,
    pinnedTopHeight,
    pinnedBottomHeight,
    pinnedTopCount,
    template,
    layout,
    interaction,
    getRowClassName,
    getCellClassName,
    renderMarker,
  } = useDataGridRootContext();
  const readOnly = useDataGridReadOnly();
  const storeApi = useDataGridStoreApi();
  const rowMarkers = useDataGridRowMarkers();
  const rowCount = useDataGridRowCount();
  const activeCell = useDataGridActiveCell();
  // Data row 0 starts below the header AND any pinned-top band (shrunken effective viewport);
  // the pinned-bottom band shrinks the window's bottom edge the same way.
  const effectiveHeaderHeight = headerHeight + pinnedTopHeight;
  const { start, end, windowTop, measured, element: scrollElement } = useRowWindow(scrollRef, {
    rowCount,
    rowHeight,
    dataRowTop: effectiveHeaderHeight,
    bottomInset: pinnedBottomHeight,
  });

  const warnedHeightLimitRef = useRef(false);
  useEffect(() => {
    if (warnedHeightLimitRef.current || !isDev() || rowCount * rowHeight <= BROWSER_HEIGHT_LIMIT_WARN_PX) return;
    warnedHeightLimitRef.current = true;
    warnHeightLimit(rowCount, rowHeight);
  }, [rowCount, rowHeight]);

  // Fires post-commit, never during render — DataGridBody already re-renders every window tick
  // regardless (it calls useRowWindow directly), so this adds no extra subscription and can't
  // affect the single-flushSync-per-tick scroll commit (the effect runs after that commit, on its
  // own microtask-free schedule). Gated on [start, end] identity so it fires once on mount and
  // again only when the committed range actually moved, never on a same-window scroll tick.
  //
  // `!measured` skips the pre-heal render: useRowWindow heals the no-element fallback to the real
  // window in a pre-paint layout-effect flush, so the fixed {0, min(rowCount,30)} fallback and the
  // real window are two distinct committed ranges; without this guard this fired on both on every
  // mount — the fallback is never a range a consumer (e.g. data-grid-lazy's fetch-on-window)
  // should act on in the first place.
  // The callback is read off the store at fire time (not a dep), so an identity change never re-fires it — only a range change does.
  const lastFiredRangeRef = useRef<{ start: number; end: number } | null>(null);
  useEffect(() => {
    if (!measured) return;
    const last = lastFiredRangeRef.current;
    if (last && last.start === start && last.end === end) return;
    lastFiredRangeRef.current = { start, end };
    storeApi.getState().onRenderedRowsChange?.({ start, end });
  }, [start, end, measured, storeApi]);

  // A naive "clear then repopulate" would blank the body for a frame on every window shift.
  // Rows are keyed by getRowId and mapped straight from viewRowIndices, so keyed reconciliation
  // unmounts only the rows that left the range and mounts only the rows that entered it; the
  // rows common to both windows never unmount.
  const viewRowIndices = useMemo(() => {
    const indices: number[] = [];
    for (let i = start; i < end; i++) indices.push(i);
    // the active row always renders, even off-window, so focus survives scroll
    const activeRowOffWindow = activeCell !== null && (activeCell.row < start || activeCell.row >= end) && activeCell.row < rowCount;
    if (activeRowOffWindow) indices.push(activeCell.row);

    // Dev-only invariant: the rendered set must be exactly computeWindow's [start,end) plus the
    // off-window active row, never more/fewer — catches a regression that silently drops or
    // duplicates rows.
    if (isDev()) {
      const expected = end - start + (activeRowOffWindow ? 1 : 0);
      warnRowCountMismatch(indices.length, expected, start, end, activeRowOffWindow);
    }
    return indices;
  }, [start, end, activeCell, rowCount]);

  // Rows are memoized by getRowId, not viewRowIndex, so sort/filter/insert/delete reuses the right DOM row.
  const rowIds = useDataGridRowIds(viewRowIndices);

  // Keyed by getRowId (the row's own React key), so a row kept across a shift is found by
  // identity, not array position. Separate module: the render-time callback lookup reads Maps —
  // a ref read in render bails the React Compiler (see row-element-registry.ts).
  const rowRegistry = useMemo(() => createRowElementRegistry(), []);

  // Rows place at gridRowStart = viewRowIndex - gridOrigin + 1. The origin trails the window and
  // only rebases once the window drifts out of its band, so a small window shift leaves surviving
  // rows untouched (an inline-style write restyles the whole row). The canvas translate absorbs the offset.
  const [originBase, setOriginBase] = useState(0);
  const rebaseOrigin = start < originBase || start - originBase > 2 * GRID_ORIGIN_MARGIN_ROWS;
  const rebasedOrigin = Math.max(0, start - GRID_ORIGIN_MARGIN_ROWS);
  if (rebaseOrigin) setOriginBase(rebasedOrigin);
  const trailingOrigin = rebaseOrigin ? rebasedOrigin : originBase;

  // An active row just above the origin extends the origin down to it; the canvas translate absorbs that.
  const gridOrigin = activeCell ? Math.max(Math.min(trailingOrigin, activeCell.row), trailingOrigin - GRID_ORIGIN_MARGIN_ROWS) : trailingOrigin;
  const effectiveWindowTop = windowTop - (start - gridOrigin) * rowHeight;
  // Firefox clamps grid lines to 10,000, so a far off-window active row parks at an off-screen line
  // at least a margin away from the window instead of its true one.
  const lastGridLine = end - gridOrigin + GRID_ORIGIN_MARGIN_ROWS;
  const gridLine = (viewRowIndex: number) => Math.min(Math.max(viewRowIndex - gridOrigin + 1, 1), lastGridLine);
  rowRegistry.setLineBounds(gridOrigin, lastGridLine);

  // Drag-to-reorder rows: one shared instance for the whole body (one indicator, one gesture),
  // mirroring how DataGridHeader owns useColumnReorder for its headers.
  const actions = useDataGridActions();
  const internalActions = useDataGridInternalActions();
  const rowReorderEnabled = useDataGridRowReorderEnabled();
  // the gesture lives on the marker's reorder family only — plain number/checkbox/both markers
  // stay pure row-select surfaces (see RowMarkersMode), so a selection drag never reorders.
  const rowReorderArmed = rowReorderEnabled && isReorderMarkerMode(rowMarkers);
  const reorderAnnouncement = useDataGridRowMoveAnnouncement();
  // A `role="status"` region may not live inside role="grid" (only row/rowgroup are allowed
  // children — axe's aria-required-children), so the announcement portals to <body> after mount;
  // the gate keeps SSR output free of the portal node.
  const [announcementTarget, setAnnouncementTarget] = useState<HTMLElement | null>(null);
  useEffect(() => {
    setAnnouncementTarget(document.body);
  }, []);

  /** Resolves the data row (and its above/below half) under a client point, for the reorder drag's live drop target. */
  const hitTestRow = useCallback((clientX: number, clientY: number) => {
    const el = document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(`[role="row"]${gridAttrSelector("rowIndex")}`);
    if (!el) return null;
    const row = Number(el.dataset["gridRowIndex"]);
    if (!Number.isFinite(row)) return null;
    const rect = el.getBoundingClientRect();
    const position: "before" | "after" = clientY < rect.top + rect.height / 2 ? "before" : "after";
    return { row, position };
  }, []);

  const onRowReorder = useCallback(
    (dragged: CompactSelectionLike, over: number, position: "before" | "after") => {
      const rows = dragged.toArray();
      actions.reorderRows(rows, predictBlockTarget(rows, over, position));
    },
    [actions],
  );

  const getDragRows = useCallback(
    (pressedRow: number) => {
      const checked = storeApi.getState().selection.rows;
      return checked.hasIndex(pressedRow) ? checked : CompactSelection.fromSingleSelection(pressedRow);
    },
    [storeApi],
  );

  const rowReorder = useRowReorder({
    enabled: rowReorderArmed,
    hitTestRow,
    onReorder: onRowReorder,
    getDragRows,
    getScrollElement: () => scrollRef.current,
  });

  // The single row-reorder drop-indicator line, grid-placed on the boundary row's track in the
  // canvas (same coordinate math as the rows' own imperative gridRowStart writes).
  const rowDropIndicator = useMemo<CSSProperties | null>(() => {
    const drag = rowReorder.dragState;
    if (!drag || drag.overRow === null) return null;
    const boundary = drag.position === "before" ? drag.overRow : drag.overRow + 1;
    return {
      gridRowStart: boundary - gridOrigin + 1,
      gridColumn: "1 / -1",
      position: "relative",
      alignSelf: "start",
      height: 2,
      zIndex: GRID_LAYER.overlay,
      pointerEvents: "none",
      backgroundColor: "var(--color-primary)",
    };
  }, [rowReorder.dragState, gridOrigin]);

  // Writes gridRowStart straight into each row's DOM node, bypassing React for this value.
  // The body re-renders every window tick anyway, so the write costs nothing extra, and
  // DataGridRow stays memoized without windowStart in its props.
  useLayoutEffect(() => {
    for (let i = 0; i < viewRowIndices.length; i++) {
      // i < viewRowIndices.length by loop condition
      const viewRowIndex = viewRowIndices[i]!;
      const key = rowIds[i] ?? viewRowIndex;
      const el = rowRegistry.elements.get(key);
      const value = String(gridLine(viewRowIndex));
      if (el && el.style.gridRowStart !== value) el.style.gridRowStart = value;
    }
  });

  // Drop flash keys whose rows left the rendered window — a remounted cell would otherwise replay
  // its one-shot pulse on scroll-back while the key is still live (the pulse is viewport-scoped by design).
  useEffect(() => {
    if (!measured) return;
    internalActions._pruneFlashingCells(viewRowIndices);
  }, [measured, viewRowIndices, internalActions]);

  const canvasBaseOffset = effectiveWindowTop + effectiveHeaderHeight;

  const canvasStyle: CSSProperties = {
    position: "absolute",
    insetBlockStart: 0,
    insetInlineStart: 0,
    display: "grid",
    gridTemplateColumns: template,
    gridAutoRows: `${rowHeight}px`,
    // Horizontal only: the vertical offset is the imperative `translate`,
    // because a per-tick change of an inherited custom property restyles every cell.
    translate: `0 ${canvasBaseOffset}px`,
    // --grid-dir signs the X term: transforms are physical while RTL tracks mirror.
    transform: "translate3d(calc(var(--grid-dir, -1) * var(--grid-scroll-left, 0px)), 0, 0)",
  };

  return (
    <>
      <div style={canvasStyle} className={className} data-grid-rows-canvas="" data-grid-window-start={start} data-grid-window-end={end}>
        <CanvasOffsetAnchor scrollElement={scrollElement} baseOffset={canvasBaseOffset} />
        {viewRowIndices.map((viewRowIndex, i) => {
          const key = rowIds[i] ?? viewRowIndex;
          return (
            <DataGridRow
              key={key}
              viewRowIndex={viewRowIndex}
              rowId={rowIds[i]}
              renderedColumns={renderedColumns}
              layout={layout}
              readOnly={readOnly}
              rowMarkers={rowMarkers}
              onMarkerPointerDown={interaction.onMarkerPointerDown}
              onMarkerCheckboxPointerDown={interaction.onMarkerCheckboxPointerDown}
              onMarkerReorderPointerDown={rowReorder.onMarkerDragPointerDown}
              renderMarker={renderMarker}
              isRowReorderDragging={rowReorder.dragState?.rows.hasIndex(viewRowIndex) ?? false}
              rowRef={rowRegistry.getCallback(key)}
              getGridLine={rowRegistry.gridLine}
              ariaRowIndexOffset={pinnedTopCount + headerRowCount - 1}
              getRowClassName={getRowClassName}
              getCellClassName={getCellClassName}
            />
          );
        })}
        <DataGridOverlays
          windowStart={gridOrigin}
          rowCount={viewRowIndices.length}
          // contiguous rendered span for clamping; an appended off-window active row lies outside it
          clampRowStart={start}
          clampRowEnd={end}
          // total visible columns (real index space), not the rendered window size — bands and
          // pin-zone segmentation must span the FULL grid width
          colCount={layout.pins.length}
          colOffset={layout.markerWidth > 0 ? 2 : 1}
          pinTrack={{
            pins: layout.pins,
            trackLefts: layout.trackLefts,
            trackRights: layout.trackRights,
            renderedUnpinnedRange: unpinnedWindowRange(renderedColumns, layout.pins),
          }}
        />
        {rowDropIndicator && <div data-grid-drop-indicator="" aria-hidden="true" style={rowDropIndicator} />}
      </div>
      {announcementTarget &&
        createPortal(
          <div aria-live="polite" role="status" className="sr-only">
            {reorderAnnouncement}
          </div>,
          announcementTarget,
        )}
    </>
  );
}

import type { ComponentType } from "react";
import type { AnyColumnDef } from "../store/types";
import type { CellType, CellTypeValueInput, FilterOperator, FilterValueInputProps } from "../types";
import type { CellValidate } from "../validation/validate-cell";

/** Text/general operators offered for every column type. */
export const TEXT_FILTER_OPERATORS: readonly FilterOperator[] = [
  "contains",
  "notContains",
  "equals",
  "notEquals",
  "startsWith",
  "endsWith",
  "empty",
  "notEmpty",
];

/** Set-membership operators for types with a bounded set of distinct values. */
export const SET_FILTER_OPERATORS: readonly FilterOperator[] = ["isAnyOf", "isNoneOf"];

/** Comparison operators added only for orderable types (gt/lt only for number/date). */
export const COMPARISON_FILTER_OPERATORS: readonly FilterOperator[] = ["gt", "gte", "lt", "lte", "isBetween"];

/**
 * The operator list for a type name whose cell type declares no `filter.operators`: comparisons
 * and set operators for number and date, set operators for select and text, text operators otherwise.
 */
export function operatorsForColumnType(columnType: string | undefined): FilterOperator[] {
  if (columnType === "number" || columnType === "date") return [...TEXT_FILTER_OPERATORS, ...COMPARISON_FILTER_OPERATORS, ...SET_FILTER_OPERATORS];
  if (columnType === "select" || columnType === "text" || columnType === undefined) return [...TEXT_FILTER_OPERATORS, ...SET_FILTER_OPERATORS];
  return [...TEXT_FILTER_OPERATORS];
}

/** `column.filterOperators ?? cellType.filter.operators ??` the type-name default, without set operators when a custom `filterMatch` cannot evaluate them. */
export function resolveFilterOperators<TData = unknown, TValue = unknown, TOptions = unknown>(
  column: AnyColumnDef,
  cellType: CellType<TData, TValue, TOptions> | undefined,
): readonly FilterOperator[] {
  const declared = column.filterOperators ?? cellType?.filter?.operators;
  if (declared) return declared;
  const defaults = operatorsForColumnType(column.type);
  const hasCustomMatcher = Boolean(column.filterMatch ?? cellType?.filter?.match);
  return hasCustomMatcher ? defaults.filter((operator) => !SET_FILTER_OPERATORS.includes(operator)) : defaults;
}

/** Whether the column is filterable and offers a set operator, which is what the header filter needs. */
export function offersSetFilter(column: AnyColumnDef, cellType: CellType | undefined): boolean {
  if (column.filterable === false) return false;
  const operators = resolveFilterOperators(column, cellType);
  return SET_FILTER_OPERATORS.some((operator) => operators.includes(operator));
}

/** The filter row's value widget: `cellType.filter.valueInput`, else the type-name default. */
export function resolveFilterValueInput<TData = unknown, TValue = unknown, TOptions = unknown>(
  column: AnyColumnDef,
  cellType: CellType<TData, TValue, TOptions> | undefined,
): CellTypeValueInput | ComponentType<FilterValueInputProps> {
  const declared = cellType?.filter?.valueInput;
  if (declared) return declared;
  if (column.type === "number" || column.type === "date") return column.type;
  if (column.type === "checkbox") return "boolean";
  if (column.type === "select") return "choices";
  return "text";
}

/**
 * `column.validate ?? cellType.validate` — the single resolution every validation path uses.
 * Generic over the cell type's params so a specialized `CellType<TData, TValue, TOptions>`
 * is accepted without an erasure cast.
 */
export function resolveColumnValidate<TData = unknown, TValue = unknown, TOptions = unknown>(
  column: AnyColumnDef,
  cellType?: CellType<TData, TValue, TOptions>,
): CellValidate {
  // the TValue-narrowed function is safe to treat as the unknown-input CellValidate — validation always receives the cell's own value
  return column.validate ?? (cellType?.validate as CellValidate);
}

import { cn } from "@/lib/utils";

/**
 * Shared display span: truncates and honors the type's text alignment. `align` names are reading
 * relative, not physical — `"right"` is the END of the reading direction, so a right-aligned
 * numeric column hugs the inline end in both LTR and RTL.
 */
export function CellSpan({ text, align }: { text: string; align?: "left" | "right" | "center" }) {
  return (
    <span
      className={cn(
        "block w-full truncate",
        align === "right" && "text-end",
        align === "center" && "text-center",
      )}
    >
      {/* <bdi> isolates the value's own bidi run so mixed-script data shapes correctly, without the
          box taking that run's direction — `dir="auto"` here would resolve a Latin value to `ltr`
          and re-resolve this span's `text-align: start` to the physical LEFT, stranding cell text
          on the wrong side of an RTL grid while the header mirrored correctly. */}
      <bdi>{text}</bdi>
    </span>
  );
}

import type { CellOptionsOf, CellType, CellTypeKey, CellValueOf } from "../types";
import { textCellType } from "./text";
import { numberCellType } from "./number";
import { checkboxCellType } from "./checkbox";
import { selectCellType } from "./select";
import { dateCellType } from "./date";
import { urlCellType } from "./url";
import { longTextCellType } from "./long-text";

export { textCellType } from "./text";
export { numberCellType } from "./number";
export { checkboxCellType } from "./checkbox";
export { selectCellType } from "./select";
export { dateCellType } from "./date";
export { urlCellType } from "./url";
export { longTextCellType } from "./long-text";
export { safeHref } from "./safe-href";

/**
 * The seven built-in keys, deliberately DECOUPLED from `CellTypeKey` (which is
 * `keyof GridCellTypes` and grows with consumer augmentation). Keeping this
 * union literal means the `satisfies` below only ever checks these five
 * built-in entries — a consumer's `declare module` augmentation adds a key to
 * `GridCellTypes`/`CellTypeKey` without requiring the shipped `cellTypes`
 * object to provide an implementation for it.
 */
type BuiltinCellTypeKey = "text" | "number" | "checkbox" | "select" | "date" | "url" | "longText";

/** A `CellType` for one {@link BuiltinCellTypeKey}, with its exact value/options shape. */
type CellTypeFor<K extends BuiltinCellTypeKey> = CellType<unknown, CellValueOf<K>, CellOptionsOf<K>>;

/** Built-in cell-type registry keyed by {@link BuiltinCellTypeKey}; consumers merge in custom types alongside these. */
export const cellTypes = {
  text: textCellType,
  number: numberCellType,
  checkbox: checkboxCellType,
  select: selectCellType,
  date: dateCellType,
  url: urlCellType,
  longText: longTextCellType,
} satisfies { [K in BuiltinCellTypeKey]: CellTypeFor<K> };

/**
 * Defines a custom cell type with the one compile-time check a plain object can't give: `key`
 * must be a registered {@link CellTypeKey} (your `GridCellTypes` module augmentation) and the
 * type's value/options must match that key's declared shape, so a typo in a key or a drifted
 * `GridCellTypes` entry fails at the definition, not at every column that uses the type.
 * Zero runtime cost — the entry is returned as-is, ready for the `cellTypes` registry.
 */
export function defineCellType<K extends CellTypeKey>(
  key: K,
  type: CellType<unknown, CellValueOf<K>, CellOptionsOf<K>>,
): CellType<unknown, CellValueOf<K>, CellOptionsOf<K>> {
  return type;
}

import { useEffect } from "react";
import { CheckIcon } from "lucide-react";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { GRID_ATTR } from "../data-attributes";

function CheckboxCell({ value, column }: CellRenderProps<unknown, boolean>) {
  if (value == null) return null;
  // display-only: the interaction layer toggles via commitCellValue, so the box never receives events
  // plain span, not the base-ui control: one mounts per row per window commit, and its state machine and effects cost more than the visual
  return (
    <span className="flex size-full items-center justify-center">
      <span
        role="checkbox"
        aria-checked={value ? "true" : "false"}
        aria-label={column.headerText ?? (typeof column.header === "string" ? column.header : column.id)}
        data-checked={value || undefined}
        className="pointer-events-none flex size-4 shrink-0 items-center justify-center rounded-none border border-input dark:bg-input/30 data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground dark:data-checked:bg-primary"
        {...{ [GRID_ATTR.checkboxBox]: "" }}
      >
        {value ? <CheckIcon className="size-3.5" /> : null}
      </span>
    </span>
  );
}

/** `CellType` requires an `Editor`, but `startEditing` skips `activate` types: this one only cancels a session opened directly through the store. */
function CheckboxEditor({ cancel }: CellEditorProps<unknown, boolean>) {
  const committed = useCommitGuard();
  useEffect(() => {
    if (!committed.tryCommit()) return;
    cancel();
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return null;
}

/** Truthy tokens accepted by the checkbox type's `fromText` (paste/import), case-insensitive. */
const CHECKBOX_TRUE_TOKENS = new Set(["true", "1", "yes", "x", "on"]);

/** `checkbox`: fromText accepts a small truthy-token set; clipboard round-trips as "true"/"false". */
export const checkboxCellType: CellType<unknown, boolean, GridCellTypes["checkbox"]["options"]> = {
  Cell: CheckboxCell,
  Editor: CheckboxEditor,
  toText: (value) => (value ? "true" : "false"),
  fromText: (text) => CHECKBOX_TRUE_TOKENS.has(text.trim().toLowerCase()),
  clearValue: () => false,
  isEmpty: (value) => value == null,
  compare: (a, b) => Number(a) - Number(b),
  align: "center",
  // the edit gestures toggle in place instead of opening an editor (the type owns the gesture, not the name)
  activate: (value) => !value,
  filter: { valueInput: "boolean" },
};

import { toSafeText } from "./safe-text";
import { useEffect, useRef, useState, type KeyboardEvent } from "react";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { COMPARISON_FILTER_OPERATORS, SET_FILTER_OPERATORS, TEXT_FILTER_OPERATORS } from "./capabilities";
import { displayText } from "./display-text";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { useCellTextInsets } from "../interaction/use-cell-editor";
import { isComposingKey } from "../interaction/is-composing-key";
import { useDataGridLabels } from "../store";
import { columnLabelText } from "../columns/column-format-helpers";

/** Calendar-validity probe for an ISO-shaped `yyyy-mm-dd`: UTC so no time-zone can shift a day; `setUTCFullYear` (unlike the `Date.UTC` constructor) maps 0-99 to themselves, so `0026-01-01` stays 0026. */
function isRealIsoDate(iso: string): boolean {
  const [year, month, day] = iso.split("-").map(Number) as [number, number, number];
  const probe = new Date(0);
  probe.setUTCFullYear(year, month - 1, day);
  return probe.getUTCFullYear() === year && probe.getUTCMonth() === month - 1 && probe.getUTCDate() === day;
}

const MONTH_NAME_PREFIXES = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];

/** True when the input itself names the parsed year, month, and day, so `Date` did not roll an invalid day into the next month. */
function inputNamesDate(input: string, year: number, month: number, day: number): boolean {
  const numbers = (input.match(/\d+/g) ?? []).map(Number);
  const take = (matches: (n: number) => boolean): boolean => {
    const at = numbers.findIndex(matches);
    if (at === -1) return false;
    numbers.splice(at, 1);
    return true;
  };
  if (!take((n) => n === year) && !take((n) => n < 100 && n === year % 100)) return false;
  if (!take((n) => n === day)) return false;
  const namedMonths = new Set((input.toLowerCase().match(/[a-z]+/g) ?? []).map((word) => word.slice(0, 3)).filter((prefix) => MONTH_NAME_PREFIXES.includes(prefix)));
  if (namedMonths.size > 1) return false;
  return take((n) => n === month) || namedMonths.has(MONTH_NAME_PREFIXES[month - 1]!);
}

// anchored time grammar: hh:mm[:ss[.f]] [AM|PM] [Z | [GMT|UTC]+hh[:]mm] [(zone name)]; the lookbehind keeps whitespace runs linear
const TIME_PART_RE = /(?:[Tt]|(?<![\s,]),?\s+)\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?(?:\s*[AaPp][Mm])?(?:\s*(?:[Zz]|(?:GMT|UTC)?[+-]\d{2}:?\d{2}))?(?:\s*\([^()]*\))?$/;
const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

/** Normalizes any Date-parseable input to its ISO `yyyy-mm-dd` date part; null when unparseable, calendar-invalid, or out of range. A datetime stores its local calendar day. */
function toIsoDatePart(input: string, options?: GridCellTypes["date"]["options"]): string | null {
  const trimmed = input.trim();
  if (trimmed === "") return null;
  // the written date, without its time part, is what must be a real calendar day
  const written = trimmed.replace(TIME_PART_RE, "");
  let isoDate: string;
  if (ISO_DATE_RE.test(written) && written === trimmed) {
    // the shape check is not a calendar check — 2026-02-30 matches it and must not commit
    if (!isRealIsoDate(trimmed)) return null;
    isoDate = trimmed;
  } else {
    if (ISO_DATE_RE.test(written) && !isRealIsoDate(written)) return null;
    const parsed = new Date(trimmed);
    if (Number.isNaN(parsed.getTime())) return null;
    const writtenDate = new Date(written);
    if (Number.isNaN(writtenDate.getTime())) return null;
    if (!inputNamesDate(written, writtenDate.getFullYear(), writtenDate.getMonth() + 1, writtenDate.getDate())) return null;
    // use local getters, not toISOString(), so a locale-parsed date (local midnight) doesn't shift a day across UTC
    const year = String(parsed.getFullYear()).padStart(4, "0");
    const month = String(parsed.getMonth() + 1).padStart(2, "0");
    const day = String(parsed.getDate()).padStart(2, "0");
    isoDate = `${year}-${month}-${day}`;
  }
  if (options?.min !== undefined && isoDate < options.min) return null;
  if (options?.max !== undefined && isoDate > options.max) return null;
  return isoDate;
}

/** Parses an ISO `yyyy-mm-dd` date part as a local-midnight `Date` for the Calendar; null for anything else. */
function isoDatePartToLocalDate(isoDate: string | null): Date | undefined {
  if (isoDate == null || !/^\d{4}-\d{2}-\d{2}$/.test(isoDate)) return undefined;
  // regex above guarantees exactly 3 numeric "-"-separated parts
  const [year, month, day] = isoDate.split("-").map(Number) as [number, number, number];
  return new Date(year, month - 1, day);
}

/** Local-midnight `Date` back to its ISO `yyyy-mm-dd` part (mirrors `toIsoDatePart`'s local-getter approach). */
function localDateToIsoDatePart(date: Date): string {
  const year = String(date.getFullYear()).padStart(4, "0");
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** Formatters keyed by serialized options, so a re-created column literal reuses one (build ~38us, reuse ~0.7us). */
const dateFormatterCache = new Map<string, Intl.DateTimeFormat>();

function getDateFormatter(locale: string, format: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(format)}`;
  let formatter = dateFormatterCache.get(key);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, format);
    dateFormatterCache.set(key, formatter);
  }
  return formatter;
}

/** Formats an ISO date part per the column's `displayFormat`/`locale`, falling back to the raw ISO text. */
function formatDateDisplay(value: string | null, options?: GridCellTypes["date"]["options"]): string {
  const text = toSafeText(value);
  if (!options?.displayFormat) return text;
  const date = isoDatePartToLocalDate(text);
  if (!date) return text;
  // pinned default: server and browser Intl defaults can differ -> SSR hydration mismatch
  return getDateFormatter(options.locale ?? "en-US", options.displayFormat).format(date);
}

function DateCell({ value, options }: CellRenderProps<unknown, string | null, GridCellTypes["date"]["options"]>) {
  return <CellSpan text={displayText(dateCellType, value, options)} align="right" />;
}

/** Popover + Calendar (shadcn date-picker pattern): opens on edit start; picking a date commits and stays; a small typed-input above the calendar accepts ISO or Date.parse-able text with Enter to commit. */
function DateEditor({
  value,
  options,
  onChange,
  commit,
  cancel,
  column,
  pending,
  rejectionCount,
}: CellEditorProps<unknown, string | null, GridCellTypes["date"]["options"]>) {
  const labels = useDataGridLabels();
  const inputRef = useRef<HTMLInputElement>(null);
  const { triggerRef, measure } = useCellTextInsets();
  const [text, setText] = useState(dateCellType.toText(value));
  const [open, setOpen] = useState(true);
  const committed = useCommitGuard();

  // Re-arm on each rejection, not on pending->false (that also fires on the cancel right before unmount); see CellEditorProps.rejectionCount.
  const lastRejectionCount = useRef(rejectionCount ?? 0);
  useEffect(() => {
    if ((rejectionCount ?? 0) !== lastRejectionCount.current) committed.reset();
    lastRejectionCount.current = rejectionCount ?? 0;
  }, [rejectionCount, committed]);

  useEffect(() => {
    const el = inputRef.current;
    if (!el) return;
    el.focus({ preventScroll: true });
    const end = el.value.length;
    el.setSelectionRange(end, end);
  }, []);

  const commitValue = (nextValue: string | null, movement?: { dx: number; dy: number }) => {
    if (!committed.tryCommit()) return;
    onChange(nextValue);
    commit(movement);
  };

  return (
    <Popover
      open={open}
      onOpenChange={(next, details) => {
        if (!next && details.reason === "escape-key" && isComposingKey(details.event)) {
          details.cancel();
          return;
        }
        setOpen(next);
        if (!next && committed.tryCommit()) cancel();
      }}
    >
      <PopoverTrigger
        nativeButton={false}
        render={<span ref={triggerRef} className="block w-full min-w-0 truncate text-end" />}
      >
        {displayText(dateCellType, value, options)}
      </PopoverTrigger>
      <PopoverContent
        data-grid-cell-editor=""
        align="start"
        alignOffset={() => -measure().start}
        sideOffset={() => measure().textBottomToCellBottom}
        className="w-auto p-0 data-open:animate-none data-closed:animate-none"
        onKeyDown={(e: KeyboardEvent<HTMLDivElement>) => {
          if (e.key === "Escape" && !isComposingKey(e)) {
            if (committed.tryCommit()) cancel();
          }
        }}
      >
        <div className="p-2 pb-0">
          <Input
            ref={inputRef}
            value={text}
            // readOnly, not disabled: a disabled input swallows Escape while an async validation is pending.
            readOnly={pending}
            // ISO date text is direction-neutral, so it must not inherit the grid's layout direction.
            dir="auto"
            placeholder={labels.grid.datePlaceholder}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
              // Enter or Escape during IME composition confirms or cancels the composition, not the edit.
              if (isComposingKey(e)) return;
              if (e.key === "Enter") {
                commitValue(dateCellType.fromText(text, options), { dx: 0, dy: 1 });
              } else if (e.key === "Escape") {
                if (committed.tryCommit()) cancel();
              }
            }}
            aria-label={columnLabelText(column)}
            className="h-8 w-full border-none bg-transparent px-2 shadow-none outline-none focus-visible:ring-0"
          />
        </div>
        <Calendar
          mode="single"
          selected={isoDatePartToLocalDate(value)}
          defaultMonth={isoDatePartToLocalDate(value)}
          onSelect={(date) => {
            if (!date) return;
            commitValue(localDateToIsoDatePart(date), { dx: 0, dy: 0 });
          }}
        />
      </PopoverContent>
    </Popover>
  );
}

/** `date`: ISO `yyyy-mm-dd` storage; fromText accepts ISO or any Date.parse-able string, normalized and range-checked against min/max. */
export const dateCellType: CellType<unknown, string | null, GridCellTypes["date"]["options"]> = {
  Cell: DateCell,
  Editor: DateEditor,
  numeric: true,
  filter: { operators: [...TEXT_FILTER_OPERATORS, ...COMPARISON_FILTER_OPERATORS, ...SET_FILTER_OPERATORS], valueInput: "date" },
  toText: (value) => toSafeText(value),
  toDisplayText: (value, options) => formatDateDisplay(value, options),
  fromText: (text, options) => toIsoDatePart(text, options),
  clearValue: () => null,
  isEmpty: (value) => value == null,
  compare: (a, b) => {
    if (a == null && b == null) return 0;
    if (a == null) return -1;
    if (b == null) return 1;
    return a < b ? -1 : a > b ? 1 : 0;
  },
  align: "right",
};

/** The only protocols a cell link may use; a type cannot widen the list. */
const SAFE_HREF_PROTOCOLS = new Set(["http:", "https:", "mailto:"]);

/** Bounds the input before parsing, so one huge stored value cannot force a URL parse per cell render. */
const MAX_SAFE_HREF_LENGTH = 2_048;

/**
 * Resolves a candidate link to a safe href, or `null` when it may not be rendered or opened.
 * Only `http:`, `https:`, and `mailto:` survive. The input is parsed with `new URL` without a
 * base, so relative (`//evil`) and scheme-less values fail; `javascript:`, `data:`, `file:`, an
 * over-long input, and a parse failure (NUL-injected schemes) all return `null`. The normalized
 * `url.href` is returned, never the raw text.
 */
export function safeHref(raw: string): string | null {
  if (raw.length > MAX_SAFE_HREF_LENGTH) return null;
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return null;
  }
  if (!SAFE_HREF_PROTOCOLS.has(url.protocol)) return null;
  return url.href;
}

import { Input } from "@/components/ui/input";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { TEXT_FILTER_OPERATORS } from "./capabilities";
import { safeHref } from "./safe-href";
import { displayText } from "./display-text";
import { toSafeText } from "./safe-text";
import { CELL_INPUT_CLASS, useCellEditor } from "../interaction/use-cell-editor";

// One window.open-style opening context for every cell link; the same attributes the `openLink`
// action passes to window.open.
const LINK_OPEN_ATTRIBUTES = {
  target: "_blank",
  rel: "noopener noreferrer nofollow",
  referrerPolicy: "no-referrer",
} as const;

function UrlCell({ value, options }: CellRenderProps<unknown, string | null, GridCellTypes["url"]["options"]>) {
  const text = displayText(urlCellType, value, options);
  const href = urlCellType.href?.(value, options) ?? null;
  if (href === null) return <CellSpan text={text} />;
  // Not a tab stop: grid focus is roving (one focusable cell); alt+Enter (openLink) opens the active link.
  return (
    <a href={href} tabIndex={-1} draggable={false} {...LINK_OPEN_ATTRIBUTES} className="block w-full truncate text-primary underline">
      <bdi>{text}</bdi>
    </a>
  );
}

function UrlEditor(props: CellEditorProps<unknown, string | null, GridCellTypes["url"]["options"]>) {
  const { ref, ...bindings } = useCellEditor(props, { toDraft: urlCellType.toText, toValue: urlCellType.fromText });
  return <Input ref={ref} {...bindings} className={CELL_INPUT_CLASS} />;
}

/** `url`: the stored value IS the URL — toText/copy/export/edit stay the URL; a value failing the safeHref allow-list renders as plain text. `options.label` maps the URL to the shown link text only. */
export const urlCellType: CellType<unknown, string | null, GridCellTypes["url"]["options"]> = {
  Cell: UrlCell,
  Editor: UrlEditor,
  filter: { operators: TEXT_FILTER_OPERATORS, valueInput: "text" },
  toText: (value) => toSafeText(value).trim(),
  toDisplayText: (value, options) => {
    const url = toSafeText(value).trim();
    return options?.label ? options.label(url) : url;
  },
  href: (value) => {
    const url = toSafeText(value).trim();
    return url === "" ? null : safeHref(url);
  },
  fromText: (text) => text.trim(),
  clearValue: () => null,
  isEmpty: (value) => value == null || value === "",
  compare: (a, b) => (a ?? "").localeCompare(b ?? ""),
};

import { toSafeText } from "./safe-text";
import { useCallback, useEffect, useRef, useState, type KeyboardEvent } from "react";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { TEXT_FILTER_OPERATORS } from "./capabilities";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { useCellTextInsets } from "../interaction/use-cell-editor";
import { isComposingKey } from "../interaction/is-composing-key";
import { columnLabelText } from "../columns/column-format-helpers";
import { displayText } from "./display-text";

/** Rendered text is capped so one huge stored value cannot stall layout. */
const LONG_TEXT_DISPLAY_LIMIT = 500;

/** The editor textarea's `maxLength` and the type's default `validate` bound when a column sets no `maxLength` of its own. */
export const LONG_TEXT_DEFAULT_MAX_LENGTH = 100_000;

function LongTextCell({ value, options }: CellRenderProps<unknown, string, GridCellTypes["longText"]["options"]>) {
  return <CellSpan text={displayText(longTextCellType, value, options)} />;
}

/** Popover + textarea (the date editor's pattern): the cell stays one line, the editor takes a real multi-line surface. Outside press commits the draft; Escape cancels. */
function LongTextEditor({
  value,
  options,
  onChange,
  commit,
  cancel,
  column,
  pending,
  rejectionCount,
}: CellEditorProps<unknown, string, GridCellTypes["longText"]["options"]>) {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const { triggerRef, measure } = useCellTextInsets();
  const [text, setText] = useState(longTextCellType.toText(value));
  const [open, setOpen] = useState(true);
  const committed = useCommitGuard();

  // Re-arm on each rejection, not on pending->false (that also fires on the cancel right before unmount); see CellEditorProps.rejectionCount.
  const lastRejectionCount = useRef(rejectionCount ?? 0);
  useEffect(() => {
    if ((rejectionCount ?? 0) !== lastRejectionCount.current) committed.reset();
    lastRejectionCount.current = rejectionCount ?? 0;
  }, [rejectionCount, committed]);

  // The portal commits its content one render after mount; a mount effect would read a null ref.
  const setTextareaRef = useCallback((el: HTMLTextAreaElement | null) => {
    textareaRef.current = el;
    if (!el) return;
    // first line sits on the display text, so opening the editor moves nothing
    const { start, top } = measure();
    el.style.padding = `${top}px ${start}px`;
    el.focus({ preventScroll: true });
    const end = el.value.length;
    el.setSelectionRange(end, end);
  }, [measure]);

  const commitValue = (nextValue: string, movement?: { dx: number; dy: number }) => {
    if (!committed.tryCommit()) return;
    onChange(nextValue);
    commit(movement);
  };

  const insertLineBreak = () => {
    const el = textareaRef.current;
    const start = el?.selectionStart ?? text.length;
    const end = el?.selectionEnd ?? text.length;
    setText(text.slice(0, start) + "\n" + text.slice(end));
    // restore the caret after React re-renders the controlled value
    requestAnimationFrame(() => el?.setSelectionRange(start + 1, start + 1));
  };

  return (
    <Popover
      open={open}
      onOpenChange={(next, details) => {
        if (!next && details.reason === "escape-key" && isComposingKey(details.event)) {
          details.cancel();
          return;
        }
        setOpen(next);
        if (!next) {
          // Escape cancels the edit; any other close (outside press) commits the draft.
          // commitValue owns the one-shot guard; cancel is idempotent.
          if (details.reason === "escape-key") cancel();
          else commitValue(longTextCellType.fromText(text), { dx: 0, dy: 0 });
        }
      }}
    >
      <PopoverTrigger nativeButton={false} render={<span ref={triggerRef} className="block w-full min-w-0 truncate" />}>
        {displayText(longTextCellType, value, options)}
      </PopoverTrigger>
      <PopoverContent
        data-grid-cell-editor=""
        // Base UI's open-focus wins the rAF race and resets the caret; the mount effect owns focus.
        initialFocus={false}
        align="start"
        alignOffset={() => -measure().start}
        sideOffset={() => -measure().textBottomToCellTop}
        className="w-100 rounded-none p-0 data-open:animate-none data-closed:animate-none"
        onKeyDown={(e: KeyboardEvent<HTMLDivElement>) => {
          if (e.key === "Escape" && !isComposingKey(e) && committed.tryCommit()) cancel();
        }}
      >
        <textarea
          ref={setTextareaRef}
          value={text}
          // readOnly, not disabled: a disabled textarea swallows Escape while an async validation is pending.
          readOnly={pending}
          dir="auto"
          aria-multiline
          aria-label={columnLabelText(column)}
          maxLength={options?.maxLength ?? LONG_TEXT_DEFAULT_MAX_LENGTH}
          placeholder={options?.placeholder}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e: KeyboardEvent<HTMLTextAreaElement>) => {
            if (isComposingKey(e)) return;
            if (e.key !== "Enter") return;
            e.preventDefault();
            if (e.shiftKey || e.altKey) insertLineBreak();
            else commitValue(longTextCellType.fromText(text), { dx: 0, dy: 1 });
          }}
          className="block max-h-75 min-h-37.5 w-full resize-none overflow-y-auto border-none bg-transparent text-[length:inherit] shadow-none outline-none"
        />
      </PopoverContent>
    </Popover>
  );
}

/** `longText`: multi-line value stored verbatim; the cell renders the first 500 characters with line breaks as spaces, the editor is a popover textarea. The type's default `validate` cannot see column `options`, so it bounds at {@link LONG_TEXT_DEFAULT_MAX_LENGTH} — a column with a custom `maxLength` declares its own `validate` for the non-editor paths. */
export const longTextCellType: CellType<unknown, string, GridCellTypes["longText"]["options"]> = {
  Cell: LongTextCell,
  Editor: LongTextEditor,
  filter: { operators: TEXT_FILTER_OPERATORS, valueInput: "text" },
  toText: (value) => toSafeText(value),
  toDisplayText: (value) => toSafeText(value).slice(0, LONG_TEXT_DISPLAY_LIMIT).replace(/\r\n|\r|\n/g, " "),
  fromText: (text) => text,
  clearValue: () => "",
  isEmpty: (value) => value == null || value === "",
  compare: (a, b) => toSafeText(a).localeCompare(toSafeText(b)),
  validate: (value) =>
    toSafeText(value).length > LONG_TEXT_DEFAULT_MAX_LENGTH ? `Too long: max ${LONG_TEXT_DEFAULT_MAX_LENGTH} characters` : null,
};

import type { CellType } from "../types";
import { toSafeText } from "./safe-text";

/** Generic display-text resolution: any {@link CellType} may define `toDisplayText` for a formatted read view; falls back to `toText`. Clipboard/export always call `toText` directly, never this. */
export function displayText<TValue, TOptions>(
  cellType: Pick<CellType<unknown, TValue, TOptions>, "toText" | "toDisplayText">,
  value: TValue,
  options?: TOptions,
): string {
  return (cellType.toDisplayText ?? cellType.toText)(value, options);
}

/** The cell type's `toText` for clipboard and export; a throwing `toText` falls back to the value's safe text. */
export function exportText<TValue, TOptions>(
  cellType: Pick<CellType<unknown, TValue, TOptions>, "toText">,
  value: TValue,
  options?: TOptions,
): string {
  try {
    return toSafeText(cellType.toText(value, options));
  } catch {
    return toSafeText(value);
  }
}

/** `String(value ?? "")` that falls back to `""` when the conversion throws (null-prototype objects, deeply nested arrays). */
export function toSafeText(value: unknown): string {
  if (value == null) return "";
  try {
    return String(value);
  } catch {
    return "";
  }
}

/** Domain barrel — built-in cell type registry and shared editor pieces. */
export {
  cellTypes,
  textCellType,
  numberCellType,
  checkboxCellType,
  selectCellType,
  dateCellType,
  urlCellType,
  longTextCellType,
  safeHref,
} from "./cell-types";
export { displayText } from "./display-text";
export { CellSpan } from "./cell-span";

import { toSafeText } from "./safe-text";
import type { KeyboardEvent } from "react";
import { Input } from "@/components/ui/input";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { COMPARISON_FILTER_OPERATORS, SET_FILTER_OPERATORS, TEXT_FILTER_OPERATORS } from "./capabilities";
import { CELL_INPUT_CLASS, useCellEditorDraft } from "../interaction/use-cell-editor";
import { cn } from "@/lib/utils";
import { isComposingKey } from "../interaction/is-composing-key";
import { displayText } from "./display-text";
import { warnDev } from "../store/commit";

const DECIMAL_NUMBER = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i;

/** Normalizes a comma decimal separator to a dot so `Number()` can parse locales pasted verbatim. */
function normalizeNumberText(text: string): string {
  return text.trim().replace(",", ".");
}

/** Clamps a parsed number into the column's configured min/max, if any. */
function clampNumber(value: number, options?: GridCellTypes["number"]["options"]): number {
  let clamped = value;
  if (options?.min !== undefined) clamped = Math.max(clamped, options.min);
  if (options?.max !== undefined) clamped = Math.min(clamped, options.max);
  return clamped;
}

/** Moves the decimal point by `places` through the exponent, so `1.005` shifts to exactly `100.5`. */
function shiftDecimal(value: number, places: number): number {
  const [mantissa = "0", exponent = "0"] = String(value).split("e");
  return Number(`${mantissa}e${Number(exponent) + places}`);
}

/** Rounds to the column's configured decimal precision, if any; never returns `-0`. */
function roundToDecimals(value: number, options?: GridCellTypes["number"]["options"]): number {
  if (options?.decimals === undefined || !Number.isFinite(value)) return value;
  const rounded = shiftDecimal(Math.round(shiftDecimal(value, options.decimals)), -options.decimals);
  return rounded === 0 ? 0 : rounded;
}

/** Count of fractional digits in a finite number's shortest decimal form. */
function decimalPlaces(value: number): number {
  const [mantissa = "", exponent = "0"] = String(value).split("e");
  const fraction = mantissa.split(".")[1]?.length ?? 0;
  return Math.min(100, Math.max(0, fraction - Number(exponent)));
}

/** Pulls a bound into the column's decimals, keeping a bound that already sits on that grid. */
function boundToDecimals(bound: number, decimals: number, inward: (n: number) => number): number {
  const rounded = Math.round(bound * 10 ** decimals) / 10 ** decimals;
  if (rounded === bound) return rounded;
  return inward(bound * 10 ** decimals) / 10 ** decimals;
}

/** Clamps into min/max, pulling each bound inward to the column's decimals so the result never exceeds it. */
function clampToDecimals(value: number, options: GridCellTypes["number"]["options"], decimals: number): number {
  let clamped = value;
  if (options?.min !== undefined) clamped = Math.max(clamped, boundToDecimals(options.min, decimals, Math.ceil));
  if (options?.max !== undefined) clamped = Math.min(clamped, boundToDecimals(options.max, decimals, Math.floor));
  return clamped;
}

/** One `Intl.NumberFormat` per (format options object, locale, decimals); the options object as WeakMap key keeps a per-render literal GC-able. */
const numberFormatterCache = new WeakMap<Intl.NumberFormatOptions, Map<string, Intl.NumberFormat>>();
/** Options objects whose `new Intl.NumberFormat` threw; the dev fallback warning fires once per object. */
const warnedNumberFormats = new WeakSet<Intl.NumberFormatOptions>();

function getNumberFormatter(format: Intl.NumberFormatOptions, locale: string, decimals: number | undefined): Intl.NumberFormat {
  const perOptions = numberFormatterCache.get(format) ?? new Map<string, Intl.NumberFormat>();
  const key = `${locale}|${decimals ?? ""}`;
  let formatter = perOptions.get(key);
  if (!formatter) {
    // decimals fills in fraction digits the format left open (0.25 under style:"percent" + decimals:2 renders 25.00%)
    const effective =
      decimals !== undefined && format.minimumFractionDigits === undefined && format.maximumFractionDigits === undefined
        ? { ...format, minimumFractionDigits: decimals, maximumFractionDigits: decimals }
        : format;
    formatter = new Intl.NumberFormat(locale, effective);
    perOptions.set(key, formatter);
    numberFormatterCache.set(format, perOptions);
  }
  return formatter;
}

function NumberCell({ value, options }: CellRenderProps<unknown, number | null, GridCellTypes["number"]["options"]>) {
  return <CellSpan text={displayText(numberCellType, value, options)} align="right" />;
}

function NumberEditor(props: CellEditorProps<unknown, number | null, GridCellTypes["number"]["options"]>) {
  const { value, options, pending } = props;
  // seed with the same options the cell display formats with, so the draft matches what the cell showed
  const { bindings, setDraft } = useCellEditorDraft(props, {
    toDraft: (draftValue) => numberCellType.toText(draftValue, options),
    toValue: (draft) => numberCellType.fromText(draft, options),
  });
  const { ref, onKeyDown, ...rest } = bindings;

  return (
    <Input
      ref={ref}
      {...rest}
      onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
        if (e.key !== "ArrowUp" && e.key !== "ArrowDown") {
          onKeyDown(e);
          return;
        }
        if (pending || isComposingKey(e)) return;
        // step the draft; a cleared draft falls back to the committed value, so an empty
        // cell with a null value has no step base and stays untouched
        const base = numberCellType.fromText(rest.value, options) ?? value;
        if (base === null) return;
        e.preventDefault();
        const configuredStep = options?.step ?? 1;
        const step = options?.decimals !== undefined ? Math.max(configuredStep, 10 ** -options.decimals) : configuredStep;
        const raw = base + (e.key === "ArrowUp" ? step : -step);
        const clamped = clampNumber(raw, options);
        // float drift (0.1 + 0.2) rounds away at the finer of the draft's and the step's precision
        const next =
          options?.decimals !== undefined
            ? clampToDecimals(roundToDecimals(raw, options), options, options.decimals)
            : clamped === raw
              ? Number(raw.toFixed(Math.max(decimalPlaces(base), decimalPlaces(step))))
              : clamped;
        setDraft(String(next));
      }}
      className={cn(CELL_INPUT_CLASS, "text-end [appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none")}
    />
  );
}

/** `number`: comma-decimal-tolerant parse, min/max clamp, decimals rounding, plain `String()` serialization; `options.format` renders display-only locale formatting — copy, export, and the editor keep the raw value. */
export const numberCellType: CellType<unknown, number | null, GridCellTypes["number"]["options"]> = {
  Cell: NumberCell,
  Editor: NumberEditor,
  numeric: true,
  filter: { operators: [...TEXT_FILTER_OPERATORS, ...COMPARISON_FILTER_OPERATORS, ...SET_FILTER_OPERATORS], valueInput: "number" },
  toText: (value, options) => {
    if (value == null) return "";
    return toSafeText(options?.decimals !== undefined ? roundToDecimals(value, options) : value);
  },
  toDisplayText: (value, options) => {
    if (value == null) return "";
    if (!options?.format) return numberCellType.toText(value, options);
    try {
      return getNumberFormatter(options.format, options.locale ?? "en-US", options.decimals).format(roundToDecimals(value, options));
    } catch (error) {
      // invalid options (e.g. style:"currency" without currency) — raw text, one dev warning per options object;
      // engines differ on the thrown type (V8/Node: TypeError, spec: RangeError)
      if ((error instanceof RangeError || error instanceof TypeError) && !warnedNumberFormats.has(options.format)) {
        warnedNumberFormats.add(options.format);
        warnDev(`invalid number format options, showing the raw value: ${error instanceof Error ? error.message : String(error)}`);
      }
      return numberCellType.toText(value, options);
    }
  },
  fromText: (text, options) => {
    const normalized = normalizeNumberText(text);
    if (normalized === "") return null;
    if (!DECIMAL_NUMBER.test(normalized)) return null;
    const parsed = Number(normalized);
    if (!Number.isFinite(parsed)) return null;
    if (options?.decimals !== undefined) return clampToDecimals(roundToDecimals(parsed, options), options, options.decimals);
    return clampNumber(parsed, options);
  },
  clearValue: () => null,
  isEmpty: (value) => value == null,
  compare: (a, b) => {
    if (a == null && b == null) return 0;
    if (a == null) return -1;
    if (b == null) return 1;
    return a - b;
  },
  align: "right",
};

import { useEffect, useRef, useState } from "react";
import { toSafeText } from "./safe-text";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { CellEditorProps, CellRenderProps, CellType, GridCellTypes } from "../types";
import { CellSpan } from "./cell-span";
import { SET_FILTER_OPERATORS, TEXT_FILTER_OPERATORS } from "./capabilities";
import { useCommitGuard } from "../interaction/use-commit-guard";
import { columnLabelText } from "../columns/column-format-helpers";
import { defaultCompareText } from "../sort-filter/default-compare-text";

type Choice = { value: string; label: string };
type ChoiceIndex = { byValue: Map<string, Choice>; byLowerLabel: Map<string, Choice> };

// Per-cell lookups (search, display, copy) stay O(1); keyed by array identity, so an in-place mutation of `choices` is not seen.
const choiceIndexes = new WeakMap<readonly Choice[], ChoiceIndex>();

function choiceIndex(choices: readonly Choice[]): ChoiceIndex {
  let index = choiceIndexes.get(choices);
  if (index) return index;
  index = { byValue: new Map(), byLowerLabel: new Map() };
  for (const choice of choices) {
    if (!index.byValue.has(choice.value)) index.byValue.set(choice.value, choice);
    const lower = choice.label.toLowerCase();
    if (!index.byLowerLabel.has(lower)) index.byLowerLabel.set(lower, choice);
  }
  choiceIndexes.set(choices, index);
  return index;
}

// Sort ranks by label per `choices` array; equal labels share a rank, so a sort compares integers.
const choiceRanks = new WeakMap<readonly Choice[], Map<string, number>>();

function choiceRank(choices: readonly Choice[]): Map<string, number> {
  let ranks = choiceRanks.get(choices);
  if (ranks) return ranks;
  ranks = new Map();
  const byLabel = [...choices].sort((a, b) => defaultCompareText(a.label, b.label));
  let rank = -1;
  let previous: string | undefined;
  for (const choice of byLabel) {
    if (previous === undefined || defaultCompareText(previous, choice.label) !== 0) rank++;
    previous = choice.label;
    if (!ranks.has(choice.value)) ranks.set(choice.value, rank);
  }
  choiceRanks.set(choices, ranks);
  return ranks;
}

/** The choice whose value is `raw`, else the first whose label matches `raw` case-insensitively. */
function findChoice(choices: readonly Choice[] | undefined, raw: string): Choice | undefined {
  if (!choices) return undefined;
  const index = choiceIndex(choices);
  return index.byValue.get(raw) ?? index.byLowerLabel.get(toSafeText(raw).toLowerCase());
}

function SelectCell({ value, options }: CellRenderProps<unknown, string | null, GridCellTypes["select"]["options"]>) {
  const key = toSafeText(value);
  return <CellSpan text={findChoice(options?.choices, key)?.label ?? key} />;
}

/** Opens on mount; picking an option commits immediately (no separate confirm step). */
function SelectEditor({ value, options, onChange, commit, cancel, column, rejectionCount }: CellEditorProps<unknown, string | null, GridCellTypes["select"]["options"]>) {
  const [open, setOpen] = useState(true);
  const committed = useCommitGuard();

  // Re-arm on each rejection, not on pending->false (that also fires on the cancel right before unmount); see CellEditorProps.rejectionCount.
  const lastRejectionCount = useRef(rejectionCount ?? 0);
  useEffect(() => {
    if ((rejectionCount ?? 0) !== lastRejectionCount.current) committed.reset();
    lastRejectionCount.current = rejectionCount ?? 0;
  }, [rejectionCount, committed]);

  return (
    <Select
      value={value ?? ""}
      open={open}
      onOpenChange={(next) => {
        setOpen(next);
        // picking an option also closes the select, firing this with `next: false` after commit already ran
        if (!next && committed.tryCommit()) cancel();
      }}
      onValueChange={(next) => {
        if (!committed.tryCommit()) return;
        onChange(next === "" || next == null ? null : next);
        commit({ dx: 0, dy: 0 });
      }}
    >
      <SelectTrigger aria-label={columnLabelText(column)} className="size-full justify-start rounded-none border-none p-0 text-sm shadow-none outline-none focus-visible:ring-0 [&_svg]:hidden">
        <SelectValue placeholder="" />
      </SelectTrigger>
      <SelectContent data-grid-cell-editor="">
        {options?.choices.map((choice) => (
          <SelectItem key={choice.value} value={choice.value}>
            {choice.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

/** `select`: fromText resolves pasted option values first, then labels (case-insensitive) so pasted labels round-trip. */
export const selectCellType: CellType<unknown, string | null, GridCellTypes["select"]["options"]> = {
  Cell: SelectCell,
  Editor: SelectEditor,
  toText: (value, options) => {
    if (value == null) return "";
