      const rankA = ranks.get(a);
      const rankB = ranks.get(b);
      if (rankA !== undefined && rankB !== undefined) return rankA - rankB;
    }
    return defaultCompareText(findChoice(choices, a)?.label ?? a, findChoice(choices, b)?.label ?? b);
  },
  align: "left",
};

