/**
 * Public clipboard triggers for use outside native clipboard events (e.g. a context menu's
 * Copy/Cut/Paste items). Mirrors {@link useGridClipboard}'s native-event pipeline exactly, so
 * behavior stays identical whether the user presses Ctrl+C or clicks a menu item.
 */
export function useDataGridClipboard(options: UseDataGridClipboardOptions = {}): UseDataGridClipboardResult {
  const { sanitizeFormulas } = options;
  const actions = useDataGridActions();
  const internalActions = useDataGridInternalActions();
  const storeApi = useDataGridStoreApi();
  const guard = useBulkGeneration();

  const copy = useCallback((): Promise<"ok" | "fallback" | "failed" | "no-selection"> => {
    const s = storeApi.getState();
    const scope = resolveCopyScope(s);
    if (!scope) return Promise.resolve("no-selection");
    const { text, html } = serializeCells(serializeCopyScope(s, scope), { sanitizeFormulas: sanitizeFormulas ?? s.sanitizeClipboardFormulas });
    return writeToClipboard(text, html);
  }, [storeApi, sanitizeFormulas]);

  const cut = useCallback(async (): Promise<"ok" | "fallback" | "failed" | "no-selection"> => {
    const s = storeApi.getState();
    const scope = resolveCopyScope(s);
    if (!scope) return "no-selection";
    const { text, html } = serializeCells(serializeCopyScope(s, scope), { sanitizeFormulas: sanitizeFormulas ?? s.sanitizeClipboardFormulas });
    const { rowIds, columnIds } = copyScopeCellIds(s, scope);
    const result = await writeToClipboard(text, html);
    // A view rebuild keeps, drops, or collapses the range; a new or cleared range from the user cancels the delete.
    const latest = storeApi.getState();
    const current = latest.selection.current;
    const rebuilt = latest.viewIndex !== s.viewIndex || latest.visibleColumns !== s.visibleColumns;
    const selectionKept = current === s.selection.current || (rebuilt && (current === null || selectionFollowedRebuild(s, latest)));
    if (result !== "failed" && selectionKept) internalActions._deleteCellsById(rowIds, columnIds);
    return result;
  }, [storeApi, internalActions, sanitizeFormulas]);

  const pasteFromClipboard = useCallback(async (): Promise<PasteFromClipboardResult> => {
    let text: string;
    try {
      text = await navigator.clipboard.readText();
    } catch {
      return "permission-denied";
    }
    if (!text) return "empty";
    const s = storeApi.getState();
    const applied = pasteText(s, actions, text, guard, storeApi);
    return applied ? "ok" : "empty";
  }, [storeApi, actions, guard]);

  return useMemo(() => ({ copy, cut, pasteFromClipboard }), [copy, cut, pasteFromClipboard]);
}

"use client";

import { useCallback, useEffect, type RefObject } from "react";
import type { ViewCoord, GridRect } from "../types";
import { getCellValue } from "../columns/column-helpers";
import { isDev } from "../is-dev";
import { gridAttrSelector } from "../data-attributes";
import { closestGridRoot } from "../interaction/closest-grid-root";
import { serializeCells } from "./serialize-cells";
import { parseClipboard } from "./parse-clipboard";
import { useDataGridActions, useDataGridInternalActions, useDataGridStoreApi, type DataGridActions, type DataGridStoreState } from "../store";
import { resolveBulkWrites, type BulkCandidate, type BulkResolution } from "../validation/validate-batch";
import { exportText } from "../cell-types/display-text";
import { resolveColumnValidate } from "../cell-types/capabilities";
import { candidateRowIds, reresolveBulkWrites, snapshotBulkBatch, useBulkGeneration, type BulkGeneration } from "../validation/bulk-generation";

/** Options for {@link useGridClipboard}. */
export type UseGridClipboardOptions = {
  rootRef: RefObject<HTMLElement | null>;
  /** Prefix formula-like cells with `'` in the copied text/plain payload (same opt-in as {@link serializeCells}); default `false` so the grid's own paste round-trip stays byte-identical. */
  sanitizeFormulas?: boolean;
};

/**
 * Copy scope: the primary range if one exists (ignoring the range
 * stack — multi-rect copy is document-scoped to the primary range only), else the selected rows
 * (full width) or selected columns (full height) as their disjoint member lists — a CompactSelection
 * from Ctrl-click is RLE and may hold non-contiguous members, so this must not collapse to a
 * min..max bounding rect (that would silently include unselected rows/columns in between).
 */
export type CopyScope = { kind: "rect"; rect: GridRect } | { kind: "rows"; rows: number[] } | { kind: "columns"; columns: number[] };

/** Resolves the copy scope; returns null when nothing is selected. Exported for direct unit testing; not part of the public hook surface. */
export function resolveCopyScope(s: DataGridStoreState): CopyScope | null {
  if (s.selection.current) return { kind: "rect", rect: s.selection.current.range };
  const rows = s.selection.rows.toArray();
  if (rows.length > 0) return { kind: "rows", rows };
  const cols = s.selection.columns.toArray();
  if (cols.length > 0) return { kind: "columns", columns: cols };
  return null;
}

/** Serializes one view row's `[colStart, colStart + colCount)` slice via each cell type's `toText`. */
function serializeRowSlice(s: DataGridStoreState, viewRow: number, colStart: number, colCount: number): string[] {
  const dataRowIndex = s.viewIndex[viewRow];
  const row = dataRowIndex === undefined ? undefined : s.data[dataRowIndex];
  const cells: string[] = [];
  for (let col = colStart; col < colStart + colCount; col++) {
    const column = s.visibleColumns[col];
    if (!column || row === undefined) {
      cells.push("");
      continue;
    }
    const cellType = s.cellTypes[column.type ?? "text"];
    // explicit TData=unknown: row's `undefined`-narrowed type ({} | null) would otherwise drive inference instead of column's own already-unknown TData.
    const value = getCellValue<unknown, typeof column>(row, column);
    const text = s.processCellForClipboard
      ? s.processCellForClipboard(value, { row, column })
      : (cellType ? exportText(cellType, value, column.options) : "");
    cells.push(text);
  }
  return cells;
}

/** Serializes `rect` to a 2D string grid via each cell type's `toText`, honoring `processCellForClipboard` when provided. */
export function serializeRect(s: DataGridStoreState, rect: GridRect): string[][] {
  const out: string[][] = [];
  for (let viewRow = rect.y; viewRow < rect.y + rect.height; viewRow++) {
    out.push(serializeRowSlice(s, viewRow, rect.x, rect.width));
  }
  return out;
}

/**
 * A copy above this many cells is truncated to the rows that fit — no spreadsheet accepts a
 * clipboard payload this large anyway, and below this cap output is byte-identical to the
 * uncapped path (same precedent as
 * `MAX_SEARCH_MATCHES` in store/compute.ts). 200k cells is generously above any realistic manual
 * copy while still bounding the worst case (a Ctrl+A copy on a 100k-row grid) to a few seconds.
 */
export const MAX_COPY_CELLS = 200_000;

/**
 * Serializes an explicit, disjoint list of view rows against an explicit, disjoint list of view
 * columns — the shared engine for the "rows" (all visible columns) and "columns" (explicit column
 * indices) copy-scope branches. Column + cellType resolution happens once per selected column,
 * hoisted OUTSIDE the row loop, instead of `serializeRowSlice`'s per-(row,col) re-resolution — the
 * columns branch used to call `serializeRowSlice(s, viewRow, col, 1)` once per cell, re-reading
 * `visibleColumns`/`cellTypes` and allocating a throwaway 1-element array every time. Truncates at {@link MAX_COPY_CELLS}.
 */
function serializeDisjointRows(s: DataGridStoreState, rows: readonly number[], cols: readonly number[]): string[][] {
  const resolved = cols.map((col) => {
    const column = s.visibleColumns[col];
    return column ? { column, cellType: s.cellTypes[column.type ?? "text"] } : null;
  });

  const maxRows = cols.length === 0 ? rows.length : Math.max(1, Math.floor(MAX_COPY_CELLS / cols.length));
  const rowCount = Math.min(rows.length, maxRows);
  // parity with the paste cap's dev warn (applyParsedPaste): a truncated copy must be observable
  if (rowCount < rows.length && isDev()) {
    console.warn(`gridcn: copy truncated to ${rowCount} of ${rows.length} rows (MAX_COPY_CELLS)`);
  }

  const out: string[][] = [];
  for (let r = 0; r < rowCount; r++) {
    const viewRow = rows[r]!; // r < rowCount <= rows.length
    const dataRowIndex = s.viewIndex[viewRow];
    const row = dataRowIndex === undefined ? undefined : s.data[dataRowIndex];
    const cells: string[] = [];
    for (const entry of resolved) {
      if (!entry || row === undefined) {
        cells.push("");
        continue;
      }
      const { column, cellType } = entry;
      // explicit TData=unknown: row's `undefined`-narrowed type ({} | null) would otherwise drive inference instead of column's own already-unknown TData.
      const value = getCellValue<unknown, typeof column>(row, column);
      const text = s.processCellForClipboard
        ? s.processCellForClipboard(value, { row, column })
        : (cellType ? exportText(cellType, value, column.options) : "");
      cells.push(text);
    }
    out.push(cells);
  }
  return out;
}

/** All view-row indices `[0, rowCount)`, as a plain array — the "columns" scope's implicit row list. */
function allViewRows(s: DataGridStoreState): number[] {
  return Array.from({ length: s.viewIndex.length }, (_, i) => i);
}

/**
 * Serializes a copy scope, preserving disjoint row/column membership (a Ctrl-click multi-select
 * copies exactly the selected rows/columns, never the rows/columns in between). All three scopes
 * are capped at {@link MAX_COPY_CELLS}. The rect scope needs the cap too because two-stage Ctrl+A
 * produces a whole-grid rect (selection/select-all-progression.ts), so "visually bounded by what
 * the user dragged" does not bound a select-all copy.
 */
export function serializeCopyScope(s: DataGridStoreState, scope: CopyScope): string[][] {
  if (scope.kind === "rect") {
    const maxRows = Math.max(1, Math.floor(MAX_COPY_CELLS / Math.max(1, scope.rect.width)));
    if (scope.rect.height > maxRows && isDev()) {
      console.warn(`gridcn: copy truncated to ${maxRows} of ${scope.rect.height} rows (MAX_COPY_CELLS)`);
    }
    return serializeRect(s, { ...scope.rect, height: Math.min(scope.rect.height, maxRows) });
  }
  if (scope.kind === "rows") {
    return serializeDisjointRows(
      s,
      scope.rows,
      Array.from({ length: s.visibleColumns.length }, (_, i) => i),
    );
  }
  return serializeDisjointRows(s, allViewRows(s), scope.columns);
}

/**
 * The row and column ids {@link serializeCopyScope} serializes for `scope`, truncation included:
 * cut clears exactly these cells, by identity, never the view positions they had at copy time.
 */
export function copyScopeCellIds(s: DataGridStoreState, scope: CopyScope): { rowIds: string[]; columnIds: string[] } {
  const span = (start: number, count: number): number[] => Array.from({ length: count }, (_, i) => start + i);
  const viewCols: readonly number[] =
    scope.kind === "rect" ? span(scope.rect.x, scope.rect.width) : scope.kind === "rows" ? span(0, s.visibleColumns.length) : scope.columns;
  const maxRows = Math.max(1, Math.floor(MAX_COPY_CELLS / Math.max(1, viewCols.length)));
  const viewRows: readonly number[] =
    scope.kind === "rect"
      ? span(scope.rect.y, Math.min(scope.rect.height, maxRows))
      : (scope.kind === "rows" ? scope.rows : allViewRows(s)).slice(0, maxRows);
  const rowIds: string[] = [];
  for (const viewRow of viewRows) {
    const dataRowIndex = s.viewIndex[viewRow];
    const row = dataRowIndex === undefined ? undefined : s.data[dataRowIndex];
    if (row !== undefined) rowIds.push(s.getRowId(row, dataRowIndex!));
  }
  const columnIds = viewCols.flatMap((col) => {
    const column = s.visibleColumns[col];
    return column ? [column.id] : [];
  });
  return { rowIds, columnIds };
}

/** Writes both `text/plain` (TSV) and `text/html` (table) to a clipboard event's DataTransfer. */
function writeClipboardEvent(event: ClipboardEvent, cells: string[][], sanitizeFormulas?: boolean): void {
  const { text, html } = serializeCells(cells, { sanitizeFormulas });
  event.clipboardData?.setData("text/plain", text);
  event.clipboardData?.setData("text/html", html);
}

/**
 * Single pasted row tiles down to fill a taller target selection height ; otherwise the parsed grid is used as-is.
 * Exported for direct unit testing; not part of the public hook surface.
 */
export function tileToHeight(cells: string[][], height: number): string[][] {
  if (cells.length !== 1 || height <= 1) return cells;
  const onlyRow = cells[0]!; // cells.length === 1 checked above
  return Array.from({ length: height }, () => onlyRow);
}

/** Max cells a single paste may touch — same rationale/precedent as {@link MAX_COPY_CELLS}. */
export const MAX_PASTE_CELLS = 200_000;

/**
 * Truncates a paste grid to the first rows that fit under `maxCells` (row-summed). The paste anchor
 * is the target's top-left, so the HEAD rows are kept — dropping them would silently skip the rows
 * the user intended to paste first. A first row wider than the cap is cropped to it. Below the cap the input is returned unchanged.
 */
export function truncatePasteGrid(cells: string[][], maxCells: number): string[][] {
  let total = 0;
  for (let i = 0; i < cells.length; i++) {
    const row = cells[i]!; // i < cells.length by loop condition
    if (total + row.length > maxCells) return i === 0 ? [row.slice(0, maxCells)] : cells.slice(0, i);
    total += row.length;
  }
  return cells;
}

/**
 * Resolves the paste target: top-left of `current.range`, else the
 * lowest selected column at row 0, else the lowest selected row at col 0. `activeCell` alone isn't
 * enough — selectRow/selectColumn (row-marker/header click) never set it, so a column- or
 * row-only selection needs its own fallback here rather than silently no-op'ing the paste.
 */
export function resolvePasteTarget(s: DataGridStoreState): ViewCoord | null {
  if (s.selection.current) return { col: s.selection.current.range.x, row: s.selection.current.range.y };
  const [firstColumn] = s.selection.columns.toArray();
  if (firstColumn !== undefined) return { col: firstColumn, row: 0 };
  const [firstRow] = s.selection.rows.toArray();
  if (firstRow !== undefined) return { col: 0, row: firstRow };
  return s.activeCell;
}

/** Height (in view rows) of the paste target: current range's height if >1 row, else 1 (anchored expand). */
export function targetHeight(s: DataGridStoreState): number {
  const range = s.selection.current?.range;
  return range && range.height > 1 ? range.height : 1;
}

/**
 * Builds the unvalidated candidate cells for an anchored-expand paste: `cells` written at `target`
 * top-left, clipped at grid bounds, skipping readOnly columns and rows that don't resolve. Values are
 * parsed via `processCellFromClipboard` when provided, else the cell type's `fromText`. Validation is
 * the caller's next step ({@link buildPasteWrites} for the sync answer, `resolveBulkWrites` when a
 * column's schema is async). Exported for direct unit testing; not part of the public hook surface.
 */
export function buildPasteCandidates(s: DataGridStoreState, cells: string[][], target: ViewCoord): BulkCandidate[] {
  const candidates: BulkCandidate[] = [];
  const rowCount = s.viewIndex.length;
  const colCount = s.visibleColumns.length;

  for (let r = 0; r < cells.length; r++) {
    const viewRow = target.row + r;
    if (viewRow >= rowCount) break;
    const dataRowIndex = s.viewIndex[viewRow];
    if (dataRowIndex === undefined) continue;
    const row = s.data[dataRowIndex];
    if (row === undefined) continue;
    const rowId = s.getRowId(row, dataRowIndex);

    const sourceRow = cells[r]!; // r < cells.length by loop condition
    for (let c = 0; c < sourceRow.length; c++) {
      const col = target.col + c;
      if (col >= colCount) break;
      const column = s.visibleColumns[col];
      if (!column) continue;
      if (typeof column.readOnly === "function" ? column.readOnly(row) : Boolean(column.readOnly)) continue;

      const cellType = s.cellTypes[column.type ?? "text"];
      if (!cellType) continue;

      const text = sourceRow[c]!; // c < sourceRow.length by loop condition
      const value = s.processCellFromClipboard
        ? s.processCellFromClipboard(text, { row, column })
        : cellType.fromText(text, column.options);

      candidates.push({ viewRowIndex: viewRow, columnId: column.id, value, validate: resolveColumnValidate(column, cellType), row, rowId });
    }
  }
  return candidates;
}

/**
 * The paste resolution: {@link buildPasteCandidates} validated through {@link resolveBulkWrites}, so
 * the accepted writes plus the rejected cells — synchronously when every touched column validates
 * synchronously, a Promise for the same when one does not. Kept as a named export for consumers and
 * tests that want the pure answer without the store.
 */
export function buildPasteWrites(
  s: DataGridStoreState,
  cells: string[][],
  target: ViewCoord,
): BulkResolution | Promise<BulkResolution> {
  return resolveBulkWrites(buildPasteCandidates(s, cells, target));
}

/**
 * The paste application core (parse -> tile -> processPaste -> writes -> applyCellUpdates),
 * shared by the native `paste` event handler and {@link pasteText} so
 * both funnel through one pipeline. `cells` is already parsed (HTML-table or TSV); returns `false`
 * when there was nothing to paste (empty parse, no target, or `processPaste` vetoed it) so callers
 * can distinguish "nothing happened" from a successful write.
 *
 * A touched column with an ASYNC schema makes the write list a Promise: the batch is held, and the
 * single `applyCellUpdates` runs on resolution — still one commit, one DataChange, still dropping
 * failing cells silently. `guard` then decides whether that resolution may land at all; without one
 * (a direct call in a test) a resolved batch always applies. `true` here means "a paste started",
 * which for an async batch is not yet "cells changed".
 */
function applyParsedPaste(
  s: DataGridStoreState,
  actions: DataGridActions,
  cells: string[][],
  guard?: BulkGeneration,
  storeApi?: { getState: () => DataGridStoreState },
): boolean {
  if (cells.length === 0) return false;
  const target = resolvePasteTarget(s);
  if (!target) return false;

  const tiled = tileToHeight(cells, targetHeight(s));
  const finalCells = s.processPaste ? s.processPaste({ cells: tiled, target }) : tiled;
  if (finalCells === false) return false;

  // Cap AFTER processPaste so a consumer hook cannot re-expand a truncated grid past the bound.
  const cappedCells = truncatePasteGrid(finalCells, MAX_PASTE_CELLS);
  if (cappedCells.length < finalCells.length && isDev()) {
    console.warn(`gridcn: paste truncated to ${cappedCells.length} of ${finalCells.length} rows (MAX_PASTE_CELLS)`);
  }

  const candidates = buildPasteCandidates(s, cappedCells, target);
  const resolution = resolveBulkWrites(candidates);
  if (!(resolution instanceof Promise)) {
    // rejected cells are reported by the write itself (same source, after the write's emit)
    actions.applyCellUpdates(resolution.writes, "paste", resolution.rejected);
    return true;
  }

  const token = guard?.begin();
  const snapshot = snapshotBulkBatch(s, candidateRowIds(s, candidates));
  void resolution.then((resolved) => {
    const current = storeApi?.getState() ?? s;
    if (current.readOnly) return;
    if (guard && token !== undefined && !guard.isCurrent(token, current, snapshot)) return;
    actions.applyCellUpdates(reresolveBulkWrites(current, resolved.writes), "paste", resolved.rejected);
  });
  return true;
}

/**
 * Applies pasted plain text through the same pipeline the native `paste` event uses (parse -> tile
 * -> processPaste -> writes -> applyCellUpdates), for triggers outside a native ClipboardEvent
 * (context-menu Paste, programmatic paste). Text-only — no HTML-table fidelity, since there's no
 * `text/html` payload to prefer; parity with a plain-text native paste. Returns whether a paste
 * started (false when there's no paste target or `processPaste` vetoed it); with an async schema on
 * a touched column the cells commit once it resolves.
 */
export function pasteText(
  s: DataGridStoreState,
  actions: DataGridActions,
  text: string,
  guard?: BulkGeneration,
  storeApi?: { getState: () => DataGridStoreState },
): boolean {
  if (s.editing || s.readOnly) return false;
  return applyParsedPaste(s, actions, parseClipboard({ text }, MAX_PASTE_CELLS), guard, storeApi);
}

/**
 * Whether the listening grid root owns a clipboard event: its origin (read through shadow roots)
 * sits in this grid, not in a nested grid, and is not an editable element a cell renders.
 */
function ownsClipboardEvent(event: ClipboardEvent): boolean {
  const origin = event.composedPath()[0] ?? null;
  const target = origin instanceof Element ? origin : origin instanceof Node ? origin.parentElement : null;
  if (!target || closestGridRoot(target) !== event.currentTarget) return false;
  if (!(target instanceof HTMLElement)) return true;
  const editable = /^(INPUT|SELECT|TEXTAREA)$/.test(target.tagName) || target.isContentEditable;
  return !editable || target.closest(gridAttrSelector("cellEditor")) !== null;
}

/**
 * Wires native `copy`/`cut`/`paste` events to the grid root so OS-native shortcuts and menu
 * actions work. Attached to the root element (not `document`) so
 * multiple grids on one page each own their own clipboard traffic, gated on focus being inside the
 * grid via roving tabindex; inactive while a cell is being edited (the editor owns its own
 * clipboard then), for events from an input or `contenteditable` that a cell renders, and for
 * events from a grid nested in a cell.
 */
export function useGridClipboard(options: UseGridClipboardOptions): void {
  const { rootRef, sanitizeFormulas } = options;
  const actions = useDataGridActions();
  const internalActions = useDataGridInternalActions();
  const storeApi = useDataGridStoreApi();
  // One counter for this grid's paste surface: a second paste supersedes a still-validating first.
  const guard = useBulkGeneration();

  const onCopy = useCallback(
    (event: ClipboardEvent) => {
      const s = storeApi.getState();
      if (s.editing || !ownsClipboardEvent(event)) return;
      const scope = resolveCopyScope(s);
      if (!scope) return;
      event.preventDefault();
      writeClipboardEvent(event, serializeCopyScope(s, scope), sanitizeFormulas ?? s.sanitizeClipboardFormulas);
    },
    [storeApi, sanitizeFormulas],
  );

  const onCut = useCallback(
    (event: ClipboardEvent) => {
      const s = storeApi.getState();
      if (s.editing || !ownsClipboardEvent(event)) return;
      const scope = resolveCopyScope(s);
      if (!scope) return;
      event.preventDefault();
      writeClipboardEvent(event, serializeCopyScope(s, scope), sanitizeFormulas ?? s.sanitizeClipboardFormulas);
      if (s.readOnly) return;
      const { rowIds, columnIds } = copyScopeCellIds(s, scope);
      internalActions._deleteCellsById(rowIds, columnIds);
    },
    [storeApi, internalActions, sanitizeFormulas],
  );

  const onPaste = useCallback(
    (event: ClipboardEvent) => {
      const s = storeApi.getState();
      if (s.editing || s.readOnly || !ownsClipboardEvent(event)) return;
      // resolvePasteTarget gates BEFORE parsing/preventDefault, so a no-target paste (nothing
      // selected/active) leaves the native paste behavior (e.g. into an unrelated focused input) intact.
      if (!resolvePasteTarget(s)) return;
      const html = event.clipboardData?.getData("text/html");
      const text = event.clipboardData?.getData("text/plain");
      const parsed = parseClipboard({ html: html || undefined, text }, MAX_PASTE_CELLS);
      if (parsed.length === 0) return;
      event.preventDefault();
      applyParsedPaste(s, actions, parsed, guard, storeApi);
    },
    [storeApi, actions, guard],
  );

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    root.addEventListener("copy", onCopy);
    root.addEventListener("cut", onCut);
    root.addEventListener("paste", onPaste);
    return () => {
      root.removeEventListener("copy", onCopy);
      root.removeEventListener("cut", onCut);
      root.removeEventListener("paste", onPaste);
    };
  }, [rootRef, onCopy, onCut, onPaste]);
}

import type { ColumnGroupDef } from "../types";

/** Deepest nesting a group tree keeps; a deeper group is dropped with an issue. */
export const MAX_GROUP_DEPTH = 8;
/** Most group nodes and column references one build walks; the rest is ignored with an issue. */
export const MAX_GROUP_NODES = 5000;

type GroupNode = { id: string; def: ColumnGroupDef; parentId: string | null; depth: number };

/** The validated shape of a `columnGroups` prop: which group each column sits in, root-first. */
export type ColumnGroupModel = {
  groups: ReadonlyMap<string, GroupNode>;
  paths: ReadonlyMap<string, readonly string[]>;
  /** The longest group path of any column. */
  depth: number;
  /** Human-readable problems found while validating, for one development warning each. */
  issues: readonly string[];
};

/** One group header cell: the visible columns `[start, end)` that share a group at one level. */
export type HeaderSegment = { groupId: string; start: number; end: number; pin?: "left" | "right"; depth: number };

const NO_PATH: readonly string[] = [];
const EMPTY_ROWS: readonly (readonly HeaderSegment[])[] = [];

export function groupPathOf(model: ColumnGroupModel | null, columnId: string): readonly string[] {
  return model?.paths.get(columnId) ?? NO_PATH;
}

type Frame = { def: ColumnGroupDef; parentId: string | null; depth: number; path: readonly string[] };

/**
 * Validates `defs` against the grid's column ids. Unknown column ids drop, a column listed twice
 * keeps its first group, a repeated or column-colliding group id drops the later group, nesting
 * deeper than {@link MAX_GROUP_DEPTH} drops, and a cyclic object graph is walked once. The walk is
 * iterative and bounded by {@link MAX_GROUP_NODES}. Returns `null` when `defs` is empty, and a
 * model without groups (only its `issues`) when no group keeps a column.
 */
export function buildColumnGroupModel(defs: readonly ColumnGroupDef[] | undefined, columnIds: readonly string[]): ColumnGroupModel | null {
  if (!defs || !Array.isArray(defs as unknown) || defs.length === 0) return null;
  const known = new Set(columnIds);
  const issues: string[] = [];
  const nodes = new Map<string, GroupNode>();
  const paths = new Map<string, readonly string[]>();
  const visited = new Set<object>();
  const stack: Frame[] = [];
  for (let i = defs.length - 1; i >= 0; i--) stack.push({ def: defs[i]!, parentId: null, depth: 0, path: NO_PATH });
  let budget = MAX_GROUP_NODES;
  while (stack.length > 0) {
    const { def, parentId, depth, path } = stack.pop()!;
    if (--budget < 0) {
      issues.push(`columnGroups is larger than ${MAX_GROUP_NODES} entries; the rest is ignored`);
      break;
    }
    if (typeof def !== "object" || def === null || typeof def.id !== "string" || def.id === "" || !Array.isArray(def.children as unknown)) {
      issues.push("a columnGroups entry needs a string id and a children array; it is ignored");
      continue;
    }
    if (visited.has(def)) {
      issues.push(`column group "${def.id}" appears twice in the tree; the second place is ignored`);
      continue;
    }
    visited.add(def);
    if (nodes.has(def.id) || known.has(def.id)) {
      issues.push(`column group id "${def.id}" is not unique across groups and columns; the group is ignored`);
      continue;
    }
    if (depth >= MAX_GROUP_DEPTH) {
      issues.push(`column group "${def.id}" nests deeper than ${MAX_GROUP_DEPTH} levels; it is ignored`);
      continue;
    }
    nodes.set(def.id, { id: def.id, def, parentId, depth });
    const nextPath = [...path, def.id];
    const children = def.children;
    const frames: Frame[] = [];
    for (const child of children) {
      if (--budget < 0) {
        issues.push(`columnGroups is larger than ${MAX_GROUP_NODES} entries; the rest is ignored`);
        stack.length = 0;
        break;
      }
      if (typeof child === "string") {
        if (!known.has(child)) issues.push(`column group "${def.id}" lists unknown column "${child}"; it is ignored`);
        else if (paths.has(child)) issues.push(`column "${child}" is listed in more than one group; the first group wins`);
        else paths.set(child, nextPath);
      } else {
        frames.push({ def: child, parentId: def.id, depth: depth + 1, path: nextPath });
      }
    }
    for (let i = frames.length - 1; i >= 0; i--) stack.push(frames[i]!);
  }
  if (paths.size === 0) return issues.length > 0 ? { groups: new Map(), paths, depth: 0, issues } : null;
  const used = new Set<string>();
  let depth = 0;
  for (const path of paths.values()) {
    if (path.length > depth) depth = path.length;
    for (const id of path) used.add(id);
  }
  const groups = new Map<string, GroupNode>();
  for (const [id, node] of nodes) if (used.has(id)) groups.set(id, node);
  return { groups, paths, depth, issues };
}

/** Whether two models hold the same structure and the same header content (the store keeps the old model when so). */
export function columnGroupModelsEqual(a: ColumnGroupModel | null, b: ColumnGroupModel | null): boolean {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (a.groups.size !== b.groups.size || a.paths.size !== b.paths.size) return false;
  for (const [id, node] of a.groups) {
    const other = b.groups.get(id);
    if (!other || other.parentId !== node.parentId) return false;
    if (other.def.header !== node.def.header || other.def.headerText !== node.def.headerText || other.def.headerClassName !== node.def.headerClassName) return false;
  }
  for (const [id, path] of a.paths) {
    const other = b.paths.get(id);
    if (!other || other.length !== path.length || other.some((g, i) => g !== path[i])) return false;
  }
  return true;
}

function gather(ids: readonly string[], model: ColumnGroupModel, level: number): string[] {
  const slots: (string | string[])[] = [];
  const buckets = new Map<string, string[]>();
  for (const id of ids) {
    const group = model.paths.get(id)?.[level];
    if (group === undefined) {
      slots.push(id);
      continue;
    }
    const bucket = buckets.get(group);
    if (bucket) {
      bucket.push(id);
      continue;
    }
    const created = [id];
    buckets.set(group, created);
    slots.push(created);
  }
  const result: string[] = [];
  for (const slot of slots) {
    if (typeof slot === "string") result.push(slot);
    else for (const id of gather(slot, model, level + 1)) result.push(id);
  }
  return result;
}

/**
 * Makes every group contiguous in `ids`: all members move to the first member's position, in
 * their current relative order, and nested groups repair the same way. Returns `ids` itself when
 * nothing has to move.
 */
export function repairGroupOrder(ids: string[], model: ColumnGroupModel | null): string[];
export function repairGroupOrder(ids: readonly string[], model: ColumnGroupModel | null): readonly string[];
export function repairGroupOrder(ids: readonly string[], model: ColumnGroupModel | null): readonly string[] {
  if (!model || ids.length < 2) return ids;
  const repaired = gather(ids, model, 0);
  for (let i = 0; i < ids.length; i++) if (repaired[i] !== ids[i]) return repaired;
  return ids;
}

function insertAtUnit(rest: string[], moving: readonly string[], unit: readonly string[], position: "before" | "after"): string[] | null {
  const unitSet = new Set(unit);
  let first = -1;
  let last = -1;
  for (let i = 0; i < rest.length; i++) {
    if (!unitSet.has(rest[i]!)) continue;
    if (first === -1) first = i;
    last = i;
  }
  if (first === -1) return null;
  const at = position === "before" ? first : last + 1;
  return [...rest.slice(0, at), ...moving, ...rest.slice(at)];
}

function commonPrefix(a: readonly string[], b: readonly string[]): number {
  let k = 0;
  while (k < a.length && k < b.length && a[k] === b[k]) k++;
  return k;
}

/**
 * Moves column `id` next to `targetId` without leaving its group: a column moves among the members
 * of its own group, or next to a whole sibling group or column of the same parent. Returns `null`
 * when the move would take the column out of its group.
 */
export function moveWithinGroups(orderedIds: readonly string[], model: ColumnGroupModel, id: string, targetId: string, position: "before" | "after"): string[] | null {
  const unit = dropUnit(orderedIds, model, id, targetId);
  if (!unit) return null;
  return insertAtUnit(
    orderedIds.filter((c) => c !== id),
    [id],
    unit,
    position,
  );
}

/**
 * The columns a drop next to `targetId` lands beside when `id` (a column id or a group id) moves:
 * the whole sibling group, or the target column itself. `null` when the move would leave the
 * moving column's group, drop a group onto itself, or leave the group's parent.
 */
export function dropUnit(orderedIds: readonly string[], model: ColumnGroupModel, id: string, targetId: string): string[] | null {
  const node = model.groups.get(id);
  const targetPath = groupPathOf(model, targetId);
  let k: number;
  if (node) {
    if (targetPath.includes(id)) return null;
    k = node.depth;
    if (k > 0 && targetPath[k - 1] !== node.parentId) return null;
  } else {
    const idPath = groupPathOf(model, id);
    k = commonPrefix(idPath, targetPath);
    if (idPath.length > k) return null;
  }
  const unitGroup = targetPath[k];
  return unitGroup === undefined ? [targetId] : orderedIds.filter((c) => model.paths.get(c)?.[k] === unitGroup);
}

/** Whether `columnId` sits inside group `groupId`, at any depth. */
export function isInGroup(model: ColumnGroupModel | null, columnId: string, groupId: string): boolean {
  return groupPathOf(model, columnId).includes(groupId);
}

/**
 * Moves the whole block of group `groupId` next to `targetId`, inside the group's parent. Returns
 * `null` when the target lies inside the moving group or outside the parent group.
 */
export function moveGroupBlock(orderedIds: readonly string[], model: ColumnGroupModel, groupId: string, targetId: string, position: "before" | "after"): string[] | null {
  if (!model.groups.has(groupId)) return null;
  const unit = dropUnit(orderedIds, model, groupId, targetId);
  if (!unit) return null;
  const block = orderedIds.filter((c) => isInGroup(model, c, groupId));
  return insertAtUnit(
    orderedIds.filter((c) => !isInGroup(model, c, groupId)),
    block,
    unit,
    position,
  );
}

/**
 * The group header rows over the visible columns, one array per level (top first), each segment a
 * half-open column range. A segment ends at a group change or a pin zone change. O(columns x depth).
 */
export function computeHeaderRows(
  visibleColumns: readonly { id: string; pin?: "left" | "right" }[],
  model: ColumnGroupModel | null,
): readonly (readonly HeaderSegment[])[] {
  if (!model) return EMPTY_ROWS;
  let depth = 0;
  for (const column of visibleColumns) {
    const length = model.paths.get(column.id)?.length ?? 0;
    if (length > depth) depth = length;
  }
  if (depth === 0) return EMPTY_ROWS;
  const rows: HeaderSegment[][] = [];
  for (let level = 0; level < depth; level++) {
    const row: HeaderSegment[] = [];
    let open: HeaderSegment | null = null;
    for (let index = 0; index < visibleColumns.length; index++) {
      const column = visibleColumns[index]!;
      const groupId = model.paths.get(column.id)?.[level];
      const pin = column.pin === "left" || column.pin === "right" ? column.pin : undefined;
      if (groupId === undefined) {
        open = null;
        continue;
      }
      if (open && open.groupId === groupId && open.pin === pin) {
        open.end = index + 1;
        continue;
      }
      open = { groupId, start: index, end: index + 1, depth: level, ...(pin ? { pin } : {}) };
      row.push(open);
    }
    rows.push(row);
  }
  return rows;
}

import type { ColumnDef } from "../types";

/** Column label for a11y strings: `headerText`, else the string `header`, else the id. Generic over TData/TValue so callers with a concrete `ColumnDef<TData, TValue>` (e.g. a cell editor's `column` prop) don't need a cast to `ColumnDef<unknown, unknown>`. */
export function columnLabelText<TData = never, TValue = unknown>(column: ColumnDef<TData, TValue>): string {
  return column.headerText ?? (typeof column.header === "string" ? column.header : column.id);
}

/** Run-length-encodes consecutive equal widths into `repeat(n, wpx)` grid-template segments. */
export function encodeTemplate(widths: number[]): string {
  const segments: string[] = [];
  let i = 0;
  while (i < widths.length) {
    let j = i + 1;
    while (j < widths.length && widths[j] === widths[i]) j++;
    const count = j - i;
    segments.push(count > 1 ? `repeat(${count}, ${widths[i]}px)` : `${widths[i]}px`);
    i = j;
  }
  return segments.join(" ");
}

import type { AccessorKeyOf, CellOptionsOf, CellTypeKey, CellValueOf, ColumnDef } from "../types";
import { isDev } from "../is-dev";

/** Keys of `T` whose value extends `V` (nullable `V` also matches the non-null key type). */
export type KeysMatching<T, V> = {
  [K in keyof T]-?: T[K] extends V
    ? K
    : null extends V
      ? T[K] extends NonNullable<V>
        ? K
        : never
      : never;
}[keyof T] &
  string;

/**
 * A column definition whose `type` selects a {@link CellTypeKey}, narrowing
 * `options` and the inferred value type (and thus `accessorKey`) through
 * the `GridCellTypes` map. Omitting `type` behaves as `"text"`.
 */
export type TypedColumnDef<TData, K extends CellTypeKey> = Omit<
  ColumnDef<TData, CellValueOf<K>>,
  "type" | "options" | "accessorKey"
> & {
  // `type` must be required for non-text branches, else an untyped column literal
  // structurally matches every branch of AnyTypedColumn (and defaults to "text" at runtime).
  type: K;
  options?: CellOptionsOf<K>;
  accessorKey?: KeysMatching<TData, CellValueOf<K>>;
};

/** `TypedColumnDef` for the default "text" branch, where `type` may be omitted. */
export type TypedTextColumnDef<TData> = Omit<TypedColumnDef<TData, "text">, "type"> & {
  type?: "text";
};

/** A `TypedColumnDef` for some cell-type key, used where the specific `K` need not be named. */
export type AnyTypedColumn<TData> =
  | TypedTextColumnDef<TData>
  | { [K in Exclude<CellTypeKey, "text">]: TypedColumnDef<TData, K> }[Exclude<CellTypeKey, "text">];

/** All keys any `AnyTypedColumn<TData>` branch may carry (for excess-property rejection). */
type KnownColumnKey<TData> = keyof AnyTypedColumn<TData>;

/** Every key of a column literal in `T` that lies outside the known column shape. */
type ExcessColumnKeys<TData, T extends readonly unknown[]> = {
  [I in keyof T]: Exclude<keyof T[I], KnownColumnKey<TData>>;
}[number];

/**
 * Rejects excess properties: generic inference against a union constraint (as `defineColumns`
 * does against `AnyTypedColumn`) skips TypeScript's normal excess-property check on object
 * literals. An unknown key turns this into a required argument, so the call fails to compile and
 * the missing argument's type names the key.
 */
type RejectExcessColumnKeys<TData, T extends readonly unknown[]> = [ExcessColumnKeys<TData, T>] extends [never]
  ? []
  : [unknownColumnKey: `unknown column key: ${ExcessColumnKeys<TData, T> & string}`];

/**
 * Identity helper that gives each column literal in the array its own
 * `TValue`/`options` inference (via `type`) while returning `columns`
 * unchanged at runtime. In dev mode it warns on columns missing both
 * `accessorKey` and `accessorFn` (duplicate ids are warned once per instance
 * by the provider instead).
 */
export function defineColumns<TData>(): <const T extends readonly AnyTypedColumn<TData>[]>(
  columns: T,
  // A check on `columns` itself (`T & ...`) drops callback contextual typing on TypeScript 5.x.
  ...excessKeyCheck: RejectExcessColumnKeys<TData, T>
) => T {
  return (columns, ..._excessKeyCheck) => {
    if (isDev()) {
      for (const column of columns) {
        if (!column.accessorKey && !column.accessorFn) {
          console.warn(`[data-grid] column "${column.id}" has neither accessorKey nor accessorFn`);
        }
      }
    }
    return columns;
  };
}

/**
 * A minimal column shape covering both plain `ColumnDef` and the narrower
 * per-literal type `defineColumns`'s `const` inference produces (which keeps
 * only the accessor fields actually present in the literal, no TValue-bearing
 * member of its own).
 */
export type AccessorLike<TData> = {
  id: string;
  accessorKey?: AccessorKeyOf<TData>;
  accessorFn?: (row: TData) => unknown;
  setValue?: (row: TData, value: never) => TData;
};

/**
 * Resolves the value type a column reads/writes: `accessorFn`'s return type
 * if present, else the field type at `accessorKey`. Mirrors `getCellValue`'s
 * runtime precedence so it works on the narrow literal types `defineColumns`
 * produces (which carry no explicit TValue-bearing member).
 */
export type InferredValue<TData, TCol> = TCol extends { accessorFn: (row: TData) => infer TValue }
  ? TValue
  : TCol extends { accessorKey: infer K extends keyof TData }
    ? TData[K]
    : unknown;

/** Reads a column's value from `row` via `accessorFn`/`accessorKey`. */
export function getCellValue<TData, const TCol extends AccessorLike<TData>>(
  row: TData,
  column: TCol,
): InferredValue<TData, TCol> {
  if (column.accessorFn) return column.accessorFn(row) as InferredValue<TData, TCol>;
  // row as Record: AccessorKeyOf<TData> degrades to a bare `string` when TData=unknown (the
  // erasure-boundary case, see types.ts), which TS can no longer prove indexes `row` — sound because
  // a real (non-unknown) TData's accessorKey is still `keyof TData & string`, indexable directly.
  if (column.accessorKey) return (row as Record<string, unknown>)[column.accessorKey] as InferredValue<TData, TCol>;
  throw new Error(`[data-grid] column "${column.id}" has no accessorKey or accessorFn to read`);
}

/**
 * Writes `value` back onto `row` immutably: `setValue` if provided, else a
 * spread on `accessorKey`. Throws for accessorFn-only columns with no `setValue`.
 */
export function setCellValue<TData, const TCol extends AccessorLike<TData>>(
  row: TData,
  column: TCol,
  value: InferredValue<TData, TCol>,
): TData {
  // value as never: TCol's setValue is typed per-column, but TS can't unify it with InferredValue<TData, TCol> at this generic call site — safe by TCol's own constraint.
  if (column.setValue) return column.setValue(row, value as never);
  if (column.accessorKey) return { ...row, [column.accessorKey]: value };
  throw new Error(`[data-grid] column "${column.id}" is not writable (no setValue or accessorKey)`);
}

/** Domain barrel — column sizing/pinning/reorder/label helpers. */
export {
  defineColumns,
  getCellValue,
  setCellValue,
  type KeysMatching,
  type TypedColumnDef,
  type TypedTextColumnDef,
  type AnyTypedColumn,
  type AccessorLike,
  type InferredValue,
} from "./column-helpers";
export { columnLabelText, encodeTemplate } from "./column-format-helpers";
export { measureTextWidths, measureColumnAutosizeWidth } from "./measure-column-text";
export { pinLeftOffsets, pinRightOffsets } from "./pin-offsets";
export { pinnedInsetStyle } from "./pinned-inset-style";
export { resolveColumnWidth, distributeFlexWidths } from "./resolve-column-width";
export {
  useColumnReorder,
  type ColumnReorderState,
  type ColumnReorderHandlers,
} from "./use-column-reorder";
export {
  useColumnResize,
  type ColumnResizeHandlers,
} from "./use-column-resize";
export {
  DataGridSortIndicator,
  ariaSortFor,
  type DataGridSortIndicatorProps,
} from "./sort-indicator";

import type { AnyColumnDef } from "../store";
import type { AutosizeOptions, CellType, SortSpec } from "../types";
import { isDev } from "../is-dev";
import { offersSetFilter } from "../cell-types/capabilities";
import { displayText } from "../cell-types/display-text";
import { getCellValue } from "./column-helpers";
import { CELL_PADDING, measureTextWidths } from "./measure-column-text";
import { clampColumnWidth } from "./resolve-column-width";

/** Default view rows sampled by one autosize pass. */
export const DEFAULT_AUTOSIZE_SAMPLE_ROWS = 1_000;
/** Hard cap on `AutosizeOptions.sampleRows` (hostile-dataset bound, with the 1,000-char cut). */
export const MAX_AUTOSIZE_SAMPLE_ROWS = 10_000;
/** Texts longer than this are cut before measuring (one 10 MB string cell must not slow a pass). */
const MAX_SAMPLE_TEXT_LENGTH = 1_000;
/** Fixed header allowance for a sorted column: `ms-1` (4px) + the size-3.5 (14px) arrow + room for a 2-digit multi-sort priority number (~10px + 2px gap). */
const SORTED_HEADER_AFFORDANCE = 30;
/** Fixed header allowance for the per-column header-menu trigger: `p-0.5` (2px per side) + a size-3.5 (14px) chevron. */
const HEADER_MENU_AFFORDANCE = 18;
/** Fixed header allowance for the header-filter button, the same size as the header-menu trigger. */
const HEADER_FILTER_AFFORDANCE = 18;

/** The view-shaped subset of store state the engine measures over. */
export type AutosizeState = {
  columns: readonly AnyColumnDef[];
  visibleColumns: readonly AnyColumnDef[];
  hiddenColumns: readonly string[];
  columnWidths: Record<string, number>;
  /** View (display) row order, post sort/filter — the rows the sample walks. */
  viewIndex: number[];
  data: readonly unknown[];
  /** The resolved cell-type registry (display text + value access go through the columns' types). */
  cellTypes: Record<string, CellType>;
  sortState: readonly SortSpec[];
  enableColumnResize: boolean;
  /** A consumer header-menu trigger is rendered (adds the trigger allowance to every measured header). */
  hasHeaderMenu: boolean;
  /** A header-filter button is rendered (adds its allowance to the headers of columns with a set filter). */
  hasHeaderFilter: boolean;
};

/** The mounted view-row window `[start, end)` (the rows the user sees), `null` when nothing is mounted. */
export type AutosizeWindow = { start: number; end: number } | null;

/** Canvas fonts for `measureText`: the body cell font and the header cell font (headers render `font-medium`, so the two differ). */
export type AutosizeFonts = { cellFont: string; headerFont: string };

/**
 * Computes an autosize width for every target column: the widest of (header text + header
 * affordances) and (sampled cell display texts) plus `CELL_PADDING`, clamped through
 * `clampColumnWidth`. Views only: `viewIndex` (sort/filter applied) defines what is measured and
 * lazy holes (`data[viewIndex[i]] === undefined`) are skipped. Sample = `sampleRows` view rows
 * evenly strided across the view plus the mounted window's rows; texts are cut to
 * `MAX_SAMPLE_TEXT_LENGTH` and deduped per column before measuring.
 */
export function computeAutosizeWidths(
  state: AutosizeState,
  fonts: AutosizeFonts,
  window: AutosizeWindow,
  options?: AutosizeOptions,
): Record<string, number> {
  const { columns, visibleColumns, hiddenColumns, viewIndex, data, cellTypes, sortState, enableColumnResize, hasHeaderMenu, hasHeaderFilter } = state;
  const sampleRows = Math.min(Math.max(options?.sampleRows ?? DEFAULT_AUTOSIZE_SAMPLE_ROWS, 1), MAX_AUTOSIZE_SAMPLE_ROWS);
  const includeHeader = options?.includeHeader ?? true;

  let targets: AnyColumnDef[];
  if (options?.columnIds) {
    const byId = new Map(columns.map((column) => [column.id, column] as const));
    targets = [];
    for (const id of options.columnIds) {
      const column = byId.get(id);
      if (!column) {
        if (isDev()) console.warn(`[data-grid] autosizeColumns: unknown column id "${id}"`);
        continue;
      }
      if (hiddenColumns.includes(id) || !enableColumnResize || column.resizable === false) continue;
      targets.push(column);
    }
  } else {
    targets = visibleColumns.filter((column) => enableColumnResize && column.resizable !== false);
  }
  if (targets.length === 0) return {};

  // sample view rows: evenly spread across the whole view, plus the last row and every mounted window row
  const count = viewIndex.length;
  const sampled = new Set<number>();
  const spread = Math.min(sampleRows, count);
  for (let k = 0; k < spread; k++) sampled.add(Math.floor((k * count) / spread));
  if (count > 0) sampled.add(count - 1);
  if (window) {
    for (let i = Math.max(window.start, 0); i < Math.min(window.end, count); i++) sampled.add(i);
  }

  const sortedColumnIds = new Set(sortState.map((spec) => spec.columnId));
  const textFallback = cellTypes["text"]!;
  const result: Record<string, number> = {};
  for (const column of targets) {
    const cellType = cellTypes[column.type ?? "text"] ?? textFallback;
    const cellTexts = new Set<string>();
    for (const row of sampled) {
      const dataRow = viewIndex[row]!;
      const rowValue = data[dataRow];
      if (rowValue === undefined) continue; // lazy hole
      const value = getCellValue<unknown, AnyColumnDef>(rowValue, column);
      const text = displayText(cellType, value, column.options).slice(0, MAX_SAMPLE_TEXT_LENGTH);
      if (text) cellTexts.add(text);
    }
    const headerText = includeHeader
      ? (column.headerText ?? (typeof column.header === "string" ? column.header : "")).slice(0, MAX_SAMPLE_TEXT_LENGTH)
      : "";
    const headerWidth = headerText
      ? measureTextWidths([headerText], fonts.headerFont) + (sortedColumnIds.has(column.id) ? SORTED_HEADER_AFFORDANCE : 0) + (hasHeaderMenu ? HEADER_MENU_AFFORDANCE : 0) + (hasHeaderFilter && offersSetFilter(column, cellType) ? HEADER_FILTER_AFFORDANCE : 0)
      : 0;
    const cellWidth = measureTextWidths([...cellTexts], fonts.cellFont);
    result[column.id] = clampColumnWidth(column, Math.max(headerWidth, cellWidth) + CELL_PADDING);
  }
  return result;
}

/** Extra horizontal padding (px) added around measured text: cell's own inline padding (px-2 = 8px each side) plus a small buffer. */
export const CELL_PADDING = 20;

let sharedCanvas: HTMLCanvasElement | null = null;

/** Lazily creates (and caches) the offscreen canvas used for `measureText`; returns null when canvas is unavailable (SSR/jsdom without a 2d context). */
function getMeasureContext(): CanvasRenderingContext2D | null {
  if (typeof document === "undefined") return null;
  if (!sharedCanvas) sharedCanvas = document.createElement("canvas");
  return sharedCanvas.getContext("2d");
}

/**
 * Measures the widest of `texts` (in px) using `font` via canvas `measureText` — far cheaper than
 * a DOM layout pass per candidate string. Returns 0 when no canvas context is available (SSR).
 */
export function measureTextWidths(texts: readonly string[], font: string): number {
  const ctx = getMeasureContext();
  if (!ctx) return 0;
  ctx.font = font;
  let max = 0;
  for (const text of texts) {
    const width = ctx.measureText(text).width;
    if (width > max) max = width;
  }
  return max;
}

/**
 * Autosize measurement for a column's double-click-to-fit gesture: measures the
 * header text plus every CURRENTLY RENDERED cell's text in that column (not the whole dataset —
 * only what's actually mounted), using the grid's own computed font so the measurement matches
 * what's on screen, then clamps to `[minWidth, maxWidth]` and adds cell padding.
 */
export function measureColumnAutosizeWidth(args: {
  headerText: string;
  cellTexts: readonly string[];
  font: string;
  minWidth?: number;
  maxWidth?: number;
}): number {
  const { headerText, cellTexts, font, minWidth = 0, maxWidth = Number.POSITIVE_INFINITY } = args;
  const widest = measureTextWidths([headerText, ...cellTexts], font);
  const target = Math.ceil(widest) + CELL_PADDING;
  return Math.min(Math.max(target, minWidth), maxWidth);
}

import type { AnyColumnDef } from "../store";

/** Cumulative inset-inline-start offsets (px) for pinned-left columns, keyed by column index. */
export function pinLeftOffsets(widths: number[], pins: (AnyColumnDef["pin"] | undefined)[]): number[] {
  const offsets: number[] = [];
  let acc = 0;
  for (let i = 0; i < widths.length; i++) {
    offsets.push(acc);
    if (pins[i] === "left") acc += widths[i]!; // i < widths.length by loop condition
  }
  return offsets;
}

/** Cumulative inset-inline-end offsets (px) for pinned-right columns, keyed by column index. */
export function pinRightOffsets(widths: number[], pins: (AnyColumnDef["pin"] | undefined)[]): number[] {
  const offsets = new Array<number>(widths.length).fill(0);
  let acc = 0;
  for (let i = widths.length - 1; i >= 0; i--) {
    offsets[i] = acc;
    if (pins[i] === "right") acc += widths[i]!; // 0 <= i < widths.length by loop condition
  }
  return offsets;
}

// Right-pinned cells draw their divider on the start side, so it marks the band edge while columns scroll underneath.
export const COLUMN_BORDER =
  "border-e data-[pinned=right]:border-e-0 data-[pinned=right]:border-s border-x-[color:var(--grid-column-border,var(--color-border))]";

"use client";

import type { CSSProperties, PointerEvent as ReactPointerEvent, ReactNode } from "react";
import { cn } from "@/lib/utils";
import type { ColumnGroupDef, HeaderClickBehavior } from "../types";
import type { HeaderSegment } from "./column-groups";
import { COLUMN_BORDER } from "./column-border";
import { pinnedInsetStyle } from "./pinned-inset-style";

const MIN_VISIBLE_LABEL_PX = 128;
const INTERACTIVE_CONTENT = 'button, a, input, select, textarea, [role="button"], [contenteditable]:not([contenteditable="false"])';

/** Props for {@link DataGridGroupHeaderCell}. */
export type DataGridGroupHeaderCellProps = {
  segment: HeaderSegment;
  group: ColumnGroupDef;
  gridColOffset: number;
  /** Segment width in px. */
  width: number;
  /** Left edge of the segment's first track, in content coordinates. */
  trackLeft: number;
  /** Width of the marker column plus the pinned-start columns: the label stays right of it while the segment scrolls. */
  pinnedStartEdge: number;
  headerClickBehavior: HeaderClickBehavior;
  /** Selects the segment's columns `[start, end)`; runs only in "select" mode. */
  onSelect: (start: number, end: number, event: ReactPointerEvent<HTMLElement>) => void;
  reorder: {
    enabled: boolean;
    /** The id of the column or group being dragged. */
    draggingId: string | null;
    onPointerDown: (groupId: string, event: ReactPointerEvent<HTMLElement>) => void;
  };
};

/**
 * One group header cell: a label over the visible columns `[start, end)` of a group at one level.
 * A pinned segment sticks like the pinned columns under it. The label of a wide unpinned segment
 * follows the scroll position through a CSS offset, so it stays readable without per-tick JS.
 */
export function DataGridGroupHeaderCell({ segment, group, gridColOffset, width, trackLeft, pinnedStartEdge, headerClickBehavior, onSelect, reorder }: DataGridGroupHeaderCellProps): ReactNode {
  const { start, end, pin, depth } = segment;
  const style: CSSProperties = {
    gridRow: depth + 1,
    gridColumn: `${start + gridColOffset} / ${end + gridColOffset}`,
    zIndex: pin ? 3 : 2,
    ...pinnedInsetStyle(pin, pin === "right" ? end - 1 : start),
  };
  const followsScroll = !pin && width > MIN_VISIBLE_LABEL_PX;
  const labelStyle: CSSProperties | undefined = followsScroll
    ? { paddingInlineStart: `max(0px, min(calc(var(--grid-scroll-left, 0px) + ${pinnedStartEdge}px - ${trackLeft}px), ${width - MIN_VISIBLE_LABEL_PX}px))` }
    : undefined;
  const isDragging = reorder.draggingId === group.id;
  const handlePointerDown = (event: ReactPointerEvent<HTMLElement>) => {
    if (event.target instanceof Element && event.target.closest(INTERACTIVE_CONTENT)) return;
    if (headerClickBehavior === "select") onSelect(start, end, event);
    if (reorder.enabled) reorder.onPointerDown(group.id, event);
  };
  return (
    <div
      role="columnheader"
      aria-colindex={start + 1}
      aria-colspan={end - start}
      aria-label={typeof group.header === "string" ? undefined : group.headerText}
      data-grid-group-header=""
      data-group-id={group.id}
      data-pinned={pin || undefined}
      data-dragging={isDragging || undefined}
      className={cn("group relative flex items-center border-b border-border bg-muted px-2 font-medium select-none", COLUMN_BORDER, isDragging && "opacity-50", group.headerClassName)}
      style={style}
      onPointerDown={handlePointerDown}
      onDoubleClick={(event) => event.stopPropagation()}
    >
      {typeof group.header === "string" ? (
        <span className="block min-w-0 truncate" style={labelStyle}>
          {group.header}
        </span>
      ) : (
        group.header
      )}
    </div>
  );
}

import type { CSSProperties } from "react";
import type { AnyColumnDef } from "../store";

/** Pinned-cell inset style: position:relative works under a transformed ancestor, `position:sticky` doesn't. */
export function pinnedInsetStyle(
  pinned: AnyColumnDef["pin"] | undefined,
  index: number,
): CSSProperties {
  if (!pinned) return {};
  if (pinned === "left") {
    // Cell's flow position is trackLeft, then the ancestor canvas applies -scrollLeft; to land the
    // cell at the static offset regardless of scroll, add scrollLeft back and cancel trackLeft.
    return {
      position: "relative",
      insetInlineStart: `calc(var(--grid-scroll-left, 0px) + var(--grid-pin-left-${index}) - var(--grid-track-left-${index}))`,
    };
  }
  // Pin-right: the cell's right edge must sit `staticRightOffset` from the viewport's right edge,
  // but only floats to that edge once content actually overflows it, via
  // min(viewportWidth, contentWidth), else it hugs the content's own right edge (no dead gap).
  // rendered_left = trackLeft - scrollLeft + insetInlineStart (canvas transform + this cell's own inset).
  // Solve rendered_left = min(viewportWidth, contentWidth) - staticRightOffset - cellWidth for
  // insetInlineStart, and simplify trackLeft + cellWidth = trackRight:
  //   insetInlineStart = scrollLeft + min(viewportWidth, contentWidth) - staticRightOffset - trackRight
  return {
    position: "relative",
    insetInlineStart: `calc(var(--grid-scroll-left, 0px) + min(var(--grid-viewport-width), var(--grid-content-width)) - var(--grid-pin-right-${index}) - var(--grid-track-right-${index}))`,
  };
}

import type { AnyColumnDef } from "../store";

/** Absolute floor for any column width: a runaway drag or a zero/negative `minWidth` can never collapse a column to unusable. */
export const MIN_COLUMN_WIDTH = 32;

/**
 * Resolves a column's rendered width in px: live override, else def `width`, else the 150px
 * default, clamped by min/max. The clamp here covers the RENDERED width; programmatic writes go
 * through {@link clampColumnWidth}, which adds the 32px floor on top of `minWidth`.
 */
export function resolveColumnWidth(column: AnyColumnDef, override: number | undefined): number {
  const base = override ?? column.width ?? 150;
  const min = column.minWidth ?? 0;
  const max = column.maxWidth ?? Number.POSITIVE_INFINITY;
  return Math.min(Math.max(base, min), max);
}

/** Clamps `width` into the column's legal range `[max(MIN_COLUMN_WIDTH, minWidth), maxWidth]` — the one clamp the resize gesture and the store actions share. */
export function clampColumnWidth(column: AnyColumnDef, width: number): number {
  return resolveColumnWidth(column, Math.max(width, MIN_COLUMN_WIDTH));
}

/**
 * Grows `baseWidths` to fill positive leftover viewport space, proportional to `flexes`
 * (standard flexbox grow resolution: distribute leftover proportionally, clamp at maxWidth,
 * drop clamped columns from the active set and redistribute their unused share among the rest,
 * iterate until stable). Columns with no/zero flex, or every column when leftover <= 0, keep
 * their base width — a flex column never shrinks below it. Returns `baseWidths` unchanged (same
 * reference) when there's nothing to distribute, a cheap bail for the common non-flex grid.
 */
export function distributeFlexWidths(
  baseWidths: number[],
  flexes: (number | undefined)[],
  maxWidths: number[],
  available: number,
): number[] {
  const totalBase = baseWidths.reduce((a, b) => a + b, 0);
  const totalLeftover = available - totalBase;
  const flexIndices = flexes.reduce<number[]>((acc, f, i) => {
    if (f !== undefined && f > 0) acc.push(i);
    return acc;
  }, []);
  if (totalLeftover <= 0 || flexIndices.length === 0) return baseWidths;

  // exact/widths/floors/result/order below all index by i, which ranges over flexIndices/active —
  // positions derived from flexes/baseWidths, so every indexed access here is in-bounds by construction.
  const exact = baseWidths.slice(); // fractional target width per column, refined each pass
  let active = flexIndices.slice();
  let remainingLeftover = totalLeftover;
  while (active.length > 0 && remainingLeftover > 1e-9) {
    const totalFlex = active.reduce((sum, i) => sum + (flexes[i] as number), 0);
    const stillActive: number[] = [];
    let clampedAway = 0;
    for (const i of active) {
      const share = (remainingLeftover * (flexes[i] as number)) / totalFlex;
      const uncapped = exact[i]! + share;
      const capped = Math.min(uncapped, maxWidths[i]!);
      clampedAway += uncapped - capped;
      exact[i] = capped;
      if (capped < uncapped) continue; // hit its maxWidth — leaves the active set
      stillActive.push(i);
    }
    if (clampedAway <= 1e-9) break; // nothing clamped this pass — fully distributed, stop
    remainingLeftover = clampedAway;
    active = stillActive;
  }

  // Largest-remainder rounding so the sum matches `available` exactly (templates are whole px).
  const widths = baseWidths.slice();
  for (const i of flexIndices) widths[i] = exact[i]!;
  const floors = widths.map(Math.floor);
  let remainder = available - floors.reduce((a, b) => a + b, 0);
  const order = flexIndices.map((i) => ({ i, frac: widths[i]! - floors[i]! })).sort((a, b) => b.frac - a.frac);
  const result = floors.slice();
  for (const { i } of order) {
    if (remainder <= 0) break;
    result[i]! += 1;
    remainder -= 1;
  }
  return result;
}

"use client";

import { ChevronDown, ChevronUp } from "lucide-react";
import type { ReactNode } from "react";
import type { SortSpec } from "../types";

/** Props for {@link DataGridSortIndicator}. */
export type DataGridSortIndicatorProps = {
  columnId: string;
  sortState: readonly SortSpec[];
};

/**
 * Sort direction arrow (muted, size-3.5) for a header, plus its multi-sort priority number when
 * more than one sort is active. Renders nothing when the column isn't sorted.
 */
export function DataGridSortIndicator(props: DataGridSortIndicatorProps): ReactNode {
  const { columnId, sortState } = props;
  const index = sortState.findIndex((s) => s.columnId === columnId);
  if (index === -1) return null;
  const { direction } = sortState[index]!; // index !== -1 checked above, so it's a valid position
  const Icon = direction === "asc" ? ChevronUp : ChevronDown;
  return (
    <span className="ms-1 inline-flex items-center gap-0.5 text-muted-foreground" data-grid-sort-indicator={direction}>
      <Icon className="size-3.5" />
      {sortState.length > 1 && <span className="text-[10px] tabular-nums">{index + 1}</span>}
    </span>
  );
}

/** Resolves a header's `aria-sort` attribute from the active multi-sort spec. */
export function ariaSortFor(columnId: string, sortState: readonly SortSpec[]): "ascending" | "descending" | "none" {
  const entry = sortState.find((s) => s.columnId === columnId);
  if (!entry) return "none";
  return entry.direction === "asc" ? "ascending" : "descending";
}

"use client";

import { useCallback, useEffect, useRef, useState, type PointerEvent as ReactPointerEvent } from "react";

/** px of pointer movement (in the drag-start direction, off the origin header) before a header press commits to reorder-drag. */
const REORDER_THRESHOLD = 5;

/** Live reorder-drag UI state: the dragged column and where the drop indicator should render. */
export type ColumnReorderState = {
  draggingId: string;
  /** Column id the drop indicator renders next to, or null before the pointer has crossed into another header. */
  overId: string | null;
  /** Drop indicator renders before/after `overId`. */
  position: "before" | "after";
};

/** Per-header pointerdown handler + the shared drag state, one instance per `<DataGridHeader>`. */
export type ColumnReorderHandlers = {
  /** Attach to each header's label-zone pointerdown (never the resize-handle zone). */
  onHeaderDragPointerDown: (columnId: string, event: ReactPointerEvent<HTMLElement>) => void;
  dragState: ColumnReorderState | null;
};

/**
 * Drag-to-reorder columns. MUST coexist with the header multi-column select-drag
 * from the interaction layer: both start from a press on the header. The disambiguation rule
 * (documented here as the single source of truth, tested by both the reorder and the select-drag
 * suites): **a horizontal drag that leaves the origin header becomes a reorder drag** whenever
 * `enableColumnReorder` is on and the pressed column is `reorderable`; **Shift+drag is always a
 * select-drag**, regardless of movement, so shift-extending a multi-column selection never
 * accidentally reorders. A plain press+drag that never leaves the origin header (or moves before
 * `REORDER_THRESHOLD`) resolves as a click (selection/sort), matching the existing 5px-jitter rule
 * used elsewhere in the interaction layer.
 */
export function useColumnReorder(args: {
  enabled: boolean;
  isColumnReorderable: (columnId: string) => boolean;
  /** Resolves the header element at a client point to a column id + before/after half, or null off any header. */
  hitTestHeader: (clientX: number, clientY: number) => { columnId: string; position: "before" | "after" } | null;
  onReorder: (id: string, targetId: string, position: "before" | "after") => void;
  /** Called the instant a press arms into a reorder drag — the caller cancels the sibling header column-select drag that started from the same press. */
  onArm?: () => void;
}): ColumnReorderHandlers {
  const { enabled, isColumnReorderable } = args;
  const argsRef = useRef(args);
  argsRef.current = args;

  const [dragState, setDragState] = useState<ColumnReorderState | null>(null);
  // attached once per gesture, the document listener would close over stale React state without this ref
  const dragStateRef = useRef<ColumnReorderState | null>(null);
  const pendingRef = useRef<{ columnId: string; startX: number; startY: number; pointerId: number } | null>(null);
  const cleanupRef = useRef<(() => void) | null>(null);

  const setDrag = useCallback((next: ColumnReorderState | null) => {
    dragStateRef.current = next;
    setDragState(next);
  }, []);

  const teardown = useCallback(() => {
    cleanupRef.current?.();
    cleanupRef.current = null;
    pendingRef.current = null;
    setDrag(null);
  }, [setDrag]);

  const onHeaderDragPointerDown = useCallback(
    (columnId: string, event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      // Shift+drag is always select-drag (disambiguation rule above) — never arm the reorder path.
      if (event.shiftKey) return;
      if (!enabled || !isColumnReorderable(columnId)) return;
      // a second pointer must not arm a second listener set (the first cleanup would be overwritten, listeners leak)
      if (pendingRef.current) return;

      pendingRef.current = { columnId, startX: event.clientX, startY: event.clientY, pointerId: event.pointerId };

      const handleMove = (e: PointerEvent) => {
        const pending = pendingRef.current;
        if (!pending || e.pointerId !== pending.pointerId) return;

        if (!dragStateRef.current) {
          // not yet armed: commit to reorder only past the threshold AND off the origin header (hitTest says a different column)
          const dx = Math.abs(e.clientX - pending.startX);
          if (dx < REORDER_THRESHOLD) return;
          const hit = argsRef.current.hitTestHeader(e.clientX, e.clientY);
          if (!hit || hit.columnId === pending.columnId) return;
          argsRef.current.onArm?.();
          setDrag({ draggingId: pending.columnId, overId: hit.columnId, position: hit.position });
          return;
        }

        const hit = argsRef.current.hitTestHeader(e.clientX, e.clientY);
        const prev = dragStateRef.current;
        setDrag({ ...prev, overId: hit?.columnId ?? null, position: hit?.position ?? prev.position });
      };

      const handleUp = (e: PointerEvent) => {
        const pending = pendingRef.current;
        if (!pending || e.pointerId !== pending.pointerId) return;
        const finalState = dragStateRef.current;
        if (finalState && finalState.overId) {
          argsRef.current.onReorder(finalState.draggingId, finalState.overId, finalState.position);
        }
        teardown();
      };

      const handleLost = (e: Event) => {
        if (e.type === "lostpointercapture" && e.target !== document) return;
        if ("pointerId" in e && e.pointerId !== pendingRef.current?.pointerId) return;
        teardown();
      };

      document.addEventListener("pointermove", handleMove);
      document.addEventListener("pointerup", handleUp);
      document.addEventListener("pointercancel", handleLost);
      document.addEventListener("lostpointercapture", handleLost);
      window.addEventListener("blur", handleLost);
      cleanupRef.current = () => {
        document.removeEventListener("pointermove", handleMove);
        document.removeEventListener("pointerup", handleUp);
        document.removeEventListener("pointercancel", handleLost);
        document.removeEventListener("lostpointercapture", handleLost);
        window.removeEventListener("blur", handleLost);
      };
    },
    [enabled, isColumnReorderable, setDrag, teardown],
  );

  useEffect(() => teardown, [teardown]);

  return { onHeaderDragPointerDown, dragState };
}

"use client";

import { useCallback, useEffect, useRef, useState, type MouseEvent as ReactMouseEvent, type PointerEvent as ReactPointerEvent } from "react";
import type { AnyColumnDef } from "../store";
import type { AutosizeOptions } from "../types";
import { inlineDelta, type GridDirection } from "../virtualization/direction";
import { clampColumnWidth } from "./resolve-column-width";
import { safeSetPointerCapture } from "../interaction/safe-set-pointer-capture";

/** Handlers returned by {@link useColumnResize}, wired onto each header cell's resize handle. */
export type ColumnResizeHandlers = {
  onPointerDown: (event: ReactPointerEvent<HTMLElement>) => void;
  onDoubleClick: (event: ReactMouseEvent<HTMLElement>) => void;
  /** True while a resize drag is active — drives the handle's `data-resizing` hover-affordance state. */
  isResizing: boolean;
};

/**
 * Pointer-capture column resize: drag the handle to live-update the column's
 * width via `setColumnWidth`, clamped to `[minWidth ?? 32, maxWidth ?? Infinity]`; ends on
 * `lostpointercapture` (not `pointerup` — pointerup can be missed on alt-tab). Double-click sizes this column to its content over the whole view via the store's
 * `autosizeColumns` action (one commit, one `onColumnLayoutChange`).
 */
export function useColumnResize(args: {
  column: AnyColumnDef;
  currentWidth: number;
  setColumnWidth: (id: string, width: number) => void;
  /** Fires once at drag-release/autosize — the `onColumnLayoutChange` commit point (not per drag frame). */
  commitColumnWidth: (id: string, width: number) => void;
  /** The store's `autosizeColumns` action; double-click calls it for this column. */
  autosizeColumns: (options?: AutosizeOptions) => void;
  /**
   * Layout direction. The handle sits at the column's inline-END edge in both directions (the
   * logical `end-0` class places it), so dragging toward the inline end must always widen the
   * column — but `clientX` is physical, so under RTL that is a drag toward the physical LEFT and
   * the raw delta has to be inverted. Defaults to `"ltr"`.
   */
  direction?: GridDirection;
}): ColumnResizeHandlers {
  const { column } = args;
  const argsRef = useRef(args);
  argsRef.current = args;
  const [isResizing, setIsResizing] = useState(false);

  const clamp = useCallback((width: number) => clampColumnWidth(column, width), [column]);

  const dragRef = useRef<{ startX: number; startWidth: number } | null>(null);
  const cleanupRef = useRef<(() => void) | null>(null);

  const onPointerDown = useCallback(
    (event: ReactPointerEvent<HTMLElement>) => {
      if (event.button !== 0) return;
      event.stopPropagation();
      event.preventDefault();
      // a second pointer must not arm a second listener set (the first would outlive its release and leak)
      if (dragRef.current) return;
      // React nulls event.currentTarget when this handler returns; the document listeners below outlive it
      const target = event.currentTarget;
      const pointerId = event.pointerId;
      dragRef.current = { startX: event.clientX, startWidth: argsRef.current.currentWidth };
      safeSetPointerCapture(target, pointerId);
      setIsResizing(true);

      // document-level listeners: pointer capture retargets hardware events to the handle, not events dispatched on document (tests)
      let lastWidth = argsRef.current.currentWidth;
      const handleMove = (e: PointerEvent) => {
        if (e.pointerId !== pointerId) return;
        const drag = dragRef.current;
        if (!drag) return;
        lastWidth = clamp(drag.startWidth + inlineDelta(e.clientX - drag.startX, argsRef.current.direction ?? "ltr"));
        argsRef.current.setColumnWidth(column.id, lastWidth);
      };
      const cleanup = () => {
        document.removeEventListener("pointermove", handleMove);
        document.removeEventListener("pointerup", handleEnd);
        document.removeEventListener("pointercancel", handleEnd);
        target.removeEventListener("lostpointercapture", handleEnd);
        cleanupRef.current = null;
      };
      const handleEnd = (e: PointerEvent) => {
        if (e.pointerId !== pointerId) return;
        dragRef.current = null;
        setIsResizing(false);
        cleanup();
        // drag-release commit point for onColumnLayoutChange — fires once here, not per handleMove frame.
        if (e.type === "pointerup") argsRef.current.commitColumnWidth(column.id, lastWidth);
      };
      // lostpointercapture fires even when pointerup is missed (alt-tab); the document fallbacks cover environments without capture semantics
      document.addEventListener("pointermove", handleMove);
      document.addEventListener("pointerup", handleEnd);
      document.addEventListener("pointercancel", handleEnd);
      target.addEventListener("lostpointercapture", handleEnd);
      cleanupRef.current = cleanup;
    },
    [clamp, column.id],
  );

  // an unmount mid-drag (handle gone, capture lost with it) must drop the document listeners
  useEffect(
    () => () => {
      cleanupRef.current?.();
      cleanupRef.current = null;
      dragRef.current = null;
    },
    [],
  );

  const onDoubleClick = useCallback(
    () => {
      argsRef.current.autosizeColumns({ columnIds: [column.id] });
    },
    [column.id],
  );

  return { onPointerDown, onDoubleClick, isResizing };
}

/**
 * Every grid-owned `data-*` DOM attribute, in one place. Each is stamped by exactly one component
 * (noted per entry) and read back by selectors/tests elsewhere — collecting them here means a typo
 * in either place is a compile error instead of a silently-broken selector. Does NOT cover
 * shadcn/Base-UI-owned attributes (`data-slot`, `data-state`, etc.) or plain per-row/column
 * identifiers (`data-column-id`) that carry a consumer value rather than a fixed grid enum.
 */
export const GRID_ATTR = {
  /** cell.tsx: `"left" | "right"` when the column is pinned, absent otherwise. Also stamped boolean-style (`""`/absent) by the selection/fill/presence overlays when their rect falls in a pinned zone. */
  pinned: "data-pinned",
  /** cell.tsx: present (`""`) on a `data-grid-pinned-rows` band cell (rendered via `DataGridCell`'s `pinned` mode). */
  pinnedRow: "data-grid-pinned-row",
  /** cell.tsx: present (`""`) on the focused cell. */
  active: "data-active",
  /** cell.tsx: present (`""`) while the cell is in edit mode. */
  editing: "data-editing",
  /** cell.tsx: present (`""`) when the cell matches the current quick-search text. */
  searchMatch: "data-search-match",
  /** row.tsx: the row's view index (number), immune to pinned-top band shifting `aria-rowindex`; read back by `resolve-context-menu-target.ts`. */
  rowIndex: "data-grid-row-index",
  /** header-cell.tsx: present (`""`) while that column's resize handle is being dragged. */
  resizing: "data-resizing",
  /** cell-types/checkbox.tsx: present (`""`) on a checkbox cell's box; a press inside it toggles on the first click. */
  checkboxBox: "data-grid-checkbox",
  /** rows/marker-cell.tsx: present (`""`) on a rows-channel selected row's marker cell. */
  selected: "data-row-selected",
  /** virtualization/use-row-hover.ts: present (`""`) on the body row under the pointer. */
  hovered: "data-hovered",
  /** virtualization/use-scrolled-edges.ts: present (`""`) on the viewport while scrolled away from its inline-start edge. */
  scrolledLeft: "data-scrolled-left",
  /** virtualization/use-scrolled-edges.ts: present (`""`) on the viewport while there's more to scroll toward its inline-end edge. */
  scrolledRight: "data-scrolled-right",
  /** virtualization/use-scrolled-edges.ts: present (`""`) on the viewport while scrolled away from its top edge. */
  scrolledTop: "data-scrolled-top",
  /** virtualization/use-scrolled-edges.ts: present (`""`) on the viewport while there's more to scroll toward its bottom edge. */
  scrolledBottom: "data-scrolled-bottom",

