  "Enter", "Escape", "Tab", "Backspace", "Delete", "Insert", "Clear", "Help",
  "CapsLock", "NumLock", "ScrollLock", "Pause", "PrintScreen", "ContextMenu",
  "Execute", "Menu", "Suspend", "EraseEOL", "Again", "Accept", "Redo", "Undo", "Props", "Select",
