import type { GridAction, Keymap } from "../types";
import { DEFAULT_KEYMAP } from "./default-keymap";

/** Parsed form of a binding string (see `Keymap` in ../types for the string format). */
export type ParsedBinding = {
  mod: boolean;
  /** Literal physical Ctrl key, distinct from `mod` (which is Cmd on mac); keymap-local extension for bindings like Ctrl+Space that must not resolve to Cmd on macOS. */
  ctrl: boolean;
  shift: boolean;
  alt: boolean;
  key: string;
};

/** Splits a binding string like "mod+shift+ArrowUp" into its modifier flags and key. */
export function parseBinding(binding: string): ParsedBinding {
  const parts = binding.split("+");
  // last part is always the key; a literal "+" key never occurs in this keymap
  const key = parts[parts.length - 1] ?? "";
  const modifiers = parts.slice(0, -1);
  return {
    mod: modifiers.includes("mod"),
    ctrl: modifiers.includes("ctrl"),
    shift: modifiers.includes("shift"),
    alt: modifiers.includes("alt"),
    key,
  };
}

/** Minimal event shape the matcher needs; matches both DOM and synthetic KeyboardEvents. */
export type KeymapEvent = {
  key: string;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
  altKey: boolean;
};

function keysEqual(eventKey: string, bindingKey: string): boolean {
  if (eventKey.length === 1 && bindingKey.length === 1) {
    return eventKey.toLowerCase() === bindingKey.toLowerCase();
  }
  return eventKey === bindingKey;
}

function matchesBinding(event: KeymapEvent, binding: ParsedBinding, isMac: boolean): boolean {
  if (!keysEqual(event.key, binding.key)) return false;
  if (event.shiftKey !== binding.shift) return false;
  if (event.altKey !== binding.alt) return false;

  // literal ctrl: bypasses mod/Cmd resolution entirely, e.g. Ctrl+Space must stay Ctrl on mac
  if (binding.ctrl) {
    return event.ctrlKey && !event.metaKey;
  }

  const modPressed = isMac ? event.metaKey : event.ctrlKey;
  const otherPressed = isMac ? event.ctrlKey : event.metaKey;
  if (otherPressed) return false;
  if (modPressed !== binding.mod) return false;
  return true;
}

/**
 * Resolves a keyboard event to a `GridAction` using `keymap`, or null if unbound. `include`
 * limits the candidates to the actions it accepts. When several actions share a combo, the most
 * modifier-specific binding wins; on a tie a keymap binding that is not one of the action's
 * defaults beats a default, and a tie between two defaults keeps the earlier entry (Enter: `edit`
 * before `commitDown`).
 */
export function matchKeymap(
  event: KeymapEvent,
  keymap: Keymap,
  isMac: boolean,
  include?: (action: GridAction) => boolean,
): GridAction | null {
  let best: { action: GridAction; specificity: number; consumer: boolean } | null = null;

  for (const [action, bindings] of Object.entries(keymap) as [GridAction, string[] | undefined][]) {
    if (!bindings) continue;
    if (include && !include(action)) continue;
    for (const raw of bindings) {
      const parsed = parseBinding(raw);
      if (!matchesBinding(event, parsed, isMac)) continue;
      const consumer = !isDefaultBinding(action, raw);
      const specificity =
        (parsed.mod ? 1 : 0) + (parsed.ctrl ? 1 : 0) + (parsed.shift ? 1 : 0) + (parsed.alt ? 1 : 0);
      if (!best || specificity > best.specificity) {
        best = { action, specificity, consumer };
      } else if (specificity === best.specificity && consumer && !best.consumer) {
        best = { action, specificity, consumer };
      }
    }
  }

  return best?.action ?? null;
}

/**
 * Canonical form of a binding: modifiers in fixed order and a lowercase single-character key.
 * With `ctrlIsMod`, `ctrl` and `mod` share one token (both mean the Ctrl key off macOS).
 */
export function bindingSignature(binding: string, ctrlIsMod = false): string {
  const parsed = parseBinding(binding);
  const key = parsed.key.length === 1 ? parsed.key.toLowerCase() : parsed.key;
  const mod = parsed.mod || (ctrlIsMod && parsed.ctrl);
  const ctrl = parsed.ctrl && !ctrlIsMod;
  return [mod ? "mod" : "", ctrl ? "ctrl" : "", parsed.shift ? "shift" : "", parsed.alt ? "alt" : "", key]
    .filter(Boolean)
    .join("+");
}

/** True when `binding` restates one of `action`'s `DEFAULT_KEYMAP` bindings (modifier order and key case aside). */
export function isDefaultBinding(action: GridAction, binding: string): boolean {
  const defaults: readonly string[] | undefined = DEFAULT_KEYMAP[action];
  if (!defaults) return false;
  const signature = bindingSignature(binding);
  return defaults.some((d) => bindingSignature(d) === signature);
}

import type { GridAction, Keymap } from "../types";
import { isComposingKey } from "../interaction/is-composing-key";
import { matchKeymap } from "./match-keymap";
import { isMacPlatform } from "./platform";

/**
 * An action the global-shortcut layer may resolve and dispatch while DOM focus is OUTSIDE the
 * grid. The layer is action-generic (the gate + `matchKeymap` + the grid's own dispatch path);
 * the SAFE DEFAULT is `undo`/`redo` only. Extension rule for anything added to
 * {@link DataGridGlobalShortcutActions}: every binding of the added action must be mod-prefixed
 * (no ctrl-only/alt-only combos — Ctrl+Space is the Windows IME toggle, Ctrl+Q the browser quit,
 * etc.), and the action must make sense without grid focus (a navigation move scrolls the grid's
 * own container, never the page).
 */
export type GlobalShortcutAction = GridAction;

/**
 * Actions the global-shortcut window layer may enable, each keyed `true`. Core lists the
 * actions it ships; an add-on that owns a `GridAction` (undo/redo, fill) augments this
 * interface via `declare module` to offer its own flag — see `data-grid-history`'s and
 * `data-grid-fill`'s barrels for the augmentation.
 */
export interface DataGridGlobalShortcutActions {
  selectAll: true;
  insertRowAbove: true;
  insertRowBelow: true;
  duplicateRow: true;
  deleteRows: true;
}

/**
 * Opt-in global-shortcut config: one `true` flag per enabled action. Keys are constrained to
 * `GridAction` so an add-on's augmentation of {@link DataGridGlobalShortcutActions} can never
 * compile in a key `dispatchGridAction` cannot resolve. No flag set (or the config omitted)
 * enables the safe default — `undo` and `redo` only; any flag set enables exactly the flagged
 * actions.
 */
export type GlobalShortcutsConfig = {
  [K in keyof DataGridGlobalShortcutActions & GridAction]?: true;
};

/** The actions enabled by default: undo/redo only (the safe set — see {@link GlobalShortcutAction}). */
const DEFAULT_GLOBAL_ACTIONS: readonly GridAction[] = ["undo", "redo"];

/** The enabled actions of a config: any `true` flag selects exactly the flagged actions. No flag (or no config) enables the default set. */
export function enabledGlobalActions(config?: GlobalShortcutsConfig): readonly GlobalShortcutAction[] {
  const flagEnabled = Object.keys(config ?? {}).filter(
    (key) => config?.[key as keyof GlobalShortcutsConfig] === true,
  ) as GlobalShortcutAction[];
  return flagEnabled.length > 0 ? flagEnabled : [...DEFAULT_GLOBAL_ACTIONS];
}

/** Minimal event shape for {@link resolveGlobalShortcut} — the matcher's `KeymapEvent` plus the two DOM flags the gate needs. */
export type GlobalShortcutEvent = {
  key: string;
  ctrlKey: boolean;
  metaKey: boolean;
  shiftKey: boolean;
  altKey: boolean;
  isComposing: boolean;
  keyCode: number;
  defaultPrevented: boolean;
};

/** DOM-derived facts the hook computes per event; keeps the gate pure. */
export type GlobalShortcutContext = {
  keymap: Keymap;
  isMac: boolean;
  actions: readonly GridAction[];
  /** The event target is `INPUT`/`TEXTAREA`/`SELECT` or `[contenteditable="true"]`. */
  targetIsEditable: boolean;
  /** The event target is inside ANY `role="grid"` element (including another grid). */
  targetInAnyGrid: boolean;
  /** This grid is the last focused opted-in grid (the multi-grid tie-break). */
  ownsFocus: boolean;
  /** An edit session is open; its editor, including a portaled popup, owns the keys. */
  editing?: boolean;
  /** Limits the keymap match to the actions it accepts. */
  include?: (action: GridAction) => boolean;
};

/**
 * The gate for global shortcuts, pure and unit-tested (same posture as {@link matchKeymap}).
 * Rules run in order, any hit returns `null`:
 * 1. `isComposing` — IME composition owns the keys.
 * 2. `defaultPrevented` — the in-grid handler (earlier in the bubble) or the page already handled it.
 * 3. `targetIsEditable` — the field's native undo/redo wins; never hijack it.
 * 4. `targetInAnyGrid` — a grid's in-grid handler owns the key (this also excludes other grids).
 * 5. `ownsFocus` — multi-grid: only the last focused opted-in grid proceeds.
 * 6. `editing` — an open edit session owns the keys, even from a popup outside the grid.
 * 7. The keymap resolves to one of the enabled actions.
 */
export function resolveGlobalShortcut(
  event: GlobalShortcutEvent,
  ctx: GlobalShortcutContext,
): GlobalShortcutAction | null {
  if (isComposingKey(event)) return null;
  if (event.defaultPrevented) return null;
  if (ctx.targetIsEditable) return null;
  if (ctx.targetInAnyGrid) return null;
  if (!ctx.ownsFocus) return null;
  if (ctx.editing) return null;
  const action = matchKeymap(event, ctx.keymap, ctx.isMac, ctx.include);
  if (action === null) return null;
  return ctx.actions.includes(action) ? action : null;
}

/** The current platform check, re-exported so consumers/tests never drift from the hook's view. */
export { isMacPlatform };

/** Shared Apple-platform check for the keymap matcher and shortcut labels: `mod` is Cmd and modifiers are glyphs only here. */
export function isMacPlatform(): boolean {
  if (typeof navigator === "undefined") return false;
  // userAgentData is the modern replacement for the deprecated `platform`; both are checked for jsdom/older browsers.
  const uaData = (navigator as Navigator & { userAgentData?: { platform?: string } }).userAgentData;
  // case-insensitive: userAgentData.platform reports "macOS" (lowercase 'ac'), unlike legacy "MacIntel".
  const platform = uaData?.platform ?? navigator.platform ?? "";
  return /mac|iphone|ipad/i.test(platform);
}

import { isMacPlatform } from "./platform";

const ARROW_GLYPHS: Record<string, string> = {
  ArrowUp: "↑",
  ArrowDown: "↓",
  ArrowLeft: "←",
  ArrowRight: "→",
};

/** Formats one binding segment (`mod`, `shift`, `z`, `ArrowUp`, space) as a display token — glyphs on Apple platforms, word names elsewhere. */
export function formatShortcutToken(segment: string, isMac: boolean = isMacPlatform()): string {
  if (segment === "mod") return isMac ? "⌘" : "Ctrl";
  if (segment === "ctrl") return "Ctrl";
  if (segment === "shift") return isMac ? "⇧" : "Shift";
  if (segment === "alt") return isMac ? "⌥" : "Alt";
  if (segment === " ") return "Space";
  const arrowGlyph = ARROW_GLYPHS[segment];
  if (arrowGlyph !== undefined) return arrowGlyph;
  return segment.length === 1 ? segment.toUpperCase() : segment;
}

/**
 * Formats a binding string (`mod+shift+z`) to ordered display tokens — `["⌘", "⇧", "Z"]` on Apple,
 * `["Ctrl", "Shift", "Z"]` elsewhere. `isMac` defaults to {@link isMacPlatform}.
 */
export function formatShortcut(binding: string, isMac: boolean = isMacPlatform()): string[] {
  return binding.split("+").map((segment) => formatShortcutToken(segment, isMac));
}

"use client";

import { useEffect, useMemo, useRef, type ReactNode } from "react";
import type { GlobalShortcutsConfig } from "./global-shortcuts";
import { enabledGlobalActions, isMacPlatform, resolveGlobalShortcut } from "./global-shortcuts";
import { isPrintableKey } from "./is-printable-key";
import { useDataGridContainer } from "../interaction/use-data-grid-container";
import { dispatchGridAction } from "../interaction/use-grid-interaction";
import { useDataGridRootContext } from "../layout-context";
import {
  useDataGridActions,
  useDataGridKeymap,
  useDataGridStoreApi,
} from "../store";

/** Multi-grid focus owner: the id of the last opted-in grid whose container received `focusin`. */
let lastFocusedGrid: number | null = null;
let nextGridId = 0;

/**
 * While DOM focus is outside the grid, dispatches the enabled global actions (default: undo/redo)
 * on window keydown. Each action runs through the grid's own keymap-dispatch path
 * ({@link dispatchGridAction}), so it behaves exactly like its in-grid binding — same scrolling,
 * same store-side guards. Mount inside `DataGridRoot`; prefer {@link DataGridGlobalShortcuts}.
 */
export function useDataGridGlobalShortcuts(config?: GlobalShortcutsConfig): void {
  const containerRef = useDataGridContainer();
  const storeApi = useDataGridStoreApi();
  const keymap = useDataGridKeymap();
  const actions = useDataGridActions();
  const { rowHeight, interaction } = useDataGridRootContext();

  // content-based dep (not the `config` object) so an inline config doesn't recompute per render;
  // sorted keys since the flag set is open (add-ons augment it) so no fixed list of deps works
  const configKey = config ? Object.keys(config).filter((k) => config[k as keyof GlobalShortcutsConfig]).sort().join("|") : "";
  const enabled = useMemo(
    () => enabledGlobalActions(config),
    // oxlint-disable-next-line react-hooks/exhaustive-deps -- deliberate content-based dep (configKey)
    [configKey],
  );

  // the window handler reads fresh values per event without re-attaching on every config change
  const latestRef = useRef({ keymap, enabled, actions, scrollCellIntoView: interaction.scrollCellIntoView, rowHeight });
  latestRef.current = { keymap, enabled, actions, scrollCellIntoView: interaction.scrollCellIntoView, rowHeight };

  // one id per mount: a fresh id on every effect run would drop the grid's focus ownership
  // (lastFocusedGrid would no longer match) whenever the effect re-runs
  const gridIdRef = useRef(0);
  if (gridIdRef.current === 0) gridIdRef.current = ++nextGridId;

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const gridId = gridIdRef.current;

    function onFocusIn() {
      lastFocusedGrid = gridId;
    }

    function onKeyDown(event: KeyboardEvent) {
      const latest = latestRef.current;
      const target = event.target;
      const targetIsEditable =
        target instanceof HTMLElement &&
        (target.tagName === "INPUT" ||
          target.tagName === "TEXTAREA" ||
          target.tagName === "SELECT" ||
          target.isContentEditable);
      const targetInAnyGrid = target instanceof Element ? target.closest('[role="grid"]') !== null : false;
      const action = resolveGlobalShortcut(event, {
        keymap: latest.keymap,
        isMac: isMacPlatform(),
        actions: latest.enabled,
        targetIsEditable,
        targetInAnyGrid,
        ownsFocus: lastFocusedGrid === gridId,
        editing: storeApi.getState().editing !== null,
        include: (a) => storeApi.getState().commands?.[a]?.scope !== "editing",
      });
      if (action === null) return;
      dispatchGridAction({
        action,
        actions: latest.actions,
        storeApi,
        scrollRef: containerRef,
        scrollCellIntoView: latest.scrollCellIntoView,
        rowHeight: latest.rowHeight,
        triggerKey: isPrintableKey(event) ? event.key : undefined,
        preventDefault: () => event.preventDefault(),
      });
    }

    container.addEventListener("focusin", onFocusIn);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      container.removeEventListener("focusin", onFocusIn);
      window.removeEventListener("keydown", onKeyDown);
      if (lastFocusedGrid === gridId) lastFocusedGrid = null;
    };
  }, [containerRef, storeApi]);
}

