      getRowClassName: getRowClassName as GetRowClassName<unknown> | undefined,
      getCellClassName: getCellClassName as GetCellClassName<unknown> | undefined,
    }),
    [
      scrollRef,
      viewportRef,
      visibleColumns,
      renderedColumns,
      layout,
      rowHeight,
      headerHeight,
      headerRowHeight,
      headerRowCount,
      headerRows,
      columnGroupModel,
      pinnedTopHeight,
      pinnedBottomHeight,
      topBandRowCount,
      template,
      interaction,
      direction,
      renderHeaderMenu,
      renderHeaderFilter,
      renderMarker,
      renderMarkerHeader,
