                data-grid-pin-shadow="bottom"
                data-pinned={bottomBandRowCount > 0 ? "" : undefined}
                aria-hidden="true"
                className="pointer-events-none absolute opacity-0 transition-opacity in-data-scrolled-bottom:opacity-100"
                style={{
