 */
export function remapSelectionRows(selection: GridSelection, newIndexOf: ArrayLike<number>): GridSelection {
  const after = (row: number) => newIndexOf[row] ?? row;
  const rows = CompactSelection.fromArray(selection.rows.toArray().map(after).sort((a, b) => a - b));
  const current = selection.current;
  if (!current) return { current: null, rows, columns: selection.columns };

  const cell = { ...current.cell, row: after(current.cell.row) };
  const mapRect = (rect: GridRect): GridRect | null => {
    let top = Infinity;
    let bottom = -Infinity;
    for (let row = rect.y; row < rect.y + rect.height; row++) {
      const moved = after(row);
      if (moved < top) top = moved;
      if (moved > bottom) bottom = moved;
    }
    return bottom - top + 1 === rect.height ? { ...rect, y: top } : null;
  };
  const range = mapRect(current.range);
  return {
    current: {
      cell,
      range: range ?? rectFromCorners(cell, cell),
      rangeStack: range ? current.rangeStack.flatMap((rect) => mapRect(rect) ?? []) : [],
    },
    rows,
    columns: selection.columns,
  };
}

import { CompactSelection } from "./compact-selection";
import type { ViewCoord, GridRect, GridSelection } from "../types";

/** Two-stage progression tracked by the caller (interaction layer): which stage the last `selectAllProgression` call produced. */
export type SelectAllStage = "region" | "all" | null;

/** Probes whether the cell at `coord` is empty, via the cell type's `isEmpty` — same contract as `jumpToDataBoundary`'s local helper. */
export type IsEmptyAt = (coord: ViewCoord) => boolean;

function wholeGridRect(rowCount: number, colCount: number): GridRect {
  return { x: 0, y: 0, width: colCount, height: rowCount };
}

/**
 * Excel's "current region": the maximal rectangle of contiguous non-empty rows/columns containing
 * `active`, grown one edge at a time (flood-fill by row/column, not per-cell) until every row/column
 * just outside the rect is entirely empty. An empty `active` cell's region is itself (Excel parity).
 * O(perimeter × rows/cols touched) — only called on an explicit Ctrl+A, never a hot path.
 */
export function computeDataRegion(active: ViewCoord, rowCount: number, colCount: number, isEmptyAt: IsEmptyAt): GridRect {
  if (isEmptyAt(active)) return { x: active.col, y: active.row, width: 1, height: 1 };

  let left = active.col;
  let right = active.col;
  let top = active.row;
  let bottom = active.row;

  const rowHasData = (row: number, fromCol: number, toCol: number): boolean => {
    for (let col = fromCol; col <= toCol; col++) if (!isEmptyAt({ col, row })) return true;
    return false;
  };
  const colHasData = (col: number, fromRow: number, toRow: number): boolean => {
    for (let row = fromRow; row <= toRow; row++) if (!isEmptyAt({ col, row })) return true;
    return false;
  };

  const growRows = (): boolean => {
    const before = bottom - top;
    while (top > 0 && rowHasData(top - 1, left, right)) top--;
    while (bottom < rowCount - 1 && rowHasData(bottom + 1, left, right)) bottom++;
    return bottom - top > before;
  };
  const growColumns = (): boolean => {
    const before = right - left;
    while (left > 0 && colHasData(left - 1, top, bottom)) left--;
    while (right < colCount - 1 && colHasData(right + 1, top, bottom)) right++;
    return right - left > before;
  };

  // Each axis grows to its limit; the other axis is re-checked only after this one grew.
  let rowsDirty = true;
  let columnsDirty = true;
  while (rowsDirty || columnsDirty) {
    if (rowsDirty) {
      rowsDirty = false;
      if (growRows()) columnsDirty = true;
    }
    if (columnsDirty) {
      columnsDirty = false;
      if (growColumns()) rowsDirty = true;
    }
  }

  return { x: left, y: top, width: right - left + 1, height: bottom - top + 1 };
}

function isRect(rect: GridRect, other: GridRect): boolean {
  return rect.x === other.x && rect.y === other.y && rect.width === other.width && rect.height === other.height;
}

function selectionForRect(rect: GridRect, anchor: ViewCoord): GridSelection {
  return {
    current: { cell: anchor, range: rect, rangeStack: [] },
    rows: CompactSelection.empty(),
    columns: CompactSelection.empty(),
  };
}

/**
 * Two-stage Ctrl+A (Excel/Sheets parity):
 * stage 1 selects the active cell's data region, stage 2 (an immediate repeat, tracked by the
 * caller via `stage`) selects the whole grid. When the region already equals the whole grid
 * (dense data), stage 1 already lands on `"all"` so a repeated press stays a no-op rather than
 * toggling anything — the caller's `stage` never needs a second real transition in that case.
 * Pure: takes the progression stage in, returns the next selection + stage out.
 */
export function selectAllProgression(
  selection: GridSelection,
  rowCount: number,
  colCount: number,
  active: ViewCoord,
  isEmptyAt: IsEmptyAt,
  stage: SelectAllStage,
): { selection: GridSelection; stage: "region" | "all" } {
  const wholeGrid = wholeGridRect(rowCount, colCount);

  if (stage === "region") {
    return { selection: selectionForRect(wholeGrid, active), stage: "all" };
  }

  const region = computeDataRegion(active, rowCount, colCount, isEmptyAt);
  if (isRect(region, wholeGrid)) {
    // dense data: region already covers the grid, so this stays a no-op on repeat presses too —
    // only re-derive the selection if it isn't already exactly the whole grid.
    const alreadyWholeGrid =
      selection.current !== null && selection.current.rangeStack.length === 0 && isRect(selection.current.range, wholeGrid);
    return { selection: alreadyWholeGrid ? selection : selectionForRect(wholeGrid, active), stage: "all" };
  }
  return { selection: selectionForRect(region, active), stage: "region" };
}

import { CompactSelection } from "./compact-selection";
import type { CompactSelectionLike } from "../types";

/**
 * Options for selectRow/selectColumn. Plain click (no options set) toggles membership of
 * just this index, clearing the rest of the channel.
 */
export type SelectLineOptions = {
  /** Ctrl-click: additive toggle of this index, keeping the rest of the channel. */
  additive?: boolean;
  /** Shift-click: range from the last-selected index (falls back to `index` when there is none). */
  extendFromLast?: boolean;
  /**
   * The row-marker drag variant of `extendFromLast`: instead of ADDING the anchor..index span to
   * the channel (a union that can only grow), the channel becomes EXACTLY that span — the pointer
   * is the moving edge, so dragging back over already-selected rows shrinks the selection again.
   */
  replaceFromLast?: boolean;
  /**
   * Explicit last-highlighted index for `extendFromLast`/`replaceFromLast` (insertion order, not
   * the channel's max member — an RLE set can't represent insertion order, so the caller/reducer
   * must track it). Falls back to the channel's max index, then `index`, when absent.
   */
  from?: number;
};

/** Shared by selectRow/selectColumn: applies a plain/additive/extendFromLast toggle to one selection channel. */
export function selectLine(
  channelLike: CompactSelectionLike,
  index: number,
  opts: SelectLineOptions = {},
): CompactSelection {
  // only a structural CompactSelectionLike needs the fromArray materialization; a compact channel is used in place
  const channel = channelLike instanceof CompactSelection ? channelLike : CompactSelection.fromArray(channelLike.toArray());
  if (opts.replaceFromLast) {
    const last = opts.from ?? channel.last() ?? index;
    const start = Math.min(last, index);
    const end = Math.max(last, index) + 1;
    return CompactSelection.fromSingleSelection([start, end]);
  }
  if (opts.extendFromLast) {
    const last = opts.from ?? channel.last() ?? index;
    const start = Math.min(last, index);
    const end = Math.max(last, index) + 1;
    return channel.add([start, end]);
  }
  if (opts.additive) {
    return channel.hasIndex(index) ? channel.remove(index) : channel.add(index);
  }
  // plain click: toggle-select just this index
  if (channel.length === 1 && channel.hasIndex(index)) {
    return CompactSelection.empty();
  }
  return CompactSelection.fromSingleSelection(index);
}

import type { GridRect, GridSelection } from "../types";

/** Half-open column range `[start, end)`, merged/sorted, describing which columns of one row are selected. */
export type ColRange = readonly [start: number, end: number];

/** True when `viewRow` falls inside `rect`'s row span. */
function rectCoversRow(rect: GridRect, viewRow: number): boolean {
  return viewRow >= rect.y && viewRow < rect.y + rect.height;
}

/** Inserts `[start, end)` into `ranges` (sorted, non-overlapping), merging any overlap/adjacency. */
function mergeRange(ranges: ColRange[], start: number, end: number): void {
  if (start >= end) return;
  let i = 0;
  // hot path (per-row selector): ranges[i]! guarded by i < ranges.length in the loop condition
  while (i < ranges.length && ranges[i]![1] < start) i++;
  let mergedStart = start;
  let mergedEnd = end;
  while (i < ranges.length && ranges[i]![0] <= mergedEnd) {
    mergedStart = Math.min(mergedStart, ranges[i]![0]);
    mergedEnd = Math.max(mergedEnd, ranges[i]![1]);
    ranges.splice(i, 1);
  }
  ranges.splice(i, 0, [mergedStart, mergedEnd]);
}

/**
 * The selected column ranges for one view row — a row is a rectangle's-worth of columns, not
 * individual cells, so this collapses to a handful of `[start, end)` tuples (usually 0 or 1) instead
 * of a per-column boolean/Set. Used by {@link useDataGridRowCellState} so a row's selector output
 * stays cheap to compute and cheap to compare (small array, content-equal across unrelated updates).
 */
export function selectedColRangesForRow(selection: GridSelection, viewRow: number, colCount: number): ColRange[] {
  const ranges: ColRange[] = [];
  if (selection.rows.hasIndex(viewRow)) mergeRange(ranges, 0, colCount);
  if (selection.columns.length > 0) {
    for (const col of selection.columns.toArray()) mergeRange(ranges, col, col + 1);
  }
  if (selection.current) {
    if (rectCoversRow(selection.current.range, viewRow)) {
      mergeRange(ranges, selection.current.range.x, selection.current.range.x + selection.current.range.width);
    }
    for (const rect of selection.current.rangeStack) {
      if (rectCoversRow(rect, viewRow)) mergeRange(ranges, rect.x, rect.x + rect.width);
    }
  }
  return ranges;
}

/** Whether `col` falls inside any of `ranges` — the per-cell membership check row.tsx/cell.tsx derive `isSelected` from. */
export function colRangesContain(ranges: readonly ColRange[], col: number): boolean {
  for (const [start, end] of ranges) {
    if (col >= start && col < end) return true;
  }
  return false;
}

/** Content equality for two `ColRange[]` — same length, same tuples in the same order (both are built sorted/merged, so order is deterministic). */
export function colRangesEqual(a: readonly ColRange[], b: readonly ColRange[]): boolean {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const ra = a[i]!; // i < a.length by loop condition, same length as b (checked above)
    const rb = b[i]!;
    if (ra[0] !== rb[0] || ra[1] !== rb[1]) return false;
  }
  return true;
}

import type { GridSelection } from "../types";

/**
 * Every view row index covered by `selection`: the union of the primary range, the ctrl-click
 * `rangeStack`, and the whole-row channel (`rows`), deduped and sorted ascending. The core's
 * single derivation of the selected row set — add-ons acting on selected rows (cell-menu row
 * operations, selection-scope export) consume this instead of re-reading `GridSelection`'s channels.
 * The result is view indices, not row ids. With `checkedRowsOnly`, any checked row makes the
 * checked rows the whole result and the cell ranges are ignored.
 */
export function getSelectedViewRows(selection: GridSelection, options: { checkedRowsOnly?: boolean } = {}): number[] {
  if (options.checkedRowsOnly && selection.rows.length > 0) return selection.rows.toArray();
  const rows = new Set<number>();
  const current = selection.current;
  if (current) {
    const rects = [current.range, ...current.rangeStack];
    for (const rect of rects) {
      for (let row = rect.y; row < rect.y + rect.height; row++) rows.add(row);
    }
  }
  for (const row of selection.rows.toArray()) rows.add(row);
  return Array.from(rows).sort((a, b) => a - b);
}

import type { ViewCoord, GridSelection, GridRect } from "../types";
import { CompactSelection } from "./compact-selection";
import { rectFromCorners, rectsEqual } from "./rects";

/** The selection with nothing selected. */
export function emptySelection(): GridSelection {
  return { current: null, rows: CompactSelection.empty(), columns: CompactSelection.empty() };
}

/** True when all three selection channels (current range, rows, columns) are empty. */
export function isSelectionEmpty(selection: GridSelection): boolean {
  return selection.rows.length === 0 && selection.columns.length === 0 && !selection.current;
}

/** A fresh 1x1 selection anchored at `coord`, clearing row/column channels. */
export function selectCell(coord: ViewCoord): GridSelection {
  return {
    current: { cell: coord, range: { x: coord.col, y: coord.row, width: 1, height: 1 }, rangeStack: [] },
    rows: CompactSelection.empty(),
    columns: CompactSelection.empty(),
  };
}

/** Shift-click/shift-arrow: extends the primary range from the existing anchor to `coord`; anchor is unchanged. Returns the input itself when the result equals the current range (a stationary drag re-fires the same coord; stable identity keeps selection observers quiet). */
export function extendTo(selection: GridSelection, coord: ViewCoord): GridSelection {
  if (!selection.current) return selectCell(coord);
  const { cell, rangeStack } = selection.current;
  const range = rectFromCorners(cell, coord);
  if (rectsEqual(range, selection.current.range)) return selection;
  return {
    current: { cell, range, rangeStack },
    rows: selection.rows,
    columns: selection.columns,
  };
}

/** True when `row` is covered by the rows channel or any cell range — the state a marker checkbox shows. */
export function isRowChecked(selection: GridSelection, row: number): boolean {
  const { current } = selection;
  const covers = (r: GridRect) => row >= r.y && row < r.y + r.height;
  return selection.rows.hasIndex(row) || (!!current && (covers(current.range) || current.rangeStack.some(covers)));
}

/** Removes `row` from the rows channel and from every cell range, splitting a range that spans it; the piece holding the anchor stays primary. `selection` itself comes back when the row is in neither channel. */
export function removeRowFromSelection(selection: GridSelection, row: number, options: { multiRange?: boolean } = {}): GridSelection {
  const { multiRange = true } = options;
  const rows = selection.rows.hasIndex(row) ? CompactSelection.adopt(selection.rows).remove(row) : selection.rows;
  const current = selection.current;
  const covers = (r: GridRect) => row >= r.y && row < r.y + r.height;
  if (!current || (!covers(current.range) && !current.rangeStack.some(covers))) {
    return rows === selection.rows ? selection : { ...selection, rows };
  }
  const without = (r: GridRect): GridRect[] => {
    if (!covers(r)) return [r];
    const above = row - r.y;
    const below = r.y + r.height - row - 1;
    return [
      ...(above > 0 ? [{ ...r, height: above }] : []),
      ...(below > 0 ? [{ ...r, y: row + 1, height: below }] : []),
    ];
  };
  const { cell } = current;
  const holdsCell = (r: GridRect) => cell.col >= r.x && cell.col < r.x + r.width && cell.row >= r.y && cell.row < r.y + r.height;
  const primaryPieces = without(current.range);
  const stackPieces = multiRange ? current.rangeStack.flatMap(without) : [];
  const range = primaryPieces.find(holdsCell) ?? primaryPieces.at(-1) ?? stackPieces.at(-1);
  if (!range) return { ...selection, current: null, rows };
  const anchor =
    primaryPieces.length === 0
      ? { col: range.x, row: range.y }
      : { col: cell.col, row: Math.min(Math.max(cell.row, range.y), range.y + range.height - 1) };
  const rangeStack = multiRange ? [...stackPieces, ...primaryPieces].filter((piece) => piece !== range) : [];
  return { ...selection, rows, current: { cell: anchor, range, rangeStack } };
}

/** Ctrl-click: pushes the current primary range onto the stack and starts a new 1x1 range at `coord`. */
export function pushRange(selection: GridSelection, coord: ViewCoord): GridSelection {
  if (!selection.current) return selectCell(coord);
  const { range, rangeStack } = selection.current;
  return {
    current: {
      cell: coord,
      range: { x: coord.col, y: coord.row, width: 1, height: 1 },
      rangeStack: [...rangeStack, range],
    },
    rows: selection.rows,
    columns: selection.columns,
  };
}

import type { FilterJoinOperator, FilterSpec, SortSpec } from "../types";
import { defaultCompareText } from "./default-compare-text";
import { createFilterMatcher } from "./matches-filter";

/**
 * Read-only accessor the view-index builder uses to reach cell data without
 * knowing the row type. `compare` supplies a custom row-index comparator for a
 * column (a column `sortCompare` or its cell type's `compare`; absent comparators
 * fall back to `defaultCompareText` on `getText`).
 *
 * A `compare` a caller returns MUST be deterministic and depend only on the two
 * rows' current values — {@link updateViewIndex} reuses the untouched rows'
 * order under it instead of re-deriving it.
 */
export type CellAccessor = {
  /** The raw text the filter matcher, the empty check, and the default sort read. */
  getText(rowIndex: number, columnId: string): string;
  /** The quick-search text; defaults to `getText`. */
  getSearchText?: (rowIndex: number, columnId: string) => string;
  compare?(columnId: string): ((a: number, b: number) => number) | undefined;
  /** Whether a row's cell in `columnId` is empty for sort placement; defaults to `getText() === ""`. */
  isEmpty?(rowIndex: number, columnId: string): boolean;
  /** The column's raw (un-stringified) cell value; only needed by a column's `filterMatch`. */
  getValue?(rowIndex: number, columnId: string): unknown;
  /** The column's `filterMatch` predicate, if the column declares one. */
  filterMatch?(columnId: string): ((value: unknown, filter: FilterSpec) => boolean) | undefined;
};

/**
 * One filter's per-row test: the column's `filterMatch` (raw value) when the accessor provides
 * both the predicate and raw values, else the built-in text matcher. Both the rebuild and the
 * incremental path build through this so a custom predicate can never desync between them.
 */
export function makeFilterTest(accessor: CellAccessor, filter: FilterSpec): (row: number) => boolean {
  const custom = accessor.filterMatch?.(filter.columnId);
  const getValue = accessor.getValue;
  if (custom && getValue) {
    // a thrown predicate fails the row rather than the view build
    return (row: number) => {
      try {
        return custom(getValue(row, filter.columnId), filter);
      } catch {
        return false;
      }
    };
  }
  const test = createFilterMatcher(filter);
  return (row: number) => test(accessor.getText(row, filter.columnId));
}

/** The accessor's quick-search reader: `getSearchText` when present, else `getText`. */
export function searchTextReader(accessor: CellAccessor): (rowIndex: number, columnId: string) => string {
  return accessor.getSearchText ?? ((rowIndex, columnId) => accessor.getText(rowIndex, columnId));
}

/** Whether `row`'s cell in `columnId` counts as empty for sort placement — empty sorts last in BOTH directions. */
export function isEmptyCell(accessor: CellAccessor, rowIndex: number, columnId: string): boolean {
  return accessor.isEmpty ? accessor.isEmpty(rowIndex, columnId) : accessor.getText(rowIndex, columnId) === "";
}

/**
 * Options for {@link buildViewIndex}. `searchColumnIds` is only consulted
 * when `search` is set; if omitted in that case, the search filter is
 * skipped (no rows are excluded) rather than matching against zero columns.
 */
export type ViewIndexOptions = {
  sorts: SortSpec[];
  filters: FilterSpec[];
  /** How `filters` combine; default `"and"` (every filter must match). */
  joinOperator?: FilterJoinOperator;
  search?: string;
  searchColumnIds?: string[];
};

/**
 * Computes the row-index view: filter, then search, then a stable
 * multi-column sort. `sorts[0]` is primary; each subsequent sort only
 * breaks ties left by the ones before it. No sorts leaves filtered/searched
 * rows in their original order.
 */
export function buildViewIndex(
  rowCount: number,
  accessor: CellAccessor,
  opts: ViewIndexOptions,
): number[] {
  let indices: number[] = [];
  for (let i = 0; i < rowCount; i++) indices.push(i);

  if (opts.filters.length > 0) {
    // One matcher per filter, built once outside the per-row loop: any numeric bound in
    // gt/gte/lt/lte/isBetween is the same string for every row, so parsing it here instead of on
    // every `matchesFilter` call turns an O(n) redundant re-parse into O(1) setup per filter.
    const matchers = opts.filters.map((filter) => makeFilterTest(accessor, filter));

    if (opts.joinOperator === "or") {
      // OR: a row survives if ANY filter matches — one pass, no per-filter re-scan of `indices`.
      indices = indices.filter((row) => matchers.some((test) => test(row)));
    } else {
      // AND (default): short-circuits per row via the existing filter-per-filter narrowing, same
      // hot path as before this feature — untouched perf for the common (and only, pre-OR) case.
      for (const test of matchers) {
        indices = indices.filter((row) => test(row));
      }
    }
  }

  const search = opts.search?.trim();
  if (search && opts.searchColumnIds) {
    const needle = search.toLowerCase();
    const columnIds = opts.searchColumnIds;
    const readSearchText = searchTextReader(accessor);
    indices = indices.filter((row) =>
      columnIds.some((columnId) => readSearchText(row, columnId).toLowerCase().includes(needle)),
    );
  }

  if (opts.sorts.length === 0) return indices;

  // One collator amortized across every default-compare column and every pairwise
  // comparison in this call, instead of a fresh Intl.Collator per `localeCompare`.
  const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" });

  const comparators = opts.sorts.map((sort) => {
    const custom = accessor.compare?.(sort.columnId);
    const dir = sort.direction === "asc" ? 1 : -1;

    if (custom) {
      // Decorate emptiness once per row, same O(n) discipline as the text keys below.
      const empties = new Map<number, boolean>();
      for (const row of indices) empties.set(row, isEmptyCell(accessor, row, sort.columnId));
      // Same empty-last-in-both-directions rule as the default path, so a typed column's blanks
      // don't flip sides on a direction change while a text column's stay put.
      return (a: number, b: number) => {
        const emptyA = empties.get(a)!;
        const emptyB = empties.get(b)!;
        if (emptyA && emptyB) return 0;
        if (emptyA) return 1;
        if (emptyB) return -1;
        return dir * custom(a, b);
      };
    }

    // Decorate-sort-once: fetch each row's text key for this column exactly once (O(n))
    // instead of on every pairwise comparison (O(n log n) getText calls).
    const keys = new Map<number, string>();
    for (const row of indices) keys.set(row, accessor.getText(row, sort.columnId));

    // Empty must sort last for both directions, so only the non-empty ordering flips.
    return (a: number, b: number) => {
      const textA = keys.get(a)!;
      const textB = keys.get(b)!;
      if (textA === "" || textB === "") return defaultCompareText(textA, textB, collator);
      return dir * defaultCompareText(textA, textB, collator);
    };
  });

  // Decorate-sort-undecorate keeps the sort stable across the composed comparators.
  const decorated = indices.map((row, position) => ({ row, position }));
  decorated.sort((a, b) => {
    for (const cmp of comparators) {
      const result = cmp(a.row, b.row);
      if (result !== 0) return result;
    }
    return a.position - b.position;
  });

  return decorated.map((d) => d.row);
}

import type { FilterJoinOperator, FilterSpec, SortSpec } from "../types";
import { isEmptyCell, makeFilterTest, type CellAccessor, type ViewIndexOptions } from "./build-view-index";
import { defaultCompareText } from "./default-compare-text";

/**
 * Above this many touched rows, {@link updateViewIndex} refuses the incremental path and the caller
 * rebuilds. Each touched row costs one splice-out plus one splice-in against the index array, so the
 * cost is linear in k while the rebuild is a flat O(n log n) — the two cross where k × per-row cost
 * meets the rebuild.
 *
 * Measured (prod build, 100k rows, one sort column, paired in one launch): the rebuild is ~415 ms
 * flat; the incremental path is 0.3 / 0.9 / 7.6 / 28.5 / 137 ms at k = 1 / 20 / 256 / 1000 / 5000,
 * a slope near 0.027 ms per touched row. The curves therefore meet around k ≈ 15,000. 256 sits ~58x
 * inside that, so no machine, dataset, or collator can land a batch on the wrong side of it — and a
 * batch that big is a bulk import, which the rebuild serves better anyway.
 */
export const INCREMENTAL_PATCH_LIMIT = 256;

/**
 * Why {@link updateViewIndex} declined the incremental path — `null` means it ran. See each valve's
 * own guard.
 */
export type IncrementalBailReason = "too-many-rows" | "search-active";

export type IncrementalViewIndexResult =
  | { viewIndex: number[]; bail: null }
  | { viewIndex: null; bail: IncrementalBailReason };

/**
 * A row's total-order position under one sort column, resolved once per row per call.
 * Empty sorts last in BOTH directions, so the direction multiplier applies only when neither
 * side is empty — {@link buildViewIndex}'s own rule, replicated here rather than shared, because the
 * rebuild stays the untouched reference implementation. `custom` is the column's resolved
 * `accessor.compare` when it has one; otherwise the text keys drive `defaultCompareText`.
 */
function compareOnColumn(
  accessor: CellAccessor,
  columnId: string,
  dir: 1 | -1,
  custom: ((a: number, b: number) => number) | undefined,
  a: number,
  b: number,
): number {
  if (custom) {
    const emptyA = isEmptyCell(accessor, a, columnId);
    const emptyB = isEmptyCell(accessor, b, columnId);
    if (emptyA && emptyB) return 0;
    if (emptyA) return 1;
    if (emptyB) return -1;
    return dir * custom(a, b);
  }
  const textA = accessor.getText(a, columnId);
  const textB = accessor.getText(b, columnId);
  if (textA === "" || textB === "") return defaultCompareText(textA, textB);
  return dir * defaultCompareText(textA, textB);
