  // initial view over the full dataset — it must not run for a shell.
  const [ownedStore] = useState<StoreApi<DataGridStoreState> | null>(() => (externalStore ? null : createDataGridStore(internalInit)));
  const store = externalStore ?? (ownedStore as StoreApi<DataGridStoreState>);
  const prevColumns = useRef<readonly AnyColumnDef[] | undefined>(undefined);
  const prevData = useRef<readonly unknown[] | undefined>(undefined);
  const warnedColumnTypes = useRef<Set<string>>(new Set());
  const warnedDuplicateColumnIds = useRef<Set<string>>(new Set());
  const lastConfig = useRef<InternalSyncProps | null>(null);
  const lastRecompute = useRef<InternalSyncProps | null>(null);

  // One subscription per store instance, outside React's render path. External stores are
  // subscribed by their owner's useDataGridStoreProps call — subscribing here too would
  // double-fire onSelectionChange. The selection fire guard (last-known value + echo queue) lives
  // in the store closure, so the wiring is a store action, like _subscribeEditEnd.
  useEffect(() => {
    if (externalStore) return;
    return getInternalActions(store)._subscribeSelection();
  }, [store, externalStore]);
  useEffect(() => {
    if (externalStore) return;
    return subscribeActiveCellChange(store);
  }, [store, externalStore]);
  useEffect(() => {
    if (externalStore) return;
    return getInternalActions(store)._subscribeEditEnd();
  }, [store, externalStore]);

  useEffect(() => {
    if (externalStore) return;
    getInternalActions(store)._syncPluginClaims();
  });
  useEffect(() => {
    if (externalStore) return;
    return () => getInternalActions(store)._releasePluginClaims();
  }, [store, externalStore]);

  // Config phase: the slice that feeds no derived state. The layout timing closes the write
  // window between the commit and the passive effects, so a `readOnly` flip blocks a keydown
  // that arrives right after the commit.
  useLayoutEffect(() => {
    if (externalStore) return;
    const last = lastConfig.current;
    if (last !== null && !sliceChanged(last, internalInit, CONFIG_KEYS)) return;
    lastConfig.current = internalInit;
    getInternalActions(store)._syncConfig(internalInit);
  });

  // Recompute phase: the derived-state inputs, off the layout-effect path.
  useEffect(() => {
    if (externalStore) return;
    const last = lastRecompute.current;
    if (last !== null && !sliceChanged(last, internalInit, RECOMPUTE_KEYS)) return;
    lastRecompute.current = internalInit;
    checkDevGuardrails(internalInit, prevColumns.current, prevData.current);
    checkDuplicateColumnIds(internalInit.columns, warnedDuplicateColumnIds.current);
    prevColumns.current = internalInit.columns;
    prevData.current = internalInit.data;
    getInternalActions(store)._syncProps(internalInit);
    checkUnresolvableColumnTypes(internalInit.columns, store.getState().cellTypes, warnedColumnTypes.current);
  });

  return { store, actions: store.getState().actions };
}

/**
 * Provides the grid's store to the component subtree. By default it self-creates the store via
 * the same ownership core as {@link useDataGridStoreProps}; pass `store` to serve a
 * consumer-created store instead — then this component is a pure context shell and the sync
 * loop lives on the consumer's `useDataGridStoreProps` call. `ref` receives the grid's imperative handle.
 */
export function DataGridProvider<TData>(props: DataGridProviderProps<TData>): ReactNode {
  const { store: externalStore, children, ref, ...syncProps } = props;
  // The prop union makes a sync prop next to `store` a compile error; this catches a cast/untyped caller.
  if (externalStore && Object.values(syncProps).some((v) => v !== undefined)) {
    warnExternalStoreSyncPropsOnce();
  }
  // The rest's external-store branch types the sync keys as never; the core reads none of them when `externalStore` is set.
  const { store } = useGridStoreCore<TData>(syncProps as DataGridSyncProps<TData>, externalStore);
  useImperativeHandle(ref, () => apiHandleOf<TData>(store), [store]);
  // useId is hydration-safe and distinct per provider instance — two grids on one page each get their own id.
  const instanceId = useId();
  return (
    <DataGridStoreContext.Provider value={store}>
      <GridInstanceIdContext.Provider value={instanceId}>{children}</GridInstanceIdContext.Provider>
    </DataGridStoreContext.Provider>
  );
}

/** Resolves the current grid's store, throwing with a clear message outside the provider. */
function useDataGridStoreApiInternal(): StoreApi<DataGridStoreState> {
  const store = use(DataGridStoreContext);
  if (!store) {
    throw new Error("gridcn: this hook must be used inside a <DataGridProvider>.");
  }
  return store;
}

export function useDataGridStore<T>(selector: (state: DataGridStoreState) => T): T {
  return useStore(useDataGridStoreApiInternal(), selector);
}

/**
 * Typed raw store selector for the current grid: `TData` types `state.data`, so a selector that
 * reads rows gets them back typed (the same erasure-boundary guarantee as the provider — every
 * row in `state.data` originated from this grid's own `TData`-typed `data`/`defaultData` prop).
 * Both type arguments are explicit at the call (`useDataGridSelector<Row, readonly Row[]>((s) => s.data)`);
 * prefer {@link createDataGridSelector}, which fixes `TData` at the factory and infers the result.
 * `eq` (default `Object.is`) controls re-renders, like `useStore`.
 */
export function useDataGridSelector<TData, TResult>(
  selector: (state: DataGridStoreStateOf<TData>) => TResult,
  eq?: (a: TResult, b: TResult) => boolean,
): TResult {
  return useStoreWithEqualityFn(useDataGridStoreApiInternal(), (s) => selector(s as DataGridStoreStateOf<TData>), eq);
}

/**
 * Creates a typed raw store selector with `TData` fixed at the factory call: the returned hook
 * hands its selector `state.data` typed as `readonly TData[]` and infers the result type, so the
 * common one-type-argument form compiles without a second annotation. `eq` (default `Object.is`)
 * controls re-renders, like `useStore`.
 */
export function createDataGridSelector<TData>() {
  return function useDataGridSelector<TResult>(
    selector: (state: DataGridStoreStateOf<TData>) => TResult,
    eq?: (a: TResult, b: TResult) => boolean,
  ): TResult {
    return useStoreWithEqualityFn(useDataGridStoreApiInternal(), (s) => selector(s as DataGridStoreStateOf<TData>), eq);
  };
}

/**
 * Override for internal engine components that need imperative `getState()`
 * access in event handlers. Not for consumer use.
 * @internal
 */
export function useDataGridStoreApi(): StoreApi<DataGridStoreState> {
  return useDataGridStoreApiInternal();
}

import type { GridAction, Keymap } from "../types";
import type { DataGridPlugin, GridCommand } from "../types";
import { BUILTIN_ACTIONS, DEFAULT_KEYMAP, PLUGGABLE_ACTIONS } from "../keyboard";
import type {
  ResolvedBandSegment,
  ResolvedPluginMount,
  ResolvedPluginOverlay,
  ResolvedPlugins,
  PluginDataChangeObserver,
} from "./types";

/** The shared empty identity: a grid with no plugins never allocates a fresh resolved object per config sync. */
export const EMPTY_PLUGINS: ResolvedPlugins = {
  list: [],
  overlays: [],
  bands: { top: [], bottom: [] },
  mounts: [],
  observers: [],
};

/** A dev warning that fires at most once per key per store (resolution re-runs on list changes; a static conflict must not re-warn per change). */
export type PluginWarnOnce = (key: string, message: string) => void;

/**
 * Whether two `plugins` props resolve to the same plugins: same length, the same `name` per entry,
 * and every member (`Overlay`, `rowBands`, `onDataChange`, `commands`, `keymap`, `Mount`) kept its
 * identity. An equal list reuses `state.plugins` (and the merged `commands`/`keymap`), so an
 * inline `plugins={[fill.plugin, …]}` array with stable members changes nothing.
 */
export function pluginsListEqual(a: readonly DataGridPlugin[] | undefined, b: readonly DataGridPlugin[] | undefined): boolean {
  if (a === b) return true;
  if (!a || !b || a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    const pa = a[i]!;
    const pb = b[i]!;
    if (pa.name !== pb.name || pa.Overlay !== pb.Overlay || pa.rowBands !== pb.rowBands || pa.onDataChange !== pb.onDataChange) {
      return false;
    }
    if (pa.commands !== pb.commands || pa.keymap !== pb.keymap || pa.Mount !== pb.Mount) return false;
  }
  return true;
}

/** plugin object -> the store whose mounted grid holds it; a plugin instance attaches to ONE grid. */
const pluginAttachments = new WeakMap<object, object>();

function ownedByAnotherStore(plugin: DataGridPlugin, store: object): boolean {
  const owner = pluginAttachments.get(plugin);
  return owner !== undefined && owner !== store;
}

/**
 * Claims each plugin for `store` (call from a mount effect) and drops the ones another live grid
 * already holds, dev-warning once per dropped plugin. `release` frees the claims this call made.
 */
export function claimPluginAttachments(
  list: readonly DataGridPlugin[],
  store: object,
  warn: PluginWarnOnce,
): { kept: readonly DataGridPlugin[]; release: () => void } {
  const kept: DataGridPlugin[] = [];
  for (const plugin of list) {
    if (ownedByAnotherStore(plugin, store)) {
      warn(
        `attach:${plugin.name}`,
        `plugin "${plugin.name}" is already attached to another grid; a plugin instance attaches to one grid — pass a fresh plugin object (the add-on hook's result) to each grid`,
      );
      continue;
    }
    pluginAttachments.set(plugin, store);
    kept.push(plugin);
  }
  return {
    kept: kept.length === list.length ? list : kept,
    release: () => {
      for (const plugin of kept) if (pluginAttachments.get(plugin) === store) pluginAttachments.delete(plugin);
    },
  };
}

/**
 * Dev-warns once per plugin whose `Overlay` or `Mount` identity changed between `oldList` and
 * `newList` (same `name`): the new component identity remounts the component and loses its state.
 */
export function warnPluginComponentRemounts(
  oldList: readonly DataGridPlugin[],
  newList: readonly DataGridPlugin[],
  warn: PluginWarnOnce,
): void {
  for (const next of newList) {
    const prev = oldList.find((p) => p.name === next.name);
    if (!prev) continue;
    if (prev.Overlay !== undefined && prev.Overlay !== next.Overlay) {
      warn(`remount-overlay:${next.name}`, `plugin "${next.name}"'s Overlay component identity changed; the overlay remounts and loses its state`);
    }
    if (prev.Mount !== undefined && prev.Mount !== next.Mount) {
      warn(`remount-mount:${next.name}`, `plugin "${next.name}"'s Mount component identity changed; the mount remounts and loses its state`);
    }
  }
}

/**
 * Builds the resolved plugin members from the claimed list (duplicate `name`s dev-error and the
 * later plugin is ignored; members keep array order). Runs only when the list actually changes, so
 * the conflict warnings below do not re-fire on every render of an unchanged inline array.
 */
export function resolvePlugins(list: readonly DataGridPlugin[], warn: PluginWarnOnce): ResolvedPlugins {
  if (list.length === 0) return EMPTY_PLUGINS;
  const seen = new Set<string>();
  const unique: DataGridPlugin[] = [];
  for (const plugin of list) {
    if (seen.has(plugin.name)) {
      warn(
        `name:${plugin.name}`,
        `two plugins named "${plugin.name}"; the later one is ignored — the name is the plugin's React key and its identity`,
      );
      continue;
    }
    seen.add(plugin.name);
    unique.push(plugin);
  }
  const overlays: ResolvedPluginOverlay[] = [];
  const mounts: ResolvedPluginMount[] = [];
  const observers: PluginDataChangeObserver[] = [];
  const bands = { top: [] as ResolvedBandSegment[], bottom: [] as ResolvedBandSegment[] };
  for (const plugin of unique) {
    if (plugin.Overlay) overlays.push({ name: plugin.name, Overlay: plugin.Overlay });
    if (plugin.Mount) mounts.push({ name: plugin.name, Mount: plugin.Mount });
    if (plugin.onDataChange) observers.push(plugin.onDataChange);
    if (plugin.rowBands) {
      const { top, bottom, render } = plugin.rowBands;
      if (top && top.length > 0) bands.top.push({ name: plugin.name, rows: top, render });
      if (bottom && bottom.length > 0) bands.bottom.push({ name: plugin.name, rows: bottom, render });
    }
  }
  return { list, overlays, bands, mounts, observers };
}

/**
 * The merged command map: the plugins' commands in array order (the later plugin wins a name
 * conflict, dev-warned; a built-in action name is dropped, dev-warned, unless pluggable), then the
 * consumer's `commands` over everything (the app owner's explicit choice, silently). `null` when
 * nothing lands.
 */
export function mergePluginCommands(
  plugins: readonly DataGridPlugin[],
  consumerCommands: Record<string, GridCommand<unknown>> | null | undefined,
  warn: PluginWarnOnce,
): Record<string, GridCommand<unknown>> | null {
  const merged: Record<string, GridCommand<unknown>> = {};
  const sourceOf: Record<string, string> = {};
  for (const plugin of plugins) {
    if (!plugin.commands) continue;
    for (const [name, command] of Object.entries(plugin.commands)) {
      const builtin = (BUILTIN_ACTIONS as readonly string[]).includes(name);
      if (builtin && !PLUGGABLE_ACTIONS.includes(name)) {
        warn(
          `cmd-builtin:${plugin.name}:${name}`,
          `plugin "${plugin.name}"'s command "${name}" names a built-in action and is dropped — plugins cannot replace core behavior (undo, redo, fillDown, fillRight, openFindReplace are the pluggable exceptions)`,
        );
        continue;
      }
      const prior = sourceOf[name];
      if (prior !== undefined) {
        warn(`cmd-conflict:${name}:${prior}:${plugin.name}`, `plugins "${prior}" and "${plugin.name}" both define command "${name}"; the later plugin wins`);
      }
      merged[name] = command;
      sourceOf[name] = plugin.name;
    }
  }
  if (consumerCommands) Object.assign(merged, consumerCommands);
  return Object.keys(merged).length > 0 ? merged : null;
}

/**
 * The merged keymap: `DEFAULT_KEYMAP` <- the plugins' keymaps (array order; an entry naming a
 * command the plugin does not define, or naming no built-in action, is dropped, dev-warned; a
 * binding the default keymap or the consumer's `keymap` already uses is dropped, dev-warned) <- the
 * consumer's `keymap` (always last, and wins).
 */
export function mergePluginKeymaps(
  plugins: readonly DataGridPlugin[],
  consumerKeymap: Keymap | undefined,
  warn: PluginWarnOnce,
): Keymap {
  const merged: Keymap = { ...DEFAULT_KEYMAP };
  for (const plugin of plugins) {
    if (!plugin.keymap) continue;
    for (const [name, bindings] of Object.entries(plugin.keymap)) {
      const pluginOwnsIt = Boolean(plugin.commands) && name in (plugin.commands as Record<string, GridCommand<unknown>>);
      if (!(BUILTIN_ACTIONS as readonly string[]).includes(name) || !pluginOwnsIt) {
        warn(
          `keymap-unknown:${plugin.name}:${name}`,
          `plugin "${plugin.name}"'s keymap binds "${name}" but the plugin defines no such command; the entry is dropped — a plugin keymap binds the plugin's own commands only`,
        );
        continue;
      }
      const taken = [...(DEFAULT_KEYMAP[name as GridAction] ?? []), ...(consumerKeymap?.[name as GridAction] ?? [])];
      const kept = (bindings ?? []).filter((binding) => !taken.includes(binding));
      if (kept.length < (bindings ?? []).length) {
        warn(
          `keymap-collide:${plugin.name}:${name}`,
          `plugin "${plugin.name}"'s binding for "${name}" uses a key the grid's default keymap or the consumer's keymap already owns; the colliding binding is dropped — a plugin never takes a key the grid or the app already uses`,
        );
      }
      if (kept.length > 0) merged[name as GridAction] = kept;
    }
  }
  if (consumerKeymap) Object.assign(merged, consumerKeymap);
  return merged;
}

/** Resolves one grid's plugin list, skipping plugins another live grid holds; an absent list is the shared empty identity. */
export function resolvePluginsList(list: readonly DataGridPlugin[] | undefined, store: object, warn: PluginWarnOnce): ResolvedPlugins {
  if (!list || list.length === 0) return EMPTY_PLUGINS;
  const free = list.filter((plugin) => !ownedByAnotherStore(plugin, store));
  return resolvePlugins(free.length === list.length ? list : free, warn);
}

import type { ComponentType, ReactNode, Ref } from "react";
import type { StoreApi } from "zustand/vanilla";
import type { ColumnGroupModel } from "../columns/column-groups";
import type {
  CellRef,
  ViewCellRef,
  ViewCoord,
  AutosizeOptions,
  CellType,
  ColumnDef,
  ColumnGroupDef,
  ColumnLayout,
  DataChange,
  DataGridApi,
  DataGridPlugin,
  FilterJoinOperator,
  FilterSpec,
  GridCommand,
  GridEditEndEvent,
  GridSelection,
  GridValidationErrorEvent,
  GridBulkValidationError,
  HeaderClickBehavior,
  Keymap,
  OnCellClick,
  OnCellContextMenu,
  OnCellDoubleClick,
  RowMarkersMode,
  SelectionState,
  SearchOptions,
  SortSpec,
} from "../types";
import type { RowBandRenderCtx } from "../layout-context";
import type { OverlayPluginCtx } from "../overlays";
import type { DataGridLabels, DeepPartialLabels } from "../labels";
import type { SearchMatch } from "../sort-filter";
import type { ExtendDirection, SelectLineOptions } from "../selection";
import type { ColRange } from "../selection/selected-col-ranges-for-row";
import type { DataWriteContext } from "./data-write";

/** The lazily-read context `DataGridRoot` registers for {@link DataGridActions.autosizeColumns}. */
/** The input that wrote the current selection. */
export type SelectionPointer = "touch" | "mouse" | "pen" | "keyboard";

export type AutosizeMeasureContext = {
  /** The computed `font` of one mounted body cell (canvas `measureText` font). */
  cellFont: string;
  /** The computed `font` of one mounted header cell (headers render `font-medium`). */
  headerFont: string;
  /** The currently mounted view-row window `[start, end)`, or `null` when no rows are mounted. */
  window: { start: number; end: number } | null;
  /** The consumer renders a per-column header-menu trigger (adds its fixed width allowance). */
  hasHeaderMenu: boolean;
  /** The consumer renders a per-column header-filter button (adds its fixed width allowance to columns with a set filter). */
  hasHeaderFilter: boolean;
};

/** Live props synced from the consumer's render into the store on every change, typed over the consumer's row shape. */
export type DataGridSyncProps<TData = unknown> = {
  /**
   * Controlled row array (React `value` semantics): the app owns it, and every mutation
   * (edit/paste/fill/delete/row-ops) only ever reaches it through `onDataChange` — the grid's own
   * display doesn't change until the next render supplies a new `data`. Mutually exclusive with
   * `defaultData`; when both are given, `data` wins (dev-mode warns once). Omit `data` and pass
   * `defaultData` instead for the uncontrolled mode.
   */
  data?: readonly TData[];
  /**
   * Uncontrolled row array (React `defaultValue` semantics): seeds the store ONCE at creation and
   * the store then OWNS it — every mutation applies internally with no app-side state required;
   * `onDataChange` still fires as an optional notification. Changing this prop on a later render is
   * ignored (uncontrolled, matching `<input defaultValue>`). Mutually exclusive with `data` — see
   * that prop's doc for precedence.
   */
  defaultData?: readonly TData[];
  // ColumnDef's 3rd param (TValidate) erases to `any`, not `unknown` — see AnyColumnDef's doc in
  // this file: `validate`'s function-or-schema union can't stay bivariant as a plain property, so
  // a defineColumns literal's narrow-TValue `validate` needs this documented widening to fit here.
  columns: readonly ColumnDefOf<TData>[];
  /**
   * Stable, unique id of a row. Defaults to the row's `id` field (string or number) and throws
   * for a row without one. Pass it when rows have no `id` or the id lives elsewhere.
   */
  getRowId?: (row: TData, index: number) => string;
  /**
   * Disables editing and delete grid-wide, independent of any per-column `readOnly`. The store is
   * the home of this flag: it is seeded from these init props (so SSR and the first client paint
   * already see it) and kept in sync by the provider's config phase — `DataGridRoot`,
   * interaction, and clipboard read `state.readOnly` at event/render time, so a flip to `true`
   * blocks the next keydown before any passive effect runs and cancels an open edit session.
   * Default `false`.
   */
  readOnly?: boolean;
  /**
   * Merged over `DEFAULT_KEYMAP` at the store (per-action bindings here take precedence; an
   * action mapped to `[]` unbinds it). `state.keymap` holds the merged result and keeps its
   * reference while this prop's entries are content-equal, so an inline `keymap={{ … }}` literal
   * does not churn the interaction memos. Surfaces outside `DataGridRoot` (the keybindings dialog)
   * read `state.keymap` via {@link useDataGridKeymap}.
   */
  keymap?: Keymap;
  /** Fired once per user gesture with the next data array and a row-id-based delta batch, after the grid stores that array. */
  onDataChange?: (next: readonly TData[], change: DataChange<TData>) => void;
  /**
   * Row-level cross-field validation, run once per touched row after a write gesture commits
   * (edit, paste, fill, delete-contents, updateCells/updateRows) — the row already has ALL of the
   * gesture's cells applied, so the verdict is independent of column order inside a paste. Return
   * `columnId -> message` to surface errors (they land in `cellErrors`, same display as server
   * errors), `null` when the row is fine. Values still commit either way. Not run on row
   * insert/duplicate/delete or on consumer `data` replacement. Sync only.
   */
  validateRow?: (row: TData, rowId: string) => Record<string, string> | null;
  /**
   * Custom cell types keyed by `ColumnDef.type`, merged OVER the built-in registry — built-ins
   * you do not name keep working. A `null` entry removes a built-in (or a previously provided
   * type); the grid then renders its columns with the `text` fallback and dev-warns about the
   * unresolvable type. An inline object literal is fine: the grid rebuilds the registry only
   * when an entry changes identity, so define each type once, outside render.
   */
  cellTypes?: Record<string, AnyCellType | null>;
  /** Overrides a cell's clipboard-copy text; falls back to the cell type's `toText`. */
  processCellForClipboard?: (value: unknown, ctx: ClipboardProcessCtx<TData>) => string;
  /** Overrides parsing pasted text into a cell value; falls back to the cell type's `fromText`. */
  processCellFromClipboard?: (text: string, ctx: ClipboardProcessCtx<TData>) => unknown;
  /** Runs on the parsed paste grid before it's applied; returning `false` vetoes the paste entirely. */
  processPaste?: (ctx: { cells: string[][]; target: ViewCoord }) => string[][] | false;
  /**
   * Prefixes formula-like copied cells (leading `=`, `+`, `-`, `@`, TAB, or CR; plain numbers
   * exempt) with `'` in the clipboard text and HTML, for Ctrl+C/Ctrl+X and the context menu's
   * Copy/Cut. A paste back into gridcn still restores the raw value. Default `false`.
   */
  sanitizeClipboardFormulas?: boolean;
  /** Marker column mode; default 'none'. See {@link RowMarkersMode}. */
  rowMarkers?: RowMarkersMode;
  /** Whole-row selection channel gestures (marker click, Shift+Space); default true. */
  enableRowSelection?: boolean;
  /**
   * Keeps the checked rows when a cell is selected (click, arrows, Shift or Ctrl click) and makes
   * row operations (delete, duplicate, move, the cell menu's row items) act only on the checked
   * rows while any exist. Escape, the checkboxes, and `clearSelection` still change the checks. Default `false`.
   */
  keepCheckedRows?: boolean;
  /** Whole-column selection channel gestures (header click); default true. */
  enableColumnSelection?: boolean;
  /** Multi-cell rectangular range gestures (shift-click/drag, shift+arrow); false collapses to single-cell active only. Default true. */
  enableRangeSelection?: boolean;
  /** Ctrl/Cmd-click multi-range (rangeStack); false makes it behave as a plain click. Default true. */
  enableMultiRange?: boolean;
  /** Enables the header resize handle grid-wide; default true. Per-column `resizable: false` still wins. */
  enableColumnResize?: boolean;
  /** Enables drag-to-reorder columns grid-wide; default true. Per-column `reorderable: false` still wins. */
  enableColumnReorder?: boolean;
  /**
   * Enables drag-to-reorder rows grid-wide; default true. The gesture is zone-based: it lives on
   * the marker's `reorder`-family modes only (`reorder`, `reorder-number`, `reorder-checkbox`,
   * `reorder-both`) and only from the drag handle zone (the drag handle + cell background, or the whole
   * cell in `reorder` mode) — plain `number`/`checkbox`/`both` markers stay pure row-select
   * surfaces, and within the reorder family the number/checkbox glyphs and Shift+drag always
   * stay the row-select gesture, so a selection drag never reorders.
   */
  enableRowReorder?: boolean;
  /** Enables pin/unpin actions grid-wide; default true. Per-column `pinnable: false` still wins. */
  enableColumnPinning?: boolean;
  /** How a plain header click behaves; default 'select'. See {@link HeaderClickBehavior}. */
  headerClickBehavior?: HeaderClickBehavior;
  /** Partial i18n override, deep-merged over {@link DEFAULT_LABELS}; see {@link useDataGridLabels}. */
  labels?: DeepPartialLabels;
  /** Builds a new row for `insertRow`; absent makes `insertRow` a dev-warning no-op (duplicateRows/deleteRows don't need it). */
  createRow?: (index: number) => TData;
  /**
   * Builds a duplicated row's identity for `duplicateRows`: given the
   * source row and its new data index, returns the row to insert (with a distinct id, e.g. a fresh
   * UUID, so the copy's `getRowId()` never collides with its source's React key). Absent makes
   * `duplicateRows` a dev-warning no-op — mirrors `createRow`/`insertRow`.
   */
  duplicateRow?: (row: TData, index: number) => TData;
  /**
   * Consumer-defined keyboard commands keyed by name — the dispatch target of keymap bindings
   * that name no built-in action (see {@link GridCommand}). A name that shadows a built-in action
   * wins over it (dev-warned once). Pass a stable reference.
   */
  commands?: Record<string, GridCommand<TData>>;
  /**
   * Controlled multi-sort spec. Standard controlled-input
   * semantics: omitted (undefined) keeps today's uncontrolled behavior — the store owns
   * `sortState`. Provided (even `[]`) makes this prop the source of truth every `_syncProps` sync
   * writes into the store; `onSortChange` still fires on every user-driven change (header click,
   * `setSorts`) either way, but in controlled mode the displayed order only moves once the prop
   * itself changes — a controlled grid whose consumer ignores the callback stays visually fixed.
   */
  sortState?: SortSpec[];
  /**
   * Who orders the rows. `"client"` (default): the grid sorts `data` by `sortState`. `"server"`:
   * the grid only tracks the spec (header click cycle, `aria-sort`, sort indicator, `onSortChange`)
   * and never reorders `data`; the consumer fetches rows in that order, e.g. with `useDataGridLazyRows`.
   */
  sortMode?: "client" | "server";
  /** Seeds the sort ONCE at store creation (uncontrolled, like `defaultData`); later changes are ignored. `sortState` wins when both are given. */
  defaultSortState?: SortSpec[];
  /** Fires whenever the user (or `actions.toggleSort`/`setSorts`) would change the sort, controlled or not; see `sortState`. */
  onSortChange?: (next: SortSpec[]) => void;
  /** Controlled filter spec; same controlled/uncontrolled semantics as `sortState`. */
  filterState?: FilterSpec[];
  /** Seeds the filters ONCE at store creation; see `defaultSortState`. */
  defaultFilterState?: FilterSpec[];
  /** Fires whenever the user (or `actions.setFilters`) would change the filters, controlled or not; see `filterState`. */
  onFilterChange?: (next: FilterSpec[]) => void;
  /** Controlled join operator combining `filterState`'s rows; same controlled/uncontrolled semantics as `sortState`. Default `"and"`. */
  joinOperator?: FilterJoinOperator;
  /** Seeds the join operator ONCE at store creation; see `defaultSortState`. */
  defaultJoinOperator?: FilterJoinOperator;
  /** Fires whenever the user (or `actions.setJoinOperator`) would change the join operator, controlled or not; see `joinOperator`. */
  onJoinOperatorChange?: (next: FilterJoinOperator) => void;
  /** Controlled quick-search text; same controlled/uncontrolled semantics as `sortState`. */
  searchText?: string;
  /** Seeds the quick-search text ONCE at store creation; see `defaultSortState`. */
  defaultSearchText?: string;
  /** Fires whenever the user (or `actions.setSearch`) would change the search text, controlled or not; see `searchText`. */
  onSearchTextChange?: (next: string) => void;
  /**
   * Installed plugins (add-ons that reach into the grid): overlay layers, row bands, data-change
   * observers, commands, keymap bindings, and root mounts — one seam instead of one per add-on.
   * Resolved at store creation (so SSR has band heights and `aria-rowcount`) and re-resolved in
   * the config phase only when the list actually changes: an entry is unchanged when its `name`
   * and every member keep their identity, so an inline `plugins={[fill.plugin, …]}` array is fine.
   * Array order is precedence and visual order (overlays paint in order, later on top; top bands
   * stack from the header down; bottom bands stack top to bottom; `Mount`s and observers run in
   * order). A plugin object attaches to ONE grid — a second grid resolving the same object is a
   * dev error. The list is row-shape-agnostic: a typed `DataGridPlugin<TData>` is assignable to it,
   * and an inline plugin's `onDataChange` observer sees `unknown` rows. See {@link DataGridPlugin}.
   */
  plugins?: readonly DataGridPlugin<unknown>[];
  /**
   * Seeds `columnWidths`/`columnOrder`/`hiddenColumns`/per-column `pin` ONCE at store creation,
   * over the `columns` prop's own def defaults (`resolveColumnWidth` precedence: layout beats def).
   * Deliberately NOT a controlled prop — later changes to this value are ignored (uncontrolled
   * with events); pair it with `onColumnLayoutChange` to save/restore
   * a user's layout (e.g. to localStorage) without a fully-controlled overlay fighting the defs.
   * Partial layouts are normalized the same way `columnLayout` is: unknown column ids are dropped,
   * `order` gets missing ids appended in def order, widths are clamped, and pins on
   * `pinnable: false` columns are dropped.
   */
  defaultColumnLayout?: Partial<ColumnLayout>;
  /**
   * Controlled column layout (React `value` semantics, gesture-first like `selection`): each
   * provided part (`widths`, `order`, `pins`, `hidden`) replaces that part, and an omitted part
   * stays uncontrolled — the store keeps its current value for it, so
   * `columnLayout={{ widths }}` controls only widths and a user reorder survives. A gesture
   * writes the store at once and fires `onColumnLayoutChange`; a `columnLayout` prop that changes
   * identity, is not an echo of a value the grid just fired, and differs from the grid's current
   * snapshot then overrides the store. Omitted (undefined) keeps the uncontrolled behavior
   * (store-owned, with events).
   */
  columnLayout?: Partial<ColumnLayout>;
  /**
   * Shared headers above runs of columns, by column id; groups nest. The columns stay flat. A group
   * keeps its columns next to each other: reorder moves a column inside its group and a group as a
   * block, and a saved or restored `order` that splits a group is repaired. Unknown ids, a column
   * listed twice, a repeated group id, and nesting deeper than 8 levels are dropped. Pass a stable
   * identity for `header` nodes.
   */
  columnGroups?: readonly ColumnGroupDef[];
  /**
   * Runs one {@link DataGridActions.autosizeColumns} pass after mount, when the view first has
   * rows (a lazy grid waits for its first page); it runs once per mount. Columns with a saved
   * width (`columnWidths`) keep it — a saved layout wins. `true` uses the action's defaults;
   * an options object narrows the pass.
   */
  autosizeOnMount?: boolean | AutosizeOptions;
  /**
   * Fires once per committed column-layout change (resize drag release/autosize, reorder drop,
   * pin/unpin, show/hide, `setColumnLayout`) with the full current `ColumnLayout` snapshot -
   * never per drag frame, and never when nothing changed. Fired from the store actions layer, no
   * React-render dependency. See `defaultColumnLayout` for the seed path and `columnLayout` for
   * the controlled one.
   */
  onColumnLayoutChange?: (next: ColumnLayout) => void;
  /**
   * Controlled selection (React `value` semantics, gesture-first): a gesture writes the store at
   * once and fires this callback; a `selection` prop that changes identity, is not an echo of a
   * value the grid just fired, and differs structurally from the grid's current value then
   * overrides the store. An applied value with an `anchor` moves the active cell to the anchor
   * (a normal cursor move: `onActiveCellChange` fires); without an anchor the cursor stays.
   * Omitted (undefined) keeps the uncontrolled behavior (store-owned, with events). Mutually
   * exclusive with `defaultSelection`; when both are given, `selection` wins (dev-mode warns once).
   */
  selection?: SelectionState;
  /**
   * Seeds the selection ONCE at store creation (React `defaultValue` semantics): the value
   * resolves against the initial data/columns, and a resolved `anchor` also seeds the initial
   * active cell. Later changes to this value are ignored (uncontrolled, like `defaultData`),
   * which also means a consumer `data` swap never re-applies it. Mutually exclusive with
   * `selection` - see that prop's doc for precedence.
   */
  defaultSelection?: SelectionState;
  /**
   * Fires on every committed selection change (click, extend step, range push, row/column/all
   * selection, clear) with the current selection in stable {@link SelectionState} terms plus a
   * lazy `details.getValues()` accessor. Fires only when the derived `SelectionState` differs
   * structurally from the grid's last known value, so a view rebuild that re-projects the same
   * records (a sort that keeps the selection's rows) fires nothing. A drag-extend gesture fires
   * once per step (intended - the presence/broadcast use case wants live updates, not just the
   * final drop) - `getValues()` is a function, not a materialized array, specifically so that
   * hot path never pays for building a value matrix on steps nobody reads.
   */
  onSelectionChange?: (next: SelectionState, details: SelectionChangeDetails) => void;
   /**
    * Fires when the active cell changes to a different cell, when it follows its record or column to
    * another view position (a sort, filter, data change, column hide, reorder, or pin), when another
    * record comes under it (a lazy row load, or a clamp after its row or column left the view), or
    * when it is cleared (`null`). Re-selecting the same cell on the same record and column does not fire.
    */
   onActiveCellChange?: (next: ViewCellRef | null) => void;
   /**
    * Fired when an edit session is about to start (Enter/F2, type-to-replace, double-click) with
    * the target cell's ids and view position. Return `false` to VETO the edit — `startEditing`
    * then makes no state change at all (no session, no cursor move). Checkbox cells never start an
    * edit session, so the veto never applies to them.
    */
   onEditStart?: (cell: ViewCellRef) => boolean | void;
   /**
    * Fired when an edit session ends or a commit attempt is refused — `commit` after the session
    * closes, `cancel` when the draft is discarded (including a remap that drops the edited cell),
    * `rejected` when validation refused a commit and the session stays open (fires per attempt).
    * See {@link GridEditEndEvent}.
    */
   onEditEnd?: (event: GridEditEndEvent) => void;
   /**
    * Fires after a bulk paste, a fill, or an `updateCells` call settles, only when at least one cell
    * was rejected by validation — the accepted cells are applied first. See {@link GridValidationErrorEvent}.
    */
   onValidationError?: (event: GridValidationErrorEvent) => void;
   /** Fired on a double-click on any non-pinned, non-skeleton cell — pure notification, no veto. See {@link OnCellDoubleClick}. */
   onCellDoubleClick?: OnCellDoubleClick<TData>;
   /** Fired when the user right-clicks any non-pinned, non-skeleton cell — pure notification. See {@link OnCellContextMenu}. */
   onCellContextMenu?: OnCellContextMenu<TData>;
    /**
     * Fired on a plain click on any cell — see {@link OnCellClick}. Fired from the cell's own
     * existing click handler (no new subscription); the cell reads it from the store at click
     * time, so an identity change re-renders no cell. Pass a stable identity (e.g. `useCallback`)
     * to keep the store's config sync from running once per render with a new callback.
     */
    onCellClick?: OnCellClick<TData>;
    /**
     * Fired after a row-window commit with the rendered data-row range `[start, end)` (inclusive
     * start, exclusive end — same convention as `useRowWindow`'s `RowWindow`). Only fires when the
     * range actually changed since the last call, including once for the initial mount commit; a
     * scroll tick that stays within the current window's overscan buffer does not re-fire it.
     * Useful for lazy-loading/prefetch/analytics add-ons; core has no fetching logic of its own.
     */
    onRenderedRowsChange?: (range: { start: number; end: number }) => void;
    /**
     * Fires on every live width write during a resize drag (`actions.setColumnWidth`, per drag
    * frame) — the in-progress counterpart to `onColumnLayoutChange`'s once-per-commit snapshot.
   * Fired from the store actions layer, no React-render dependency. Not called for the commit
   * itself (drag release/autosize) — pair with `onColumnLayoutChange` if you need that too.
   */
  onColumnResizing?: (ctx: { columnId: string; width: number }) => void;
};

/**
 * Second argument to `onSelectionChange`. `getValues()` reads the CURRENT `next.range` only — a
 * multi-range selection (ctrl-click stack) is not flattened or concatenated, matching clipboard
 * copy's own "primary range only" scope (`resolveCopyScope`) — call it once per range in
 * `next.rangeStack` yourself if you need the others. Returns `[]` when there's no active range
 * (row/column-channel-only selection, or a clear). Deliberately lazy: built fresh from the store
 * snapshot only when called, so a consumer that ignores it (the common case) never pays for
 * reading/allocating a value matrix on every drag step.
 */
export type SelectionChangeDetails = {
  /** Raw cell VALUES (not clipboard text) over the primary range, view-row-major: `values[0][0]` is the range's top-left cell. */
  getValues: () => unknown[][];
  /** Row ids of every selected row, view order, across both the row channel (checkboxes) and any cell range. */
  getRowIds: () => string[];
};

// The store is generic-erased to TData = unknown past this boundary (InternalSyncProps below): one
// runtime engine serves every consumer's row type, and unknown (not never) keeps every ColumnDef
// function field (accessorFn/setValue/readOnly/validate) callable with the store's own `row: unknown`
// values with no cast needed — safe because a column and the row it's called with always came from
// the same consumer-typed `data` array passed in through DataGridSyncProps<TData>. This is also what
// useDataGridVisibleColumns/useDataGridAllColumns return, so a consumer building custom column UI can
// call those same fields without a cast either.
/** `DataGridSyncProps` cast to the store's internal row-agnostic shape; the one unsafe cast, applied once at the boundary. */
export type InternalSyncProps = Omit<DataGridSyncProps<unknown>, "getRowId"> & { getRowId: (row: unknown, index: number) => string };

/** The overlay contribution of one resolved plugin: the component plus its `name` (the React key). */
export type ResolvedPluginOverlay = { name: string; Overlay: ComponentType<OverlayPluginCtx> };

/** The root-mount contribution of one resolved plugin: the component plus its `name` (the React key). */
export type ResolvedPluginMount = { name: string; Mount: ComponentType };

/** One band segment of the resolved row bands: one plugin's rows plus its painter. Segments stack in plugin array order (top: header down; bottom: top to bottom). */
export type ResolvedBandSegment = {
  name: string;
  rows: readonly unknown[];
  render: (ctx: RowBandRenderCtx) => ReactNode;
};

/** A data-change observer resolved from a plugin's `onDataChange`: runs after the store write and the consumer's `onDataChange`, each in its own try/catch. */
export type PluginDataChangeObserver = (next: readonly unknown[], change: DataChange<unknown>, ctx: { api: DataGridApi<unknown> }) => void;

/**
 * The `plugins` sync prop resolved into what core consumes, written as ONE store field so the
 * config phase can keep its reference (and the merged `commands`/`keymap` that feed from it)
 * while the list is unchanged. `list` is the raw prop array (entry-identity compare baseline).
 */
export type ResolvedPlugins = {
  list: readonly DataGridPlugin[];
  overlays: readonly ResolvedPluginOverlay[];
  bands: { top: readonly ResolvedBandSegment[]; bottom: readonly ResolvedBandSegment[] };
  mounts: readonly ResolvedPluginMount[];
  observers: readonly PluginDataChangeObserver[];
};

/**
 * `ColumnDef` widened to the store's internal row-agnostic shape (see the erasure comment above).
 * `validate`'s own value type erases to `any` (the third param, not `unknown`) — a union of a
 * function and a non-callable Standard Schema can't stay bivariant as a plain property the way a
 * pure method-shorthand function could, so narrow-`TValue` columns need this one documented,
 * single-field cast to widen into this shared type (see types.ts's `ColumnDef.validate` doc).
 */
export type AnyColumnDef = ColumnDef<unknown, unknown, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/**
 * `ColumnDef<TData, unknown, any>` — the same TValidate-erased-to-`any` widening as `AnyColumnDef`
 * (see its doc comment), but keeping `TData` open for call sites that are still generic over the
 * consumer's row type (sync-prop declarations, the public `useDataGridVisibleColumns`/`useDataGridAllColumns`
 * hooks) rather than already erased to `unknown`. Named once here (was 10 verbatim repeats across
 * store.tsx/data-grid.tsx, each with its own eslint-disable) so the widening reason lives in one place.
 */
export type ColumnDefOf<TData> = ColumnDef<TData, unknown, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/** `processCellForClipboard`/`processCellFromClipboard`'s callback context — named since it repeats identically across both callbacks in both `DataGridSyncProps` and `DataGridProps`. */
export type ClipboardProcessCtx<TData> = { row: TData; column: ColumnDefOf<TData> };

/**
 * `CellType<any, any, any>` — the `cellTypes` registry-prop widening (same single-point `any`
 * erasure as {@link AnyColumnDef}): `Cell`/`Editor` are `FC<...>` (strictly contravariant in their
 * props), so without erasing TData/TValue/TOptions neither the built-ins (concrete TValue) nor a
 * consumer's per-column `CellType<TData, TValue, TOptions>` is cast-free assignable to an
 * erased-to-`unknown` entry type — the registry prop is the one place a spread of the exported
 * `cellTypes` plus a custom type must compile with no cast.
 */
export type AnyCellType = CellType<any, any, any>; // eslint-disable-line @typescript-eslint/no-explicit-any

/** Row id used when `getRowId` is omitted: the row's `id` field. */
export function defaultGetRowId(row: unknown): string {
  const id = (row as { id?: unknown } | null | undefined)?.id;
  if (typeof id === "string" || typeof id === "number") return String(id);
  throw new Error("gridcn: a row has no string or number `id` field. Pass `getRowId` to identify rows.");
}

export function toInternalSyncProps<TData>(props: DataGridSyncProps<TData>): InternalSyncProps {
  return (props.getRowId ? props : { ...props, getRowId: defaultGetRowId }) as unknown as InternalSyncProps;
}

/**
 * Options passed to selectRow/selectColumn actions; mirrors lib/selection's SelectLineOptions
 * (including `from` — the row-marker drag passes its press-row anchor so `replaceFromLast` can
 * replace the channel with exactly the anchor..current span).
 */
export type SelectLineActionOptions = SelectLineOptions;

/**
 * One targeted cell write for {@link DataGridActions.updateCells}, addressed by STABLE ROW ID —
 * never a view or data index. A streaming producer cannot know view coordinates under an active
 * sort, and row ids are already what {@link DataOp} uses, so history survives sort/filter.
 *
 * `TColumnId` defaults to `string` — the store's own untyped shape, which the actions keep (one
 * runtime engine serves every row type). Instantiate it with the union of your columns' `id`s
 * (e.g. `(typeof columns)[number]["id"]` from `defineColumns`'s const output) when building a
 * typed patch list: a typo'd column id then fails to compile instead of skipping at runtime.
 */
export type CellPatch<TColumnId extends string = string> = {
  /** The row's `getRowId()` value. An id not present in `data` is skipped. */
  rowId: string;
  /** Any column id, including a hidden one. An unknown id is skipped. */
  columnId: TColumnId;
  value: unknown;
};

/** One whole-row update for {@link DataGridActions.updateRows}: a partial row shallow-merged per column id. `TColumnId` follows {@link CellPatch}. */
export type RowPatch<TColumnId extends string = string> = {
  rowId: string;
  /** Column id -> new value. Each entry is applied exactly as the matching {@link CellPatch} would be. */
  changes: Readonly<Partial<Record<TColumnId, unknown>>>;
};

/** How a `updateCells`/`updateRows` batch reconciles with an active sort or filter. */
export type UpdateCellsReorder = "defer" | "immediate" | "never";

/** One rowId+columnId target, addressed the same STABLE-ROW-ID way as {@link CellPatch} (no `value` — used only to name a cell for {@link DataGridActions.setCellErrors}/{@link DataGridActions.clearCellErrors}). */
export type CellErrorTarget = {
  /** The row's `getRowId()` value. An id not present in `data` is stored/cleared anyway (see `cellErrors`' doc) and simply never renders. */
  rowId: string;
  columnId: string;
};

/** One entry for {@link DataGridActions.setCellErrors}: the target cell plus its rejection message. */
export type CellErrorEntry = CellErrorTarget & { message: string };

/** Options for {@link DataGridActions.updateCells} and {@link DataGridActions.updateRows}. */
export type UpdateCellsOptions = {
  /**
   * Default `"defer"`.
   * - `"defer"` — values update in place and rows keep their view position; `viewStale` flips.
   *   The view reconciles on the next sort/filter/search change, or on `reconcileView()`. A
   *   `"defer"` batch that touches no active sort or filter column downgrades to `"never"`
   *   automatically, so `viewStale` never flips for a ticker on a non-sort column.
   * - `"immediate"` — moves the patched rows to their new positions now, by removing each one,
   *   re-testing filter membership, and binary-searching it back in under the same comparator chain
   *   a full sort uses. Cost scales with the batch size, not the row count: measured 0.3 / 0.9 /
   *   7.6 ms for 1 / 20 / 256 patched rows at 100k. Batches over
   *   {@link INCREMENTAL_PATCH_LIMIT} rows, a same-tick sort/filter change, or a column with its own
   *   comparator fall back to the full O(n log n) rebuild.
   * - `"never"` — updates in place and never marks the view stale. The caller asserts that no
   *   touched column feeds the sort or filter.
   */
  reorder?: UpdateCellsReorder;
  /** `DataChange` source tag; default `"stream"`. Pass `"edit"` to make the batch undoable. */
  source?: DataChange<unknown>["source"];
  /** Skips each column's `validate`. Default `false`. */
  skipValidation?: boolean;
};

/** One entry of {@link UpdateCellsVerdict.skipped}: a patch that was not applied, with the reason. */
export type UpdateCellsSkip = {
  /** Index of the patch in the `patches` array the action received. */
  patchIndex: number;
  /**
   * `"unknown-row"` — the row id is not in `data`; `"unknown-column"` — the column id is not a
   * known column; `"hole"` — the row is an unloaded lazy hole; `"readonly"` — the column (or the
   * row, via `readOnly(row)`) is read-only; `"invalid"` — the column's `validate` rejected the
   * value; `"no-op"` — the value is `Object.is`-equal to the current one.
   */
  reason: "unknown-row" | "unknown-column" | "hole" | "readonly" | "invalid" | "no-op";
};

/**
 * Verdict of {@link DataGridActions.updateCells} / {@link DataGridActions.updateRows}: what the
 * batch actually did. `applied` counts the cell writes that landed; `skipped` names every patch
 * that did not land and why, so a streaming producer can observe its feed being silently dropped.
 *
 * `pending` is `true` when the batch is HELD for async validation — the verdict then reports
 * nothing about its outcome, and a held batch that is later superseded (a newer `updateCells`, or
 * a row-moving operation) is dropped silently by design; track supersession on your own feed.
 */
export type UpdateCellsVerdict = {
  /** Cell writes applied (0 when nothing applied or the batch is `pending`). */
  applied: number;
  /** Patches that did not apply, with the reason. Empty when `pending`. */
  skipped: UpdateCellsSkip[];
  /** True when the batch is held for async validation. */
  pending: boolean;
  /** Present when `pending`: resolves with the final verdict, or with nothing applied when a newer write superseded the batch. */
  settled?: Promise<UpdateCellsVerdict>;
};

/** Full per-grid interaction + derived state; internally typed over `unknown` rows. */
export type DataGridStoreState = Omit<
  InternalSyncProps,
  | "data"
  | "defaultData"
  | "cellTypes"
  | "commands"
  | "rowMarkers"
  | "enableRowSelection"
  | "keepCheckedRows"
  | "enableColumnSelection"
  | "enableRangeSelection"
  | "enableMultiRange"
  | "enableColumnResize"
  | "enableColumnReorder"
  | "enableRowReorder"
  | "enableColumnPinning"
  | "headerClickBehavior"
  | "labels"
  | "plugins"
  | "defaultColumnLayout"
  | "defaultSelection"
  | "defaultSortState"
  | "defaultFilterState"
  | "defaultJoinOperator"
  | "defaultSearchText"
  | "selection"
  | "columnLayout"
  | "readOnly"
  | "keymap"
> & {
  /** Always defined: controlled mode mirrors the `data` prop every sync; uncontrolled mode seeds from `defaultData` once and the store owns it thereafter (mutated in place by the commit actions). */
  data: readonly unknown[];
  /** Whether `data` is controlled (the `data` prop was defined on the last `_syncProps`/init) — see `data`'s doc comment and `defaultData`. Mirrors the `sortControlled`-style pattern below. */
  dataControlled: boolean;
  /** Row-agnostic view of the cell-type registry; the `never`-typed sync prop is widened once at the store boundary. */
  cellTypes: Record<string, CellType>;
  /** Defaulted (never undefined) — see `resolveSelectionConfig`. */
  rowMarkers: RowMarkersMode;
  enableRowSelection: boolean;
  keepCheckedRows: boolean;
  enableColumnSelection: boolean;
  enableRangeSelection: boolean;
  enableMultiRange: boolean;
  enableColumnResize: boolean;
  enableColumnReorder: boolean;
  enableRowReorder: boolean;
  enableColumnPinning: boolean;
  headerClickBehavior: HeaderClickBehavior;
  activeCell: ViewCoord | null;
  selection: GridSelection;
  /**
   * Two-stage Ctrl+A progression (select-all-progression.ts): which stage the last `selectAll`
   * produced, plus the exact `selection`/`activeCell` object identities it produced them against.
   * Any other action that replaces `selection` or `activeCell` (selectCell/extendTo/pushRange/
   * selectRow/selectColumn/_moveActiveCell/edits/row operations) changes that identity, so `selectAll`
   * detects the mismatch and restarts from stage 1 — no need to instrument every reset site.
   */
  selectAllStage: { stage: "region" | "all"; selection: GridSelection; activeCell: ViewCoord | null } | null;
  /**
   * `coord` is the view anchor, remapped by every viewIndex/visibleColumns rebuild so the editor
   * follows its row; `rowId`/`columnId` are the identity anchor the commit resolves against, so a
   * missed remap can never write the draft into a different row. When the row (or column) leaves
   * the view the session is cancelled and the draft dropped. `session` is unique per started
   * session, so a restart on the same cell still gets a fresh editor.
   */
  editing: { coord: ViewCoord; rowId: string; columnId: string; initialText?: string; session: number } | null;
  /** Transient rejection message from the last failed commitCellEdit; cleared on the next startEditing/commit/cancel. */
  editingError: string | null;
  /**
   * Rejection nonce for the current edit session: increments on every rejected commit attempt
   * (the sync `validate` rejection in `commitCellEdit`, or an async schema resolving with issues
   * via `setEditingError`) and resets to 0 on `startEditing`. Editors re-arm their one-shot commit
   * guard when this changes: a REJECTION is the only signal that the edit is still open and a
   * fresh commit attempt is expected, never "pending cleared", which also happens on
   * Escape/cancel right before the editor unmounts. The store is the single source of truth for
   * both rejection paths.
   */
  editingRejectionCount: number;
  /**
   * Post-commit server-rejection messages, keyed `"rowId:columnId"` — set via
   * `actions.setCellErrors` after an async `onDataChange` round-trip rejects (e.g. a 422), painted
   * with the SAME visual language as a sync `validate` rejection (ring/tint + message,
   * `aria-invalid`). Deliberately NOT part of the edit lifecycle: `setCellErrors`/`clearCellErrors`
   * never touch `data`, never emit a `DataChange`/`onDataChange`, and are excluded from history —
   * this is metadata ABOUT a cell, not a data change. Auto-cleared for a cell the instant ANY write
   * path (`commitCellEdit`, `commitCellValue`, `applyCellUpdates`, `updateCells`, `deleteSelection`)
   * successfully commits a new value there — the user fixed it, so the stale error must not linger;
   * the server can always re-set it if the fix is still wrong. Pruned of any rowId no longer present
   * in `data` on every row-shape change (delete/duplicate/insert/a consumer `data` replacement) —
   * same maintenance discipline as `RowIndexCache`. Always {@link EMPTY_CELL_ERRORS} when empty, so
   * `useDataGridCellErrors`-style reads never allocate on the common no-error path.
   */
   cellErrors: ReadonlyMap<string, string>;
   /**
    * Transient "highlight-what-changed" keys (row id plus column id) currently flashing,
    * auto-cleared per key after `flashCells`'s duration (default 1400 ms — the 1.2 s fade pulse
    * finishes before the key lifts, so the cell never visibly snaps back). NOT a data change: no
    * `DataChange`, no history entry. Always {@link EMPTY_FLASHING_CELLS} identity when empty.
    */
   flashingCells: ReadonlySet<string>;
    /** The `plugins` sync prop resolved (see {@link ResolvedPlugins}); always defined — an absent list resolves to empty members, so overlays/bands/mounts/observers never read undefined. */
  plugins: ResolvedPlugins;
  /** Which input wrote the current selection; touch selections show the selection handles. */
  selectionPointer: SelectionPointer;
  lastHighlightedRow: number | null;
  lastHighlightedCol: number | null;
  columnWidths: Record<string, number>;
  /** `autosizeOnMount` as passed to the provider; the mounted root consumes it once. */
  autosizeOnMount?: boolean | AutosizeOptions;
  /** null = follow the `columns` prop order. */
  columnOrder: string[] | null;
  /** Single source of truth for visibility; seeded with the def-level `hidden` ids at creation and re-seeded when a new `columns` array is passed. */
  hiddenColumns: readonly string[];
  /**
   * The current column-layout snapshot (`widths`/`order`/`pins`/`hidden`), recomputed at every
   * commit point (resize release, reorder, pin, hide, `setColumnLayout`) and at every `columns`
   * swap — never on live resize frames. Its identity is the echo token of the controlled
   * `columnLayout` prop: a prop that is the same object a commit just fired is an echo and
   * applies nothing.
   */
  columnLayout: ColumnLayout;
  /** The validated `columnGroups` prop; null when no group keeps a column. */
  columnGroupModel: ColumnGroupModel | null;
  sortState: SortSpec[];
  /** Mirrors the `sortMode` sync prop; `"server"` keeps `sortState` out of every view rebuild. */
  sortMode: "client" | "server";
  filterState: FilterSpec[];
  /** How `filterState`'s rows combine; default `"and"`. See `FilterJoinOperator`. */
  joinOperator: FilterJoinOperator;
  /** Quick-search text; never affects `viewIndex` (search highlights + navigates, it doesn't filter). */
  searchText: string;
  /** How `searchText` matches; set through `actions.setSearch` and kept across searches. */
  searchOptions: Required<SearchOptions>;
  /**
   * Whether `sortState`/`filterState`/`joinOperator`/`searchText` are controlled (their sync prop
   * was defined on the last `_syncProps`), set once per sync and read by `toggleSort`/`setSorts`/
   * `setFilters`/`setJoinOperator`/`setSearch` (server override). Controlled mode:
   * the action still fires its `onXChange` callback but does NOT write the corresponding state
   * field itself — `_syncProps` is the only writer once the consumer's prop (and thus the store)
   * actually changes, standard controlled-input semantics (a callback-ignoring consumer's grid
   * stays visually fixed).
   */
  sortControlled: boolean;
  filterControlled: boolean;
  joinOperatorControlled: boolean;
  searchControlled: boolean;
  /** Every cell matching `searchText`, view-index row-major order; computed once per `setSearch`/`_syncProps`/`setSorts`/`setFilters`, capped at 1000 hits with early exit. */
  searchMatches: SearchMatch[];
  /** `searchMatches` as a `"${viewRow}:${columnId}"` Set for O(1) per-cell highlight lookup ({@link useDataGridIsSearchMatch}). */
  searchMatchSet: ReadonlySet<string>;
  /**
   * `searchMatches` grouped by view row -> matched column indices, for {@link computeRowCellState}'s
   * per-row derivation (the previous per-row `for` loop over every visible
   * column, each doing a `searchMatchSet.has(`${row}:${columnId}`)` string-key lookup, cost ~44ms/2000
   * ticks at 100k rows/8 cols with an active search — measured 29x faster building this map once per
   * search-text change and doing an O(1) `Map.get` per row per tick instead).
   */
  searchMatchRows: ReadonlyMap<number, ReadonlySet<number>>;
  /** True when `searchMatches` hit the 1000-match cap (more matches exist but weren't collected). */
  searchMatchesCapped: boolean;
  /** Recomputed by _syncProps/toggleSort/setSorts/setFilters only — search no longer affects it. */
  viewIndex: number[];
  /**
   * Bumped at every row-moving or row-replacing write (insert/delete/duplicate/reorder, a
   * consumer `data` replacement) — the rowId↔dataIndex mapping changed; value-only writes never
   * bump. `useDataGridRowIdToViewRow` keys on this instead of `data` so a streaming tick skips the
   * O(n) map rebuild. Relies on `getRowId` returning stable ids across value-only writes (ids are
   * identity, not content) — the same invariant the rowId index cache holds.
   */
  rowIdentityVersion: number;
  /**
   * True when at least one deferred `updateCells`/`updateRows` batch changed a value that the active
   * sort or filter reads, so the displayed order no longer matches the data. Drives a "re-sort"
   * affordance; `reconcileView()` (or any sort/filter/search change) clears it. See
   * {@link useDataGridViewStale}.
   */
  viewStale: boolean;
  /** Recomputed by _syncProps/setColumnOrder-ish actions that touch order/visibility. */
  visibleColumns: readonly AnyColumnDef[];
  /**
   * Imperative scroll-into-view, registered by the mounted `DataGridRoot` (null before mount/after
   * unmount). Lets add-ons outside the root's subtree (e.g. `data-grid-toolbar`'s search, which sits
   * as a `DataGridRoot` sibling) move the viewport without reaching into
   * root-internal refs. See {@link useDataGridScrollToCell}.
   */
  scrollToCellImpl: ((coord: ViewCoord) => void) | null;
  /** DOM focus for the active cell's element, or the grid when that element is not rendered; registered by the mounted `DataGridRoot`, like `scrollToCellImpl`. */
  focusImpl: (() => void) | null;
  /**
   * The autosize measure context the mounted `DataGridRoot` registers (fonts, mounted row
   * window, header-menu flag) — `null` before mount/after unmount, when
   * {@link DataGridActions.autosizeColumns} measures nothing.
   */
  measureFonts: (() => AutosizeMeasureContext | null) | null;
  /** @internal The data-write cluster's mutable context box (see `data-write.ts`); exposed here so the `useDataGridScrollToCell` ref resolution shares its row-index cache and stale-ref warn flag. */
  dataWrite: DataWriteContext;
  /**
   * The `readOnly` sync prop, defaulted to `false`: editing and delete are disabled grid-wide,
   * independent of any per-column `readOnly`. Seeded from the provider's init props (SSR and the
   * first client paint already see it) and kept in sync by the config phase, so a flip to `true`
   * is live before the next event; every reader (root `aria-readonly`, interaction, clipboard,
   * context menu) goes through this field.
   */
  readOnly: boolean;
  /**
   * The effective keymap — `DEFAULT_KEYMAP` merged with the `keymap` sync prop — seeded at store
   * creation and kept in sync by the config phase, the single source of truth for bindings
   * (backing the `data-grid-keybindings` add-on). Keeps its reference while the prop's entries
   * are content-equal (see `keymapContentEqual`). `DEFAULT_KEYMAP` when no prop is passed.
   */
  keymap: Keymap;
  /** The merged command map: `DEFAULT_KEYMAP`'s pluggable bodies replaced by the plugins' and the consumer's `commands` (plugins in array order, the consumer last and silently winning). `null` when no plugin or consumer command exists. */
  commands: Record<string, GridCommand<unknown>> | null;
  /** {@link DEFAULT_LABELS} deep-merged with the `labels` sync prop; see {@link useDataGridLabels}. */
  labels: DataGridLabels;
  /** The live-region text of the latest row move (drag, keyboard, or `reorderRows`); empty before the first. */
  rowMoveAnnouncement: string;
  /** The public actions only — the `_`-prefixed internals live in the store-private table ({@link getInternalActions}), never in state. */
  actions: DataGridActions;
};

/** `DataGridStoreState` with `data` typed as `readonly TData[]` — the state view {@link useDataGridSelector} hands its selector. Every row in `data` originated from the grid's own `TData`-typed `data`/`defaultData` prop, so the widening is safe. */
export type DataGridStoreStateOf<TData> = Omit<DataGridStoreState, "data"> & { data: readonly TData[] };

/** Mutations for a single grid instance, nested under the stable `actions` key. */
export type DataGridActions = {
  /**
   * Moves ONLY the active cell, leaving the selection (range, row and column channels) untouched,
   * and fires NO `onSelectionChange` (contrast `selectCell`, which sets a single-cell selection
   * and fires it). After Escape/`clearSelection`, `selection.current` is `null` while `activeCell`
   * still exists — read the active cell from `activeCell`, not from `selection.current.cell`.
   */
   /** Moves the active cell to the cell named by the stable {@link CellRef}; `null` clears it. */
   setActiveCell(ref: CellRef | null): void;
   /** View-index variant of {@link DataGridActions.setActiveCell} for callers that hold a {@link ViewCoord}. */
   setActiveCellAt(coord: ViewCoord | null): void;
   /** Selects the cell named by the stable {@link CellRef} as a single-cell selection. */
   selectCell(ref: CellRef): void;
   /** View-index variant of {@link DataGridActions.selectCell} for callers that hold a {@link ViewCoord}. */
   selectCellAt(coord: ViewCoord): void;
   /** Extends the selection to the cell named by the stable {@link CellRef}. */
   extendTo(ref: CellRef): void;
   /** View-index variant of {@link DataGridActions.extendTo} for callers that hold a {@link ViewCoord}. */
   extendToAt(coord: ViewCoord): void;
   extendSelection(direction: ExtendDirection, opts?: { toEdge?: boolean }): void;
   /** Pushes a ctrl-click range to the cell named by the stable {@link CellRef}. */
   pushRange(ref: CellRef): void;
   /** View-index variant of {@link DataGridActions.pushRange} for callers that hold a {@link ViewCoord}. */
   pushRangeAt(coord: ViewCoord): void;
  selectRow(index: number, opts?: SelectLineActionOptions): void;
  selectColumn(index: number, opts?: SelectLineActionOptions): void;
  selectAll(): void;
  /** Checkbox marker: sets one row's checked state absolutely — never a toggle — independent of the last-highlighted/range mechanics `selectRow` uses for click gestures. Checking adds the row to the rows channel; unchecking removes it from the rows channel and from every cell range that covers it. No-op when `enableRowSelection` is false. */
  setRowSelected(index: number, checked: boolean): void;
  /** Sets the row-drag anchor without touching the rows/columns selection channel — lets a checkbox-marker press arm a potential row-range drag while leaving a stationary click's own toggle untouched. No-op when `enableRowSelection` is false. */
  armRowDragAnchor(index: number): void;
  /** Header marker select-all checkbox: sets every view row's membership in the rows channel at once. No-op when `enableRowSelection` is false. */
  setAllRowsSelected(checked: boolean): void;
  clearSelection(): void;
  /** Clears the cell range and the column channel and keeps the checked rows. */
  clearCellSelection(): void;
  /**
   * Applies a whole selection in stable {@link CellRef} terms, emitting like a gesture (`onSelectionChange`
   * fires when the result differs from the grid's current value): corner refs resolve through the
   * row-index cache plus the view inverse, a range with an unresolvable corner is dropped,
   * unresolvable `rowIds`/`columnIds` are dropped, and an unresolvable or outside anchor resets to
   * `range.start` (dev mode warns once per grid). A value with an `anchor` also moves the active
   * cell to the anchor; `null` clears the whole selection. A single cell stays `selectCell(ref)`.
   */
  setSelection(next: SelectionState | null): void;
  /**
   * Live per-frame width write during a resize drag; fires `onColumnResizing` (not
   * `onColumnLayoutChange` - see `commitColumnWidth` for the commit point). The width is clamped
   * to the column's legal range (`[max(32, minWidth), maxWidth]`, the same bounds the resize
   * gesture enforces); a callback-observed width is the clamped one. An unknown column id is a no-op.
   */
  setColumnWidth(id: string, width: number): void;
  /**
   * Sets the column's width AND fires `onColumnLayoutChange` once — the resize-drag-release/autosize
   * commit point. The width is clamped exactly as {@link setColumnWidth} clamps, and the fired
   * snapshot carries the clamped value. Fires only when the width differs from the last committed
   * one; an unknown column id is a no-op.
   */
  commitColumnWidth(id: string, width: number): void;
  /**
   * Sizes columns to their content over the whole view, not the mounted window: samples
   * `options.sampleRows` view rows (default 1000, clamped to [1, 10000]) evenly strided across
   * the view plus the mounted window's rows, measures each column's cell-type display text with
   * canvas `measureText`, and commits every changed width in ONE write with ONE
   * `onColumnLayoutChange`. Default targets: every visible column while column resizing is
   * enabled and `resizable !== false`; a named hidden, non-resizable, or unknown (dev-warned)
   * column is skipped. Unchanged widths commit nothing and fire no event. Returns the measured
   * widths; `{}` when the grid has no mounted root (nothing measured, nothing written).
   */
  autosizeColumns(options?: AutosizeOptions): Record<string, number>;
  /**
   * Drops a column's width override, restoring its def `width` (and re-joining `flex` distribution
   * — a manually resized flex column leaves it while an override is set). No-op without an
   * override. Fires `onColumnLayoutChange` once, with the override gone from `widths`.
   */
  resetColumnWidth(id: string): void;
  /**
   * Reorders visible columns. `id` moves to sit immediately before/after `targetId` (per `position`).
   * Pinned columns only reorder within their own pin zone (left/right/unpinned) — a cross-zone
   * request is a no-op recompute (dropping a left-pinned column onto the unpinned band does nothing).
   * No-op when the column's own `reorderable: false`, the grid-wide `enableColumnReorder` is false,
   * an id is unknown, or the drop keeps the order. Fires `onColumnLayoutChange` once on an actual move.
   */
  setColumnOrder(id: string, targetId: string, position: "before" | "after"): void;
  /** Pins/unpins a column (`null` = unpinned). No-op when the id is unknown, the column's `pinnable: false`, grid-wide `enableColumnPinning` is false, or the pin already matches. Fires `onColumnLayoutChange` once on a real change. */
  setColumnPin(id: string, pin: "left" | "right" | null): void;
  /**
   * Shows/hides a column via the `hiddenColumns` set; works on a def-level `hidden: true` column
   * — `setColumnHidden(id, false)` re-shows it, and the def's flag re-applies only when a NEW
   * `columns` array is passed (a same-reference re-render keeps the user's choice).
   * No-op when the id is unknown or the visibility already matches; otherwise fires
   * `onColumnLayoutChange` once.
   */
  setColumnHidden(id: string, hidden: boolean): void;
  /**
   * Applies a partial column layout as ONE commit (the imperative twin of the `columnLayout`
   * prop): each given part (`widths`, `order`, `pins`, `hidden`) replaces that part, omitted
   * parts keep the current value. Normalized like `columnLayout` (unknown ids dropped, missing
   * order ids appended in def order, widths clamped, unpinnable pins dropped), and fires
   * `onColumnLayoutChange` once only when the layout actually changed.
   */
  setColumnLayout(parts: Partial<ColumnLayout>): void;
  toggleSort(columnId: string, additive: boolean): void;
  setSorts(sorts: SortSpec[]): void;
  setFilters(filters: FilterSpec[]): void;
  /** Sets how `filterState`'s rows combine ("and" every filter must match, "or" any one does). */
  setJoinOperator(joinOperator: FilterJoinOperator): void;
  /** Sets quick-search text (and, when given, the search options) and recomputes `searchMatches`/`searchMatchSet`/`searchMatchesCapped` once; never touches `viewIndex`. Omitted options keep the current ones. */
  setSearch(text: string, options?: SearchOptions): void;
  /** Enters edit mode at the cell named by the stable {@link CellRef}, cancelling an open session first; no-op when the grid or column is readOnly, or its type is unregistered or declares `activate`. */
  startEditing(ref: CellRef, initialText?: string): void;
  /** View-index variant of {@link DataGridActions.startEditing} for callers that hold a {@link ViewCoord}. */
  startEditingAt(coord: ViewCoord, initialText?: string): void;
  /** Discards the in-progress edit without emitting a change. */
  cancelEditing(): void;
  /**
   * Validates and commits the in-progress edit; rejects (keeps editing, sets editingError) or emits
   * one DataChange and moves activeCell by `movement`. `rejection` is the async validation layer's
   * awaited schema rejection for an `onInvalid: "warn"` column: the commit's sync re-run cannot see
   * a schema Promise's issues, so the layer forwards the message to flag the cell. No-op in a
   * read-only grid.
   */
  commitCellEdit(value: unknown, movement?: { dx: number; dy: number }, rejection?: string): void;
  /** Direct-write path for types with no edit mode (checkbox): validates and commits `value` at the cell named by the stable {@link CellRef} without requiring `startEditing` first, and never moves the active cell. No-op in a read-only grid. */
  commitCellValue(ref: CellRef, value: unknown): void;
  /** View-index variant of {@link DataGridActions.commitCellValue} for callers that hold a {@link ViewCoord}. */
  commitCellValueAt(coord: ViewCoord, value: unknown): void;
  /**
   * Sets `editingError` and bumps `editingRejectionCount` (the editors' commit-guard re-arm
   * nonce) without touching `editing`/`data` — used by the async Standard Schema commit path (see
   * cell.tsx/use-async-validate.ts): an async `validate` resolves AFTER `commitCellEdit` would
   * have run, so the editor-commit layer calls this directly instead of going through the
   * (synchronous) commit action. No-op if editing has since ended (race guard is the caller's
   * job — see the generation counter in use-async-validate.ts).
   */
  setEditingError(message: string): void;
  /**
   * Merges `errors` into `cellErrors` per-key (an existing entry for a cell not named here
   * survives untouched). NOT a data change: no `DataChange`, no history entry, no `onDataChange`
   * echo — see `cellErrors`' doc comment. The typical caller is an `onDataChange` handler's
   * `.catch()` after a server 422, mapping its field errors to `{ rowId, columnId, message }[]`.
   */
  setCellErrors(errors: readonly CellErrorEntry[]): void;
  /** Clears `cellErrors` for `targets`, or every entry when `targets` is omitted. Same non-data-change contract as `setCellErrors`. */
  clearCellErrors(targets?: readonly CellErrorTarget[]): void;
  /**
   * Puts the given cells into a transient ~1.2 s fade pulse (the
   * "highlight-what-changed" effect a fill/paste/move gesture plays on the cells it just wrote).
   * A cell already flashing gets its timer RESET, so overlapping gestures each get the full pulse.
   * NOT a data change — no `DataChange`, no history, no selection movement.
   */
  flashCells(cells: readonly CellRef[], durationMs?: number): void;
  /** Clears every non-readOnly cell in the current selection to its type's clearValue(), as one batch DataChange. */
  deleteSelection(): void;
  /**
   * The one generic multi-cell write path: applies `updates` (view-index coords via `viewRow`) as
   * a single `source`-tagged DataChange batch. Dedupes multiple updates to the same row/column
   * (last write wins), skips readOnly cells and no-op writes, preserves identity of untouched rows,
   * suppresses an empty batch entirely, and moves the selection to cover the touched view rect.
   * With `rejected` present, fires `onValidationError` (same `source`) after the write settles.
   */
  applyCellUpdates(updates: { viewRowIndex: number; columnId: string; value: unknown }[], source: DataChange<unknown>["source"], rejected?: readonly GridBulkValidationError[]): void;
  /**
   * The streaming write path: applies row-id-based {@link CellPatch}es in ONE `set()` and skips the
   * `computeViewIndex`/`computeSearchMatches` rebuild that a `data` prop replacement forces. This is
   * what makes streaming under an active sort viable — a controlled `data` replacement costs ~56 ms
   * per tick at 100k rows with one sort column, against ~0.15 ms here.
   *
   * Unlike `applyCellUpdates` it never moves the selection, the active cell, or the editing session,
   * so a live feed cannot pull the grid out from under a user mid-edit. Emits one batched
   * `{source: "stream"}` `DataChange` through `onDataChange`, in both controlled and uncontrolled
   * mode. See {@link UpdateCellsOptions} for the sort/filter interaction.
   */
  updateCells(patches: readonly CellPatch[], options?: UpdateCellsOptions): UpdateCellsVerdict;
  /** {@link updateCells} keyed by whole row: each {@link RowPatch}'s `changes` expands to one patch per column id. */
  updateRows(updates: readonly RowPatch[], options?: UpdateCellsOptions): UpdateCellsVerdict;
  /** Rebuilds the view index that a deferred `updateCells` postponed, and clears `viewStale`. No-op when the view is not stale. */
  reconcileView(): void;
  /**
   * Inserts one row built by the `createRow` sync prop above/below `viewRowIndex` (view-index).
   * External name that maps to the single internal batch path - it runs
   * {@link insertRows} with count 1, so both share one implementation, one `onDataChange`,
   * and one undo step.
   */
  insertRow(viewRowIndex: number, position: "above" | "below"): void;
  /**
   * Inserts `count` rows built by the `createRow` sync prop (called with `dataRowIndex + i`)
   * above/below `viewRowIndex` (view-index) as ONE `{source: 'row-operation'}` DataChange with one
   * row-id-based `insert` operation per row - a single undo entry. Dev-warning no-op when `createRow` is
   * absent; silent no-op for `count <= 0`.
   */
  insertRows(viewRowIndex: number, count: number, position?: "above" | "below"): void;
  /** Deletes the rows at `viewRowIndexes` (view-index) as one `{source: 'row-operation'}` DataChange with row-id-based `delete` operations. */
  deleteRows(viewRowIndexes: number[]): void;
  /** Deletes the rows with the given ids (the shape `getRowIds()` returns) as one `{source: 'row-operation'}` DataChange; ids that match no row are skipped. */
  deleteRowsById(rowIds: readonly string[]): void;
  /**
   * Duplicates the rows at `viewRowIndexes` (view-index), inserting each copy directly after its
   * source row, as one `{source: 'row-operation'}` DataChange with row-id-based `insert` operations. Dev-warning
   * no-op when the `duplicateRow` sync prop is absent — required so
   * every duplicated row gets a distinct id, never colliding with its source's React key.
   */
  duplicateRows(viewRowIndexes: number[]): void;
  /**
   * Moves the rows at view indices `rows` (a number or a list) as one block: they keep their
   * relative order and land contiguous, the first at view index `to` (final position — arrayMove
   * semantics for one row). Duplicate indices count once. One `{source: 'row-operation'}` DataChange with one
   * row-id-based `move` operation per moved row, each `from` the index before the batch and each `to` the
   * final index (one undo entry; apply the operations together, never one by one). No-ops (silent, dev-warned where the cause is a misconfiguration): `enableRowReorder`
   * off, readOnly, an open edit session (the editor pins a view coordinate the move would
   * invalidate), an active sort/filter (the view order is owned by the sort/filter, not the data),
   * unloaded (lazy) rows (a reorder would shift the lazy add-on's index bookkeeping), and a drop
   * that leaves the rows where they already are, an empty list, and an out-of-range index or `to`.
   * Returns `true` when rows moved, `false` for any no-op — the drag gesture uses the verdict for its a11y announcement.
   */
  reorderRows(rows: number | readonly number[], to: number): boolean;
  /**
   * Shifts every row at view indices `rows` by `delta` and keeps the gaps between them (the keyboard
   * move). Same change shape, guards, and return value as {@link reorderRows}; the whole batch stays put
   * when any row would leave the grid.
   */
  moveRowsBy(rows: readonly number[], delta: number): boolean;
  /**
   * The single generic data-write action: applies a whole {@link DataChange} (a consumer-built operation
   * batch or a history-inverted one) in ONE write and emits `onDataChange` EXACTLY ONCE - one undo
   * entry in the history add-on - like a gesture. Operations resolve by row id through `applyChange`: an
   * operation whose row is gone is skipped silently, and a batch where no operation applies writes and emits
   * nothing. Row-moving operations (insert, delete, move) run the row-operation view bookkeeping - full view
   * rebuild, `rowIdentityVersion` bump, and the row channel and the active cell follow their
   * records - while an update-only batch keeps the selection and cursor as-is (the rebuild only
   * re-orders rows under an active sort). Cell errors clear for the written cells, and errors of
   * removed rows are pruned. No-op on a `readOnly` grid. A `source: "history"` or `"rollback"` change is a
   * pass-through: the history stack ignores it, so an undo, redo, or rollback applied through this action
   * records no second entry. Values are NOT revalidated - that is `updateCells`' job; build import
   * rows validated (the io add-on does it) and undo/redo reverts to previously applied states.
   */
  commitChange(change: DataChange<unknown>): void;
};

/** @internal The `_`-prefixed store actions that the core and add-on wiring call; `useDataGridActions` never returns them. */
export type DataGridInternalActions = {
  /**
   * @internal Clears every `rowIds` x `columnIds` cell still in view, as one `delete` batch. Cut
   * captures the ids at copy time, so a view change during the clipboard write never shifts the
   * cleared cells. Not part of the public hook surface.
   */
  _deleteCellsById(rowIds: readonly string[], columnIds: readonly string[]): void;
  /** @internal keyboard nav helper: moves/extends the active cell by a view-index delta, clamped to view bounds. */
  _moveActiveCell(d: { dx: number; dy: number }, opts?: { extend?: boolean; retain?: boolean }): void;
  /** @internal syncs live consumer props and recomputes derived state; not part of the public hook surface. */
  _syncProps(props: InternalSyncProps): void;
  /**
   * @internal Syncs the config slice (every sync prop that feeds no derived state: `readOnly`,
   * `keymap`, the `enable*` flags, `rowMarkers`, `headerClickBehavior`, `labels`, `plugins`,
   * `commands`, `autosizeOnMount`, and every `on*`/`process*`/`validateRow`/
   * `createRow`/`duplicateRow` callback) into the store, run from the provider's layout effect so
   * a `readOnly` flip is live before the browser paints or dispatches the next event. A changed
   * `plugins` list or `keymap` re-resolves and re-merges (the keymap then runs the dev-only binding
   * validation); a `readOnly` flip on cancels an open edit session. Not part of the public hook
   * surface.
   */
  _syncConfig(props: InternalSyncProps): void;
  /**
   * @internal Claims the current `plugins` list for this store from a mount effect (a plugin
   * instance attaches to one live grid; a plugin another grid holds is dropped and dev-warned) and
   * re-claims when the list changes. Not part of the public hook surface.
   */
  _syncPluginClaims(): void;
  /** @internal Frees this store's plugin claims on unmount. Not part of the public hook surface. */
  _releasePluginClaims(): void;
  /**
   * @internal The provider subscribes after its `onActiveCellChange` wiring: fires `onEditEnd`
   * `cancel` when a session ends outside commit/cancel (remap, stale-anchor discard, direct store
   * write). Returns the unsubscribe. Not part of the public hook surface.
   */
  _subscribeEditEnd(): () => void;
  /**
   * @internal The provider subscribes after its `onActiveCellChange` wiring: fires
   * `onSelectionChange` with the derived {@link SelectionState} when `state.selection`'s identity
   * changes and the derived value differs structurally from the last emitted/applied value.
   * Returns the unsubscribe. Not part of the public hook surface.
   */
  _subscribeSelection(): () => void;
  /** @internal Derives the current selection's public {@link SelectionState} on demand (`api.getSelection()`). Not part of the public hook surface. */
  _deriveSelection(): SelectionState;
  /** @internal `DataGridRoot` registers/clears its scroll-into-view on mount/unmount; not part of the public hook surface. */
  _registerScrollToCell(impl: ((coord: ViewCoord) => void) | null): void;
  /** @internal `DataGridRoot` registers/clears its DOM focus on mount/unmount; not part of the public hook surface. */
  _registerFocus(impl: (() => void) | null): void;
  /** @internal `DataGridRoot` registers/clears its autosize measure context (fonts, mounted row window, header-menu flag) on mount/unmount; `autosizeColumns` reads it lazily. Not part of the public hook surface. */
  _registerMeasureFonts(impl: (() => AutosizeMeasureContext | null) | null): void;
  /**
   * @internal Drops the flash keys whose row left `keptViewRows` (the body's rendered window),
   * so a cell that scrolls out and back in never replays its one-shot pulse. Not part of the
   * public hook surface.
   */
  _pruneFlashingCells(keptViewRows: readonly number[]): void;
};

/** Full store shape: interaction state + the stable actions object. */
export type DataGridStore = DataGridStoreState;

/**
 * Everything `computeViewIndex`/`computeSearchMatches`/`computeVisibleColumns` read on a
 * `_syncProps` sync, captured by reference. All fields `===`-equal to the previous sync's means
 * their outputs (`viewIndex`/`searchMatches`/`visibleColumns`) are also unchanged, so `_syncProps`
 * can skip recomputing them and reuse the previous references (a controlled parent re-rendering
 * for unrelated reasons — e.g. its own local state — shouldn't pay full buildViewIndex cost).
 */
export type SyncInputs = {
  data: readonly unknown[];
  columns: readonly AnyColumnDef[];
  /** Sort reads each column's cell-type `compare`, so a swapped registry changes `viewIndex`. */
  cellTypes: Record<string, CellType>;
  sortState: SortSpec[];
  filterState: FilterSpec[];
  joinOperator: FilterJoinOperator;
  searchText: string;
  columnOrder: string[] | null;
  hiddenColumns: readonly string[];
  columnGroupModel: ColumnGroupModel | null;
};

export function syncInputsEqual(a: SyncInputs, b: SyncInputs): boolean {
  return (
    a.data === b.data &&
    a.columns === b.columns &&
    a.cellTypes === b.cellTypes &&
    a.sortState === b.sortState &&
    a.filterState === b.filterState &&
    a.joinOperator === b.joinOperator &&
    a.searchText === b.searchText &&
    a.columnOrder === b.columnOrder &&
    a.hiddenColumns === b.hiddenColumns &&
    a.columnGroupModel === b.columnGroupModel
  );
}

/** Result of a successful direct-write commit; `null` state fields mean "leave editing/editingError untouched". */
/**
 * `warnings` (only on the success/noop arms) carries `onInvalid: "warn"` rejections that committed
 * anyway — the store merges them into `cellErrors` AFTER the gesture's auto-clear and `validateRow`
 * verdict, so the freshest per-cell signal wins.
 */
export type CommitResult =
  | { data: readonly unknown[]; change: DataChange<unknown>; warnings?: readonly CellErrorEntry[] }
  | { error: string }
  | { noop: true; warnings?: readonly CellErrorEntry[] };

/** Per-row accumulator: the row as edited so far, plus its per-column cell deltas (columnId -> entry). */
export type RowEdit = { row: unknown; cells: Map<string, { columnId: string; value: unknown; prev: unknown }> };

/**
 * The `store` branch of {@link DataGridProviderProps}/{@link DataGridProps}: a consumer-created
 * store is passed ALONE — any sync prop next to it would be silently ignored (the owner's
 * `useDataGridStoreProps` call drives the store), so the mapped-`never` makes it a type error.
 * Dev mode warns once when an untyped (cast) caller passes both anyway.
 */
export type ExternalStoreProps = { store: StoreApi<DataGridStoreState> } & {
  [K in keyof DataGridSyncProps<unknown>]?: never;
};
/** The owned-store branch of {@link DataGridProviderProps}/{@link DataGridProps}: this instance self-creates and syncs the store from the sync props. */
export type OwnedStoreProps<TData> = DataGridSyncProps<TData> & { store?: undefined };

/** Props for {@link DataGridProvider}. */
export type DataGridProviderProps<TData = unknown> = (ExternalStoreProps | OwnedStoreProps<TData>) & {
  children: ReactNode;
  /** Receives the grid's imperative handle ({@link DataGridApi}), the same object `useDataGridApi` returns under this provider. */
  ref?: Ref<DataGridApi<TData>>;
  /**
   * A consumer-created store (from `useDataGridStoreProps`) to serve to the subtree instead
   * of self-creating one. When set, the provider becomes a pure context shell: no store
   * creation, no prop sync, no subscription wiring — the owner's `useDataGridStoreProps` call
   * drives the store and must pass the same live props; pass the store ALONE (see
   * {@link ExternalStoreProps} for why sync props next to it are a type error).
   */
  store?: StoreApi<DataGridStoreState>;
};

/** {@link useDataGridCellState}'s return shape — the 5 primitives `DataGridCell` reads every render. */
export type DataGridCellState = {
  isActive: boolean;
  /** True for any selected cell (active cell, inside the primary range/range stack, or its row/column channel) — drives `aria-selected` (WAI-ARIA grid pattern: every selected cell reports it, not just the focused one). */
  isSelected: boolean;
  isEditing: boolean;
  initialText: string | undefined;
  /** The open edit session's id when `isEditing`; a new id means a new session, even on the same cell. */
  editSession: number | undefined;
  isSearchMatch: boolean;
  /** This cell's `cellErrors` message, or null when it has none — same visual language as a sync `validate` rejection. */
  cellError: string | null;
};

/**
 * {@link useDataGridRowCellState}'s return shape — one row's worth of interactive cell state,
 * derived ONCE per row instead of once per cell. `selectedColRanges` is a rectangle-based summary
 * (a row's selected columns are a small union of `[start,end)` runs), so it stays cheap to compute
 * and to compare by content.
 */
export type DataGridRowCellState = {
  /** The active cell's column in this row, or null if the active cell isn't in this row. */
  activeCol: number | null;
  /** The editing cell's column in this row, or null if editing isn't happening in this row. */
  editingCol: number | null;
  /** Only set when `editingCol` is non-null (mirrors {@link useDataGridCellState}'s per-cell scoping). */
  editingInitialText: string | undefined;
  /** The open edit session's id; only set when `editingCol` is non-null. */
  editingSession: number | undefined;
  /** Every column index in this row matching the current search, or null when search is inactive/no row match — null (not an empty Set) lets a row with no matches skip allocating one. */
  searchMatchCols: ReadonlySet<number> | null;
  /** This row's errored columns (column index -> message), or null when this row has none — same zero-render contract as `searchMatchCols`. */
  errorCols: ReadonlyMap<number, string> | null;
  /** This row's currently-flashing columns (transient write-pulse keys), or null when none — same zero-render contract as `searchMatchCols`. */
  flashingCols: ReadonlySet<number> | null;
  selectedColRanges: readonly ColRange[];
};

import type { ComponentType, FC, ReactNode } from "react";
import type { KeyBinding } from "./keyboard/key-syntax";
import type { AnyColumnDef, DataGridActions, DataGridStoreState } from "./store/types";
import type { RowBandRenderCtx } from "./layout-context";
import type { OverlayPluginCtx } from "./overlays";

export type { KeyBinding };

/**
 * Vendored from `@standard-schema/spec` v1 (https://github.com/standard-schema/standard-schema) so
 * shipped registry code has zero runtime/type dependency on the package — the spec is
 * frozen at version 1, so drift risk is ~nil; a type-level conformance test (data-grid.type-test.ts)
 * asserts this vendored copy stays assignable to/from the real package's type in both directions,
 * so any future drift fails `tsc` instead of silently diverging. `@standard-schema/spec` is still a
 * repo devDependency (types-only, for that conformance test) — never imported by shipped code.
 */
export type StandardSchemaV1<Input = unknown, Output = Input> = {
  /** The Standard Schema properties. */
  readonly "~standard": StandardSchemaV1Props<Input, Output>;
};

interface StandardSchemaV1Props<Input = unknown, Output = Input> {
  /** The version number of the standard. */
  readonly version: 1;
  /** The vendor name of the schema library. */
  readonly vendor: string;
  /** Validates unknown input values. */
  readonly validate: (value: unknown) => StandardSchemaV1Result<Output> | Promise<StandardSchemaV1Result<Output>>;
  /** Inferred types associated with the schema. */
  readonly types?: StandardSchemaV1Types<Input, Output> | undefined;
}

/** Result of one `"~standard".validate()` call: `issues` set means failure, never thrown. */
export type StandardSchemaV1Result<Output> = StandardSchemaV1SuccessResult<Output> | StandardSchemaV1FailureResult;

interface StandardSchemaV1SuccessResult<Output> {
  /** The typed output value. */
  readonly value: Output;
  /** A falsy value for `issues` indicates success. */
  readonly issues?: undefined;
}

interface StandardSchemaV1FailureResult {
  /** The issues of failed validation. */
  readonly issues: ReadonlyArray<StandardSchemaV1Issue>;
}

/** One validation failure; cell values are scalars so `path` (when present) is a flat dot-joined prefix. */
export interface StandardSchemaV1Issue {
  /** The error message of the issue. */
  readonly message: string;
  /** The path of the issue, if any. */
  readonly path?: ReadonlyArray<PropertyKey | StandardSchemaV1PathSegment> | undefined;
}

interface StandardSchemaV1PathSegment {
  /** The key representing a path segment. */
  readonly key: PropertyKey;
}

interface StandardSchemaV1Types<Input = unknown, Output = Input> {
  /** The input type of the schema. */
  readonly input: Input;
  /** The output type of the schema. */
  readonly output: Output;
}

// Namespace-merged onto the `StandardSchemaV1` type (matching the official package's own
// declaration, and how consumers write `StandardSchemaV1.InferInput<S>`) — not a general-purpose
// namespace, so the lint rule's usual "prefer ES modules" concern doesn't apply here.
// eslint-disable-next-line @typescript-eslint/no-namespace
export namespace StandardSchemaV1 {
  /** Infers the input type of a Standard Schema. */
  export type InferInput<Schema extends StandardSchemaV1> = NonNullable<Schema["~standard"]["types"]>["input"];
  /** Infers the output type of a Standard Schema. */
  export type InferOutput<Schema extends StandardSchemaV1> = NonNullable<Schema["~standard"]["types"]>["output"];
}

// `keyof TData & string` alone resolves to `never` (not `string`) when TData=unknown — unlike
// `never`, where `keyof never` is the universal key type `string | number | symbol` — so the
// erasure boundary's `ColumnDef<unknown, ...>` (see store.tsx's AnyColumnDef) needs this special
// case, else `accessorKey` collapses to an uninhabited `undefined` field.
export type AccessorKeyOf<TData> = unknown extends TData ? string : keyof TData & string;

/** Cell coordinate in view-index: 0-based view row (sorted/filtered, not a data index) and 0-based visible-column index (marker columns excluded). It reshuffles under sort and filter — never persist it or compare it across a reorder; address cells by {@link CellRef} instead. */
export type ViewCoord = { col: number; row: number };

/** Stable cell identity: the row's `getRowId()` value plus the column's id. Survives sort, filter, and reorder — the coordinate for actions and the identity the cell ctx hands out. A ref whose row is not in the current data (filtered out, paged away, deleted) or whose column is hidden does not resolve: the action is a no-op, and dev mode warns once per grid. */
export type CellRef = { rowId: string; columnId: string };

/** A {@link CellRef} plus the view-index position the cell occupied when the event fired. */
export type ViewCellRef = CellRef & {
  /** The view (display) row index at fire time. */
  viewRowIndex: number;
  /** The view (display) column index at fire time. */
  viewColumnIndex: number;
};

/** How the quick search compares text: `matchCase` (default `false`) respects letter case, `wholeCell` (default `false`) matches only cells equal to the search text. */
export type SearchOptions = { matchCase?: boolean; wholeCell?: boolean };

/** The two opposite corners of a rectangular selection; either diagonal order is accepted on resolve. */
export type CellRange = { start: CellRef; end: CellRef };

/**
 * The grid's selection in stable {@link CellRef} terms: the primary range with its anchor, the
 * ctrl-click range stack, and the whole-row/whole-column channels. The active cell is
 * deliberately not part of it — it moves on every arrow key, and controlling it would push every
 * keystroke through the consumer's render; it stays uncontrolled with `onActiveCellChange`.
 * `anchor` may lie inside the range (Ctrl+A puts the active cell as the anchor inside the
 * region); a resolved anchor outside its range resets to `range.start`.
 */
export type SelectionState = {
  /** The primary range's anchor (Excel's white cell), or `null` when there is no primary range. */
  anchor: CellRef | null;
  /** The primary range; `null` when only the row/column channels (or nothing) are selected. */
  range: CellRange | null;
  /** Earlier ctrl-click ranges, oldest first. */
  rangeStack: readonly CellRange[];
  /** Row ids of the row channel, in view order. */
  rowIds: readonly string[];
  /** Column ids of the column channel, in view order. */
  columnIds: readonly string[];
};

/** What a marker mode renders: the 1-based view row index, the row-select checkbox, or both (number swapped for the checkbox on hover/selected). */
export type RowMarkersContent = "number" | "checkbox" | "both";

/**
 * Marker column mode: a pinned-left column rendered BEFORE all data columns, outside the data
 * column index space (ViewCoord.col / aria-colindex / aria-colcount are all untouched by it).
 * The plain modes (`number`/`checkbox`/`both`) render the selection chrome only and keep the
 * marker a pure row-select surface — a drag there is always the row-range select. The
 * `reorder`-prefixed family renders the drag handle on top of the suffix's content and is the
 * ONLY family that arms the drag-to-reorder gesture (still gated grid-wide by `enableRowReorder`),
 * and the press ZONE decides the gesture: the drag handle zone reorders on drag and never changes the selection, while the checkbox glyph and the number/rest of the cell stay pure row-select.
 */
export type RowMarkersMode = "none" | RowMarkersContent | "reorder" | `reorder-${RowMarkersContent}`;

/** Rectangular cell region, half-open on the far edge (a cell c is inside if x <= c < x + width). */
export type GridRect = { x: number; y: number; width: number; height: number };

/**
 * Selection model.
 * `cell` is the anchor (Excel's white cell) and is always inside `range`.
 * `rangeStack` holds additional rectangles from ctrl-click multi-range; never contains `range`.
 * `rows`/`columns` are whole-row/column selection channels, distinct from `current`.
 */
export type GridSelection = {
  current: {
    cell: ViewCoord;
    range: GridRect;
    rangeStack: GridRect[];
  } | null;
  rows: CompactSelectionLike;
  columns: CompactSelectionLike;
};

/** Structural interface of CompactSelection so types.ts stays dependency-free. */
export type CompactSelectionLike = {
  readonly length: number;
  hasIndex(index: number): boolean;
  /** Content equality over both members' runs, independent of internal slice layout. */
  equals(other: CompactSelectionLike): boolean;
  hasAll(range: [number, number]): boolean;
  toArray(): number[];
};

/**
 * Selection-gesture configuration. All default `true`.
 * Disabling a channel removes both its gestures (header/marker click, drag) AND its selection
 * channel: e.g. `enableColumnSelection: false` makes header clicks a no-op, not just un-rendered.
 */
export type SelectionConfig = {
  enableRowSelection: boolean;
  enableColumnSelection: boolean;
  enableRangeSelection: boolean;
  enableMultiRange: boolean;
};

/** One data mutation. Operations are row-id-based so history survives sort/filter (never index-keyed). */
export type DataOp<TData> =
  | {
      type: "update";
      rowId: string;
      row: TData;
      prev: TData;
      /** Per-cell detail when known (cell edits, paste, fill); absent for whole-row updates. */
      cells?: { columnId: string; value: unknown; prev: unknown }[];
    }
  | { type: "insert"; rowId: string; row: TData; index: number }
  | { type: "delete"; rowId: string; row: TData; index: number }
  | {
      type: "move";
      rowId: string;
      row: TData;
      /** The row's position before the move. */
      from: number;
      /** The row's position after the move (final index; `applyChange` deletes by id and places the row at output slot `to`, `invertChange` swaps `from`/`to`). */
      to: number;
    };

/** One user gesture = one batch (a paste, a fill, a delete-range is a single entry). */
export type DataChange<TData> = {
  ops: DataOp<TData>[];
  /**
   * Origin of the change, for history labeling and consumer filtering. `"stream"` tags a
   * `updateCells`/`updateRows` batch; `useDataGridHistory` drops it by default, because a
   * 100-updates/s feed would evict the user's whole undo stack in seconds. `"app"` tags an
   * imperative `record()` entry (a programmatic change the consumer applied itself).
   * `"replace"` tags a find-and-replace batch (an `updateCells` call the `data-grid-find-replace` add-on makes); `useDataGridHistory` records it.
   * `"history"` tags an undo or redo; `"rollback"` tags `useDataGridHistory().rollback`, which reverts a
   * change whose save failed. Neither is recorded, so a server-sync handler can skip undo and redo
   * and still send a rollback (or the reverse).
   */
  source: "edit" | "paste" | "fill" | "delete" | "row-operation" | "import" | "history" | "rollback" | "stream" | "replace" | "app";
  /** Optional human-readable label for this entry (e.g. "Batch save rollback"); carried through the undo/redo stack as-is. */
  label?: string;
};

export type CellRenderProps<TData, TValue, TOptions = unknown> = {
  /** The resolved cell value (through the column's `accessorKey`/`accessorFn`). */
  value: TValue;
  /** The full data row this cell belongs to. */
  row: TData;
  /** The row's `getRowId()` value — stable row identity (see {@link CellRef}). */
  rowId: string;
  /** The column's id. With `rowId`, addresses this cell stably. */
  columnId: string;
  /** Display (view-index) row index: the sorted/filtered position, matching what the user sees. NOT a stable index into `data` — it reshuffles under sort and filter. */
  viewRowIndex: number;
  /** The column's `options`, typed through `TOptions` (your declared options type) when the cell type is parameterized with it. */
  options?: TOptions;
  // `column`'s own validate erases independently (3rd param `any`) — same reasoning as
  // CellClassNameCtx.column below; without it, renderCell's own bivariance gets re-poisoned by
  // validate's union whenever TValue is erased to `unknown` at the array-common-type boundary.
  column: ColumnDef<TData, TValue, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  /** True while this cell is the active cell. */
  isActive: boolean;
};

/** Context passed to the grid-level {@link ColumnDef}-agnostic `getCellClassName` prop. */
export type CellClassNameCtx<TData, TValue> = {
  value: TValue;
  row: TData;
  /** The row's `getRowId()` value — stable row identity (see {@link CellRef}). */
  rowId: string;
  /** The column's id. With `rowId`, addresses this cell stably. */
  columnId: string;
  // `column`'s own validate erases independently (3rd param `any`) so THIS type's bivariance
  // (recovered via CellClassNameFnHolder below) doesn't get re-poisoned by validate's union when
  // TValue itself is erased to `unknown` at the array-common-type boundary — see types.ts's
  // ColumnDef.validate doc and store.tsx's AnyColumnDef doc for the full reasoning.
  column: ColumnDef<TData, TValue, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  /** Display (view-index) row index — the sorted/filtered position, matching what the user sees. */
  viewRowIndex: number;
};

/**
 * Grid-level row class callback; merged via `cn()` after the
 * built-in row classes. `viewRowIndex` is the display (sorted/filtered) position. Pass a stable
 * function identity (module scope, or memoized) — like `columns`/`data`, its identity is a dev-mode
 * guardrail (unstable identity defeats row memoization) rather than a fresh per-render prop.
 */
export type GetRowClassName<TData> = (row: TData, viewRowIndex: number) => string | undefined;

/** Grid-level cell class callback; same stable-identity guidance as {@link GetRowClassName}. */
export type GetCellClassName<TData> = (ctx: CellClassNameCtx<TData, unknown>) => string | undefined;

/** Context passed to `onCellClick`. Same shape as {@link CellClassNameCtx} plus the column's real index (not just its view row). */
export type CellClickCtx<TData, TValue> = {
  value: TValue;
  row: TData;
  column: ColumnDef<TData, TValue>;
  /** The row's `getRowId()` value — stable row identity (see {@link CellRef}). */
  rowId: string;
  /** The column's id. With `rowId`, addresses this cell stably. */
  columnId: string;
  /** Display (view-index) row index — matches {@link CellClassNameCtx.viewRowIndex}. */
  viewRowIndex: number;
  /** Data-column index (not the marker column) — matches `ViewCoord.col`. */
  viewColumnIndex: number;
};

/**
 * Fired on a plain click on any non-skeleton, non-pinned-row cell — attached to the cell's own
 * existing DOM click handler (no new subscription; see events-state.mdx). Fires alongside
 * whatever the click already does (select the cell, toggle a checkbox) — it's a pure
 * notification, never a veto point (contrast the `data-grid-fill` add-on's `onFill` veto).
 */
export type OnCellClick<TData> = (ctx: CellClickCtx<TData, unknown>, event: MouseEvent) => void;

/**
 * Fired by `onEditEnd` when an edit session ends or a commit attempt is refused: `commit` after the
 * session closes (data written or no-op), `cancel` when the draft is discarded (Escape, the cell
 * leaving the view, or a new `startEditing` replacing the session), `rejected` when a commit
 * attempt failed validation and the session STAYS OPEN (fired per attempt, alongside the
 * `editingRejectionCount` bump). Each session ends with exactly one `commit` or `cancel`. The
 * committed value is not included — `onDataChange` carries it.
 */
export type GridEditEndEvent = ViewCellRef & { result: "commit" | "cancel" | "rejected" };

/** One cell a bulk write (paste, fill, `updateCells`) refused after validation: the target (stable id plus view position, `-1` outside the view) plus the value that failed and the validator's message. */
export type GridBulkValidationError = { rowId: string; columnId: string; viewRowIndex: number; value: unknown; message: string };

/**
 * Fired by `onValidationError` after a bulk paste, a fill, or an `updateCells` call (`"stream"`, or `"replace"` for a find-and-replace batch)
 * settles, ONLY when at least one cell was rejected — the accepted cells are already applied
 * (their `onDataChange`/`onSelectionChange` fire first). `rejected` lists every refused cell with
 * its validator's message.
 */
export type GridValidationErrorEvent = { source: "paste" | "fill" | "stream" | "replace"; rejected: GridBulkValidationError[] };

/** Fired on a double-click on any non-pinned, non-skeleton cell — a pure notification in the {@link OnCellClick} sense (no veto), fired regardless of readOnly. */
export type OnCellDoubleClick<TData> = (ctx: CellClickCtx<TData, unknown>, event: MouseEvent) => void;

/** Fired when the user right-clicks any non-pinned, non-skeleton cell — a pure notification; the `data-grid-context-menu` add-on listens at the root and is unaffected. */
export type OnCellContextMenu<TData> = (ctx: CellClickCtx<TData, unknown>, event: MouseEvent) => void;

/**
 * Method-shorthand holder purely so {@link ColumnDef.cellClassName}'s function branch can pull its
 * signature via indexed access (`CellClassNameFnHolder<...>["fn"]`) instead of writing the function
 * type directly in the union — a function type embedded straight in a union property is checked
 * contravariantly, but one recovered from a method-shorthand declaration via indexed access keeps
 * that declaration's bivariant check, so a `defineColumns` literal's narrow `TValue`-specific
 * callback stays assignable to `ColumnDef<TData, unknown>` (see column-helpers.type-test.ts).
 */
type CellClassNameFnHolder<TData, TValue> = { fn(ctx: CellClassNameCtx<TData, TValue>): string | undefined };

/**
 * Editor contract, in order: the editor holds its own draft text; `onChange(value)` stashes the
 * CURRENT draft into the grid (this is the only way a value reaches the store); `commit()`
 * validates and applies whatever `onChange` last stashed, then closes the editor and moves the
 * active cell. Calling `commit()` without an `onChange` since the editor opened commits the OLD
 * value (the stash is seeded from it at editor-open, never from your local state); calling
 * `onChange` and never `commit` leaves the edit stranded. `cancel()` discards everything. The
 * built-in editors' `commitText(movement)` helper shows the canonical order: guard, `onChange`,
 * `commit`.
 */
export type CellEditorProps<TData, TValue, TOptions = unknown> = {
  /** The last-COMMITTED value, as it was when the editor opened (seed for your initial draft). NOT your in-progress draft — that lives in your editor's local state. */
  value: TValue;
  /** Initial text seed when editing started by typing (type-to-replace); undefined for Enter/F2. */
  initialText?: string;
  /** The full data row this cell belongs to. */
  row: TData;
  /** The row's `getRowId()` value — stable row identity. */
  rowId: string;
  /** The id of the column being edited. */
  columnId: string;
  /** The column's `options`, typed through `TOptions` (your declared options type) when the cell type is parameterized with it. */
  options?: TOptions;
  // `column`'s own validate erases independently (3rd param `any`) — same reasoning as
  // CellRenderProps.column above.
  column: ColumnDef<TData, TValue, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  /** Stash the current draft. Takes effect on the next `commit` — it never writes the store by itself. */
  onChange: (value: TValue) => void;
  /** Validate and apply the last stashed value, close the editor, and move the active cell by the given delta (Enter = {0,1}, blur/click-away = {0,0}). */
  commit: (movement?: { dx: number; dy: number }) => void;
  /** Discard the edit without emitting a change. */
  cancel: () => void;
  /**
   * True while an async Standard Schema `validate` is awaiting its result for THIS commit attempt
   * (see interaction/use-async-validate.ts) — editing is still open. Built-in editors set their
   * input `readOnly` (not `disabled` — a disabled input can't receive Escape/blur) while pending;
   * a custom editor may ignore this or style it differently. Always `false`/`undefined` for the
   * function form and sync schemas.
   */
  pending?: boolean;
  /**
   * Increments on every rejected commit attempt (sync or async) for this cell, and resets to 0
   * when a new edit session starts. A built-in editor's own one-shot commit guard (see
   * interaction/use-commit-guard.ts) must re-arm on a REJECTION specifically — not on every
   * `pending` transition to false, which also happens on Escape/cancel right before the editor
   * unmounts; re-arming there would let the unmount's own blur event fire a second, stale commit
   * through the now-unguarded path.
   */
  rejectionCount?: number;
};

/**
 * A cell type implements rendering plus the value pipeline that powers copy, paste, fill,
 * delete, and import/export. The pipelines read
 * the value through DIFFERENT surfaces, so one override does not reach all of them:
 *
 * - display (the cell's rendered text) = `toDisplayText` when present, else `toText`.
 * - clipboard copy and export = `toText`, always.
 * - sort = `compare` when the column declares this type, else a numeric-aware locale collation of
 *   the RAW `String(value)` — not of `toText` output.
 * - quick search = `toSearchText` when the type declares it, else `toText`; a column without a
 *   declared type searches `String(rawValue)` (a `select` column searches the choice LABEL; a
 *   `number` with `decimals` searches the rounded value; a `date` with a `displayFormat` searches
 *   the ISO string).
 * - filter = the raw-value predicate (`filter.match`, or the column's own `filterMatch`), else the
 *   built-in text matcher over `String(rawValue)`.
 * - fill (series inference) works on the raw value, not on any text form.
 */
export type CellType<TData = unknown, TValue = unknown, TOptions = unknown> = {
  Cell: FC<CellRenderProps<TData, TValue, TOptions>>;
  Editor: FC<CellEditorProps<TData, TValue, TOptions>>;
  /** Serialize for clipboard/export; quick search uses it when the type declares no `toSearchText`. Filter never uses it — it matches the raw value. */
  toText(value: TValue, options?: TOptions): string;
  /** Optional display-only rendering (e.g. locale-formatted dates); the cell renders `toDisplayText ?? toText`. Clipboard/export always use `toText`. */
  toDisplayText?(value: TValue, options?: TOptions): string;
  /** Parse from paste/import/typing. Must never throw; return clearValue()'s result for garbage. */
  fromText(text: string, options?: TOptions): TValue;
  clearValue(options?: TOptions): TValue;
  isEmpty(value: TValue): boolean;
  /** Sort comparator for this type, given the column's `options`; when absent, sorting falls back to a numeric-aware locale collation of the raw `String(value)` — not of `toText` output. */
  compare?(a: TValue, b: TValue, options?: TOptions): number;
  align?: "left" | "right" | "center";
  /** Tabular-nums cell rendering for the right-aligned digits; number and date declare it. */
  numeric?: boolean;
  /** The quick-search text for a stored value; the default is `toText`. select declares the choice label. */
  toSearchText?(value: TValue, options?: TOptions): string;
  /**
   * Default validation for columns of this type when the column declares no `validate` of its
   * own; same shape as {@link ColumnDef.validate}. Every validation path resolves
   * `column.validate ?? cellType.validate` (single-cell commit, paste, fill, updateCells, import).
   */
  validate?: ((value: TValue, row: TData) => string | null) | StandardSchemaV1<TValue>;
  /**
   * The edit gestures ACTIVATE this cell in place instead of opening an editor: Enter/F2, a
   * stationary click, and double-click commit `activate(value, options)` through `commitCellValue`
   * (no edit session, so `onEditStart`/`onEditEnd` never fire). checkbox declares
   * `(value) => !value`. Absent, the gestures open the editor.
   */
  activate?: (value: TValue, options?: TOptions) => TValue;
  /**
   * Link target for a stored value. The grid routes every result through `safeHref` (http/https/
   * mailto only) before it renders or opens; a type cannot widen the allow-list. `url` declares
   * it; the `openLink` action (alt+Enter), Ctrl+click (Cmd+click on macOS), and middle-click open the safe href.
   */
  href?(value: TValue, options?: TOptions): string | null;
  /** Filter capabilities for this type; each member falls back to the name-derived default when absent. */
  filter?: CellTypeFilter;
};

/** Which built-in value-input widget the filter row renders for a cell type. */
export type CellTypeValueInput = "text" | "number" | "date" | "boolean" | "choices";

/**
 * Props of a custom filter value input (a component in `CellTypeFilter.valueInput`). `value` is a
 * string, an `isBetween` pair, or an `isAnyOf` / `isNoneOf` list, depending on `operator`.
 */
export type FilterValueInputProps = {
  column: AnyColumnDef;
  operator: FilterOperator;
  value: string | [string, string] | string[] | undefined;
  onValueChange: (value: string | [string, string] | string[]) => void;
};

/**
 * Filter capabilities a cell type declares instead of the toolbar's name-derived defaults:
 * `operators` beats the type-name operator table, `match` replaces the built-in text matcher
 * (same raw-value contract as {@link ColumnDef.filterMatch}), and `valueInput` picks the filter
 * row's widget: a built-in one by name, or a component that renders for every operator with a value.
 */
export type CellTypeFilter = {
  operators?: readonly FilterOperator[];
  match?: (value: unknown, filter: FilterSpec) => boolean;
  valueInput?: CellTypeValueInput | ComponentType<FilterValueInputProps>;
};

/**
 * `TValidate` defaults to `TValue` for normal authoring (nothing changes for consumers) but is a
 * SEPARATE type parameter so the store's erasure boundary (`AnyColumnDef`, `DataGridSyncProps.columns`)
 * can instantiate it independently as `any` (not `unknown` — proven necessary, see `validate`'s doc
 * below) while `TValue` (accessorFn/setValue/renderCell/etc.) keeps its real `unknown` erasure and
 * full type safety.
 */
export type ColumnDef<TData, TValue = unknown, TValidate = TValue> = {
  /** Stable identity — never derived from the header label. */
  id: string;
  /**
   * String headers render truncated and get the built-in sort-direction arrow in `sort`
   * header-click mode; a ReactNode header renders as-is and owns its own display (the built-in
   * arrow is NOT appended — embed DataGridSortIndicator inside it when you still want it).
   */
  header: string | ReactNode;
  /** Plain-text header for clipboard/export when `header` is a ReactNode. */
  headerText?: string;
  accessorKey?: AccessorKeyOf<TData>;
  /**
   * Read accessor for computed or derived values. A column with ONLY `accessorFn` (no
   * `accessorKey`/`setValue`) is read-only by construction: edits, pastes, and fills are dropped
   * for it. Pair it with `setValue` to make the computed value writable.
   */
  accessorFn?: (row: TData) => TValue;
  /** Immutable write-back; defaults to spreading `accessorKey`. Required for writability when `accessorKey` is absent. */
  setValue?(row: TData, value: TValue): TData;
  /** Cell type registry key; default "text". */
  type?: string;
  options?: unknown;
  readOnly?: boolean | ((row: TData) => boolean);
  /**
   * Rejects a value: the function form returns an error message (`null` accepts), or any
   * `StandardSchemaV1` for `TValue` (Zod/Valibot/ArkType/...) — detected at the call site via
   * `"~standard" in validate`. A schema's `validate` may resolve async; only the single-cell
   * editor commit path awaits it (see cell.tsx/use-commit-guard.ts), bulk paths (paste/fill/
   * import) treat a Promise result as unsupported and skip validation for that cell (dev warn).
   * On success the COMMITTED value is `result.value` (schemas may transform), documented in
   * editing-cell-types.mdx.
   * `TValidate` (not `TValue` directly): a union of a function type and a non-callable schema
   * object, as a plain property, is checked contravariantly as a WHOLE — unlike a pure
   * method-shorthand function, TS can't special-case just the function branch bivariant anymore.
   * That would break `defineColumns`' narrow-`TValue` columns widening into the shared
   * `ColumnDef<TData, unknown>` array every consumer prop uses (verified: it also cascades to
   * OTHER unrelated method-shorthand fields like `renderCell` in the same array literal — TS's
   * structural check on the whole object type gets stricter once ANY sibling property stops being
   * bivariant). Giving `validate` its own type parameter keeps that widening exact (`TValue` never
   * becomes incompatible) while only `TValidate` erases at the store boundary — a documented,
   * narrow, single-field cast (see `AnyColumnDef`), not a project-wide `any`.
   */
  validate?: ((value: TValidate, row: TData) => string | null) | StandardSchemaV1<TValidate>;
  /**
   * What a `validate` rejection does in a single-cell commit. `"block"` (default): the commit is
   * refused — the editor stays open with the message and the value never enters `data`. `"warn"`:
   * the value commits and the cell is flagged in `cellErrors` (same ring/tint/tooltip as server
   * errors, auto-cleared by the next valid commit of that cell). A rejection carries no
   * transformed value, so `"warn"` commits the RAW value; per-row softness is expressed inside the
   * function form via its `row` argument (return `null` to skip the rule for that row). Bulk paths
   * (paste/fill/updateCells) still drop rejected cells even for `"warn"` columns.
   * ponytail: soft bulk commits would need `onInvalid` threaded through resolveBulkWrites/
   * computeCellPatchBatch/prevalidatePatches — add when a soft paste/fill is actually wanted.
   */
  onInvalid?: "block" | "warn";
  /** Rendered width in px; default 150. A resize clamps to `minWidth` and the 32px absolute floor. */
  width?: number;
  minWidth?: number;
  maxWidth?: number;
  /**
   * Proportional share of leftover viewport width. Columns with flex grow from their base
   * `width` to fill positive leftover space; clamped by `maxWidth`. A manual resize fixes the
   * column and removes it from flex distribution.
   */
  flex?: number;
  /** Initial pin direction; change it at runtime through `setColumnPin` or the context menu. Pinned columns only reorder within their own pin zone. */
  pin?: "left" | "right";
  /** Removes the column from click-to-sort (header clicks no longer sort it); programmatic `setSorts`/`toggleSort` still apply. Default true. */
  sortable?: boolean;
  /** Excludes the column from the filter menu's column picker. Existing filter specs on it keep applying. Default true. */
  filterable?: boolean;
  /**
   * Per-column filter predicate that REPLACES the built-in text matcher (`matchesFilter`/
   * `createFilterMatcher`) for this column: it receives the cell's RAW value — not
   * `String(value)` — and the spec, and returns whether the row passes. The built-in matcher runs
   * when this is absent. A thrown result fails the row for that filter.
   */
  filterMatch?: (value: unknown, filter: FilterSpec) => boolean;
  /**
   * The operator list the filter menu offers for this column, replacing the
   * `operatorsForColumnType` default derived from its `type` — e.g. numeric comparison operators
   * for a consumer-registered numeric cell type (`type: "currency"`).
   */
  filterOperators?: readonly FilterOperator[];
  /**
   * Sort comparator over the whole data row (not the cell value), consulted before the column's
   * cell-type `compare` and the default text compare. A non-zero result orders the pair; a zero,
   * NaN, or thrown result defers that pair to the default text compare. `SortSpec` direction and
   * the empty-cell-last rule still apply.
   */
  sortCompare?: (a: TData, b: TData) => number;
  /** Initial visibility; toggle at runtime through `setColumnHidden` or the columns menu. */
  hidden?: boolean;
  /** Disables the resize handle for this column; default true. */
  resizable?: boolean;
  /** Disables drag-to-reorder for this column; default true. */
  reorderable?: boolean;
  /** Disables pin/unpin for this column; default true. */
  pinnable?: boolean;
  /**
   * Display-only override that keeps the column's type pipeline; method-shorthand for the same bivariance reason as `validate`.
   * `props` is a {@link CellRenderProps}: `value`, `row`, `rowId`, `columnId`, `viewRowIndex`, `column`, `options`, and `isActive`.
   */
  renderCell?(props: CellRenderProps<TData, TValue>): ReactNode;
  /**
   * Per-column cell class, merged via `cn()` after the built-in cell classes so it wins on
   * conflicting utilities. A plain string applies to every cell in the
   * column; the function form gets the same per-cell context as the grid-level `getCellClassName`
   * prop (see `CellClassNameFnHolder` for why it's spelled via indexed access, not inline).
   */
  cellClassName?: string | CellClassNameFnHolder<TData, TValue>["fn"];
  /** Per-column header cell class, merged via `cn()` after the built-in header classes. */
  headerClassName?: string;
};

/** Row height presets (px): 'compact' 28, 'default' 36, 'comfortable' 44; the `rowHeight` prop overrides any of these. */
export type DensityMode = "compact" | "default" | "comfortable";

/**
 * How a plain header click behaves. `'select'` (default) selects the whole
 * column, matching the marker/row-selection model. `'sort'` cycles asc->desc->none on the
 * clicked column instead (shift+click adds it to a multi-sort); `'none'` disables both.
 */
export type HeaderClickBehavior = "select" | "sort" | "none";

export type SortSpec = { columnId: string; direction: "asc" | "desc" };

export type FilterOperator =
  | "contains"
  | "notContains"
  | "equals"
  | "notEquals"
  | "startsWith"
  | "endsWith"
  | "empty"
  | "notEmpty"
  | "gt"
  | "gte"
  | "lt"
  | "lte"
  | "isBetween"
  | "isAnyOf"
  | "isNoneOf";

/** Combines multiple `FilterSpec`s: `"and"` (default) requires every filter to match, `"or"` requires any one. */
export type FilterJoinOperator = "and" | "or";

/**
 * One filter row: `{ columnId: "age", operator: "gt", value: "30" }`. `value` holds text for every operator,
 * numbers and dates included (`"30"`, `"2025-01-31"`); the operators `empty` and `notEmpty` take no value.
 * `value` is a single string for most operators. `isBetween` carries an inclusive `[min, max]`
 * tuple (either bound may be `""` for an open-ended range); `isAnyOf` carries a `string[]` of
 * accepted values and matches when the cell text equals any of them; `isNoneOf` carries a
 * `string[]` of excluded values and matches when the cell text equals none of them (an empty list
 * matches every row). `filterId` is a stable
 * identity for list rendering/updates independent of array position (multiple filter rows on the
 * same column are allowed and meaningful under `"or"`/mixed joins); optional at the input boundary
 * for backward compatibility — the store auto-assigns one when absent (see `genFilterId`).
 */
export type FilterSpec = { filterId?: string; columnId: string; operator: FilterOperator; value?: string | [string, string] | string[] };

/**
 * Named keyboard actions, as an interface so consumers can ADD actions by declaration-merging
 * this interface in their own module (the same path as `GridCellTypes` — the module is
 * `@/components/data-grid/types` for the default install layout):
 * ```ts
 * declare module "@/components/data-grid/types" {
 *   interface GridActions {
 *     saveAll: true;
 *   }
 * }
 * ```
 * A merged name binds through the `keymap` prop and resolves to a `commands` entry
 * ({@link GridCommand}). `typeToReplace` (type-to-replace) has no `DEFAULT_KEYMAP` binding: by
 * default any unbound printable key on an active cell dispatches it (Excel behavior, starting an
 * edit seeded with the typed char). Defining `keymap.typeToReplace` takes the action over
 * exclusively — `["F3"]` remaps the trigger (plain edit start, no char seed); `[]` disables it.
 */
export interface GridActions {
  moveUp: true;
  moveDown: true;
  moveLeft: true;
  moveRight: true;
  moveUpKeepSelection: true;
  moveDownKeepSelection: true;
  moveLeftKeepSelection: true;
  moveRightKeepSelection: true;
  scrollActiveIntoView: true;
  moveRowStart: true;
  moveRowEnd: true;
  jumpUp: true;
  jumpDown: true;
  jumpLeft: true;
  jumpRight: true;
  moveFirstCell: true;
  moveLastCell: true;
  pageUp: true;
  pageDown: true;
  extendUp: true;
  extendDown: true;
  extendLeft: true;
  extendRight: true;
  extendJumpUp: true;
  extendJumpDown: true;
  extendJumpLeft: true;
  extendJumpRight: true;
  extendFirstCell: true;
  extendLastCell: true;
  selectRow: true;
  selectColumn: true;
  selectAll: true;
  toggleRow: true;
  toggleAllRows: true;
  openColumnMenu: true;
  openColumnFilter: true;
  edit: true;
  typeToReplace: true;
  commitDown: true;
  commitUp: true;
  commitRight: true;
  commitLeft: true;
  cancel: true;
  clearContents: true;
  undo: true;
  redo: true;
  fillDown: true;
  fillRight: true;
  insertRowBelow: true;
  insertRowAbove: true;
  duplicateRow: true;
  deleteRows: true;
  moveRowsUp: true;
  moveRowsDown: true;
  openLink: true;
  openFindReplace: true;
}

/** Every named keyboard action — the built-ins of {@link GridActions} plus any the consumer merged in. */
export type GridAction = keyof GridActions;

/** The dialog sections a custom command's `group` places it in (the same sections the keybindings dialog renders; i18n labels live in `labels.keybindings.categories`). */
export type CommandGroup = "navigation" | "selection" | "editing" | "clipboardFill" | "history" | "other";

/**
 * The imperative handle of one grid: the stable actions object, the read-only store, non-reactive
 * state reads, and the two DOM gestures (scroll, focus). Obtain it from `<DataGrid ref>`, from
 * `<DataGridProvider ref>`, or from {@link useDataGridApi} anywhere under the provider.
 */
export type DataGridApi<TData> = {
  /** The same stable object `useDataGridActions` returns (public actions only). */
  actions: DataGridActions;
  /** The read-only store view {@link useDataGridStoreApi} returns: no `setState` — the consumer's writable store is `useDataGridStoreProps` (row-agnostic — `getRow` is the typed read). */
  store: DataGridStoreWrapper;
  /** Scrolls the cell named by the ref into view; a ref that no longer resolves no-ops (dev-warned once per grid). */
  scrollTo(ref: CellRef): void;
  /** Focuses the active cell's element, first scrolling an off-window active cell into view; with no active cell it focuses the grid (whose focus onboarding seeds (0,0)). No-ops while an edit session is open — focusing would blur the editor and commit it. */
  focus(): void;
  /** Starts an edit session at the ref's cell — the same guards as `actions.startEditing`. */
  startEditing(ref: CellRef): void;
  /** Discards the in-progress edit without emitting a change (`actions.cancelEditing`). */
  stopEditing(): void;
  /** A non-reactive snapshot of the current selection in stable {@link CellRef} terms. */
  getSelection(): SelectionState;
  /** Applies the named selection as a whole, emitting like a gesture; `null` clears the whole selection. A single cell stays `actions.selectCell(ref)`. */
  setSelection(next: SelectionState | null): void;
  /** The data row at a view (display) row index — the same read `useDataGridRow` performs, without a subscription. */
  getRow(viewRowIndex: number): TData | undefined;
  /** The row id of every view row, in view order; an unloaded row (a lazy hole) gets its placeholder id, like `useDataGridRowIds`. */
  getViewRowIds(): readonly string[];
};

/**
 * The store state as plugins and the `api.store` handle see it: every state field except the
 * consumer's `on*` event callbacks and the core's internal impl slots. State reads return the
 * store's live objects (`data`, `selection`, `columns`) — they must not be mutated (no copy is
 * made; a copy per read would cost O(n) on the hot path).
 */
export type DataGridReadState = Omit<
  DataGridStoreState,
  | "onDataChange"
  | "onValidationError"
  | "onEditStart"
  | "onEditEnd"
  | "onSortChange"
  | "onFilterChange"
  | "onJoinOperatorChange"
  | "onSearchTextChange"
  | "onColumnLayoutChange"
  | "onColumnResizing"
  | "onSelectionChange"
  | "onActiveCellChange"
  | "onCellDoubleClick"
  | "onCellContextMenu"
  | "onCellClick"
  | "onRenderedRowsChange"
  | "scrollToCellImpl"
  | "focusImpl"
  | "measureFonts"
  | "dataWrite"
>;

/**
 * The read-only store view behind `DataGridApi.store` and `useDataGridStoreApi`: `getState` and
 * `subscribe` only — `setState` does not exist on it. The consumer's writable store (the
 * store-ownership path) is `useDataGridStoreProps`.
 */
export type DataGridStoreWrapper = {
  getState(): DataGridReadState;
  getInitialState(): DataGridReadState;
  subscribe(listener: (state: DataGridReadState, prevState: DataGridReadState) => void): () => void;
};

/**
 * One entry of the `plugins` prop: an add-on that reaches into the grid. Members are optional;
 * `name` is the React key of the plugin's components and its identity — unique per grid (a dev
 * error when two plugins share a name). `Overlay` renders into the overlay layer (after the
 * built-in range layers, before the active-cell ring); `rowBands` contributes to the top/bottom
 * row bands; `onDataChange` observes every data change AFTER the store write and the consumer's
 * `onDataChange`; `commands`/`keymap` join the grid's command and keymap merges; `Mount` renders
 * inside `DataGridRoot` after its children for engine work (pointer handlers, listeners). Array
 * order is precedence and visual order. A plugin object attaches to ONE grid.
 */
export type DataGridPlugin<TData = unknown> = {
  /** Unique per grid: the React key of the plugin's components and its identity in the store. */
  name: string;
  /** A component rendered by `DataGridOverlays` with the overlay ctx (window clamp + pin-zone helpers). */
  Overlay?: ComponentType<OverlayPluginCtx>;
  /** Row-band contribution: which rows land in which band plus the painter. */
  rowBands?: PluginRowBands;
  /** Observes every data change after the store write and the consumer's `onDataChange`; a throwing observer logs and does not stop the others. */
  onDataChange?(next: readonly TData[], change: DataChange<TData>, ctx: DataGridPluginCtx<TData>): void;
  /** This plugin's commands, merged into the grid's command map (the consumer's `commands` win; a built-in action name is dropped unless pluggable). */
  commands?: Record<string, GridCommand<TData>>;
  /** Binds THIS plugin's commands only: an entry naming a command the plugin does not define is dropped, dev-warned; a binding the grid's default keymap or the consumer's `keymap` already uses is dropped, dev-warned. */
  keymap?: Keymap;
  /** A component rendered inside `DataGridRoot` after its children (no props — read the grid through {@link useDataGridApi}). */
  Mount?: ComponentType;
};

/** The row-band contribution of a {@link DataGridPlugin}. */
export type PluginRowBands = {
  /** Rows for the top band (above the first data row); omit for no top band. */
  top?: readonly unknown[];
  /** Rows for the bottom band (below the last data row); omit for no bottom band. */
  bottom?: readonly unknown[];
  /** Paints this plugin's rows of one band; called as a plain function during the root's render — a band that needs state renders a component inside the returned node. */
  render(ctx: RowBandRenderCtx): ReactNode;
};

/** What a {@link DataGridPlugin} `onDataChange` observer receives besides the change. */
export type DataGridPluginCtx<TData = unknown> = {
  /** The grid's imperative handle for the grid the change belongs to. */
  api: DataGridApi<TData>;
};

/** The context a custom command's `run`/`when` receives, built fresh from the live store at dispatch time. */
export type GridCommandCtx<TData = unknown> = {
  /** The grid's imperative handle ({@link DataGridApi}) for the grid being dispatched on. */
  api: DataGridApi<TData>;
  /**
   * The active cell as a stable {@link CellRef}, or `null` when no cell is active. On an unloaded
   * lazy row it is a placeholder ref that `api` cannot resolve.
   */
  cell: CellRef | null;
  /** The view (display) row index of the active cell, or `null` when no cell is active. */
  viewRowIndex: number | null;
  /** The view (display) column index of the active cell, or `null` when no cell is active. */
  viewColumnIndex: number | null;
  /** The data row of the active cell, or `undefined` when none. */
  row: TData | undefined;
  /** The grid's effective `readOnly` flag. */
  readOnly: boolean;
};

/**
 * One consumer-defined keyboard command, bound through the `keymap` prop by name
 * (`commands: { saveAll: {...} }` + `keymap: { saveAll: ["mod+s"] }`). Method-style `run`/`when`
 * keep a consumer's `GridCommand<TData>` assignable to the store's row-agnostic field.
 */
export type GridCommand<TData = unknown> = {
  /** Runs the command when a bound key fires. */
  run(ctx: GridCommandCtx<TData>): void;
  /** Gate: return `false` to ignore the key entirely (no `preventDefault`, no `run`). */
  when?(ctx: GridCommandCtx<TData>): boolean;
  /**
   * When the command dispatches: `"grid"` (default) while no edit session is open; `"editing"`
   * while an edit session is open; `"always"` in both cases. The grid keeps its built-in bindings.
   */
  scope?: "grid" | "editing" | "always";
  /** Keybindings-dialog label; default: `labels.keybindings.actions[name]` or the humanized name. */
  label?: string;
  /** Keybindings-dialog section; default: `"other"`. */
  group?: CommandGroup;
};

/**
 * Key binding string: `mod` = Ctrl (win/linux) / Cmd (mac), `ctrl` = the LITERAL physical Ctrl key
 * on every platform (it bypasses `mod` resolution), plus `shift`, `alt`.
